/* HSK 2 course data */
window.lessonsHSK2 = [{"emoji":"🦆","grammar":[{"title":"Trợ từ 吧 (2) dùng để phỏng đoán","formula":"Câu nghi vấn + 吧？","explain":"吧 đặt cuối câu nghi vấn, diễn tả người nói phỏng đoán, chưa chắc chắn, chờ người nghe xác nhận.","tip":"Đừng nhầm với 吧 rủ rê hay đề nghị đã học ở HSK1, ở đây 吧 đi với câu hỏi phỏng đoán.","examples":"你们就是她的学生吧？ (Nǐmen jiù shì tā de xuéshēng ba?) — Các bạn chính là học sinh của cô ấy phải không? 她唱歌很好听吧？ (Tā chànggē hěn hǎotīng ba?) — Cô ấy hát rất hay phải không? 陈天中是泰国人吧？ (Chén Tiānzhōng shì Tàiguó rén ba?) — Trần Thiên Trung là người Thái Lan phải không?","error":"Không dùng 吧 phỏng đoán trong câu trần thuật, chỉ dùng ở cuối câu nghi vấn."},{"title":"Câu 是……的 nhấn mạnh thông tin","formula":"Chủ ngữ + (是) + thành phần nhấn mạnh + động từ + 的","explain":"Câu 是……的 dùng để nhấn mạnh thời gian, địa điểm, cách thức, người thực hiện hay mục đích của sự việc đã xảy ra. Trong câu khẳng định và câu hỏi có thể lược 是, trong câu phủ định không được lược.","tip":"Muốn nhấn mạnh phần nào thì đặt phần đó giữa 是 và 的.","examples":"我们是来旅游的。 (Wǒmen shì lái lǚyóu de.) — Chúng tôi đến để du lịch. 苹果在哪儿买的？ (Píngguǒ zài nǎr mǎi de?) — Táo mua ở đâu vậy? 我们不是坐出租车去的。 (Wǒmen bú shì zuò chūzūchē qù de.) — Chúng tôi không đi taxi đến đó.","error":"Không lược 是 trong câu phủ định, phải nói 不是……的."},{"title":"Câu kiêm ngữ với 请, 让, 叫","formula":"Chủ ngữ + 请/让/叫 + tân ngữ (làm chủ ngữ) + động từ","explain":"Câu kiêm ngữ gồm hai cụm động từ, tân ngữ của động từ đầu đồng thời là chủ ngữ của động từ sau. Khi động từ đầu là 请, 让, 叫 thì câu diễn tả nhờ người khác làm việc gì.","tip":"Nhớ tân ngữ đứng giữa vừa là đối tượng bị nhờ, vừa là người làm hành động sau.","examples":"我想请你帮个忙。 (Wǒ xiǎng qǐng nǐ bāng ge máng.) — Tôi muốn nhờ bạn giúp một việc. 王老师让我们说中文。 (Wáng lǎoshī ràng wǒmen shuō Zhōngwén.) — Thầy Vương bảo chúng tôi nói tiếng Trung. 妈妈叫孩子们回家。 (Māma jiào háizimen huíjiā.) — Mẹ gọi các con về nhà.","error":"Không bỏ tân ngữ ở giữa, nếu không câu sẽ thiếu người thực hiện hành động sau."}],"han":"她请我们吃了北京烤鸭","natural":["Mạch ý: đón ở sân bay, trò chuyện trên xe, điện thoại của Trần Thiên Trung, nhắn tin kể lại cho thầy Vương.","吧 ở cuối câu hỏi bày tỏ phỏng đoán, khác với 吧 rủ rê hay đề nghị đã học ở HSK1.","Khi nghe, chú ý phân biệt 是……的 nhấn mạnh thông tin nào: thời gian (什么时候到的), mục đích (来旅游的) hay phương thức (坐出租车去的)."],"num":1,"photoPrefix":"h2-1","pinyin":"Tā qǐng wǒmen chī le Běijīng Kǎoyā","structures":[{"han":"你们就是她的学生吧？","pinyin":"Nǐmen jiù shì tā de xuéshēng ba?","meaning":"Các bạn chính là học sinh của cô ấy phải không?","note":"就 nhấn mạnh sự khẳng định, 吧 ở cuối câu hỏi bày tỏ phỏng đoán, người nói chưa chắc chắn."},{"han":"我们是来旅游的。","pinyin":"Wǒmen shì lái lǚyóu de.","meaning":"Chúng tôi đến để du lịch.","note":"Câu 是……的 nhấn mạnh mục đích của hành động, 是 có thể lược trong câu khẳng định."},{"han":"我想请你帮个忙。","pinyin":"Wǒ xiǎng qǐng nǐ bāng ge máng.","meaning":"Tôi muốn nhờ bạn giúp một việc.","note":"Câu kiêm ngữ với 请, tân ngữ 你 vừa là đối tượng của 请 vừa là chủ ngữ của 帮忙."},{"han":"她请我们吃了北京烤鸭。","pinyin":"","meaning":"Chị ấy mời chúng em ăn vịt quay Bắc Kinh.","note":"请...吃 là câu kiêm ngữ, nhấn mạnh hành động mời khách, cũng là câu chủ đề của cả bài."}],"theme":"Đón ở sân bay và vịt quay Bắc Kinh","translation":"Chị ấy mời chúng tôi ăn vịt quay Bắc Kinh","vocab":[{"emoji":"🎯","example":"你们就是她的学生吧？","examplePinyin":"Nǐmen jiù shì tā de xuéshēng ba?","exampleVi":"Các bạn chính là học sinh của cô ấy phải không?","meaning":"chính là, đúng là","pinyin":"jiù","pos":"Phó từ","word":"就"},{"emoji":"🎁","example":"一飞给我打电话了。","examplePinyin":"Yīfēi gěi wǒ dǎ diànhuà le.","exampleVi":"Nhất Phi đã gọi điện cho tôi.","meaning":"cho, vì (ai đó)","pinyin":"gěi","pos":"Giới từ","word":"给"},{"emoji":"🙏","example":"让我来接你们。","examplePinyin":"Ràng wǒ lái jiē nǐmen.","exampleVi":"Để tôi đến đón các bạn.","meaning":"để, cho phép, nhờ","pinyin":"ràng","pos":"Động từ","word":"让"},{"emoji":"🤝","example":"是您姐姐来接的我们。","examplePinyin":"Shì nín jiějie lái jiē de wǒmen.","exampleVi":"Chính chị gái của thầy đã đến đón chúng em.","meaning":"đón, đón tiếp","pinyin":"jiē","pos":"Động từ","word":"接"},{"emoji":"🔢","example":"你们是第一次来北京吗？","examplePinyin":"Nǐmen shì dì-yī cì lái Běijīng ma?","exampleVi":"Đây có phải là lần đầu tiên các bạn đến Bắc Kinh không?","meaning":"lần, lượt","pinyin":"cì","pos":"Lượng từ","word":"次"},{"emoji":"🧳","example":"我们是来旅游的。","examplePinyin":"Wǒmen shì lái lǚyóu de.","exampleVi":"Chúng tôi đến để du lịch.","meaning":"du lịch","pinyin":"lǚyóu","pos":"Động từ","word":"旅游"},{"emoji":"🤲","example":"我想请你帮个忙。","examplePinyin":"Wǒ xiǎng qǐng nǐ bāng ge máng.","exampleVi":"Tôi muốn nhờ bạn giúp một việc.","meaning":"giúp đỡ","pinyin":"bāngmáng","pos":"Động từ","word":"帮忙"},{"emoji":"😳","example":"不好意思，我已经到北京了。","examplePinyin":"Bù hǎoyìsi, wǒ yǐjīng dào Běijīng le.","exampleVi":"Xin lỗi, tôi đã đến Bắc Kinh rồi.","meaning":"xin lỗi, ngại quá","pinyin":"bù hǎoyìsi","pos":"Cụm từ","word":"不好意思"},{"emoji":"✅","example":"我已经到北京了。","examplePinyin":"Wǒ yǐjīng dào Běijīng le.","exampleVi":"Tôi đã đến Bắc Kinh rồi.","meaning":"đã, rồi","pinyin":"yǐjīng","pos":"Phó từ","word":"已经"},{"emoji":"👉","example":"好的，那我给他打个电话。","examplePinyin":"Hǎo de, nà wǒ gěi tā dǎ ge diànhuà.","exampleVi":"Được, vậy thì tôi gọi điện cho anh ấy.","meaning":"vậy thì, thế thì","pinyin":"nà","pos":"Liên từ","word":"那"},{"emoji":"🗣️","example":"她还给我们介绍了很多东西。","examplePinyin":"Tā hái gěi wǒmen jièshào le hěn duō dōngxi.","exampleVi":"Chị ấy còn giới thiệu cho chúng tôi rất nhiều thứ.","meaning":"giới thiệu","pinyin":"jièshào","pos":"Động từ","word":"介绍"},{"emoji":"⏰","example":"我们的中文不太好，有时不太懂她的意思。","examplePinyin":"Wǒmen de Zhōngwén bú tài hǎo, yǒushí bú tài dǒng tā de yìsi.","exampleVi":"Tiếng Trung của chúng tôi không tốt lắm, đôi khi không hiểu rõ ý của chị ấy.","meaning":"thỉnh thoảng, đôi khi","pinyin":"yǒushí","pos":"Phó từ","word":"有时"},{"emoji":"💡","example":"有时不太懂她的意思。","examplePinyin":"Yǒushí bú tài dǒng tā de yìsi.","exampleVi":"Đôi khi không hiểu ý của chị ấy.","meaning":"hiểu","pinyin":"dǒng","pos":"Động từ","word":"懂"},{"emoji":"💭","example":"有时不太懂她的意思。","examplePinyin":"Yǒushí bú tài dǒng tā de yìsi.","exampleVi":"Đôi khi không hiểu ý của chị ấy.","meaning":"ý, ý nghĩa","pinyin":"yìsi","pos":"Danh từ","word":"意思"}]},{"emoji":"🚕","grammar":[{"title":"Mẫu cố định 还是……吧 chọn cách tốt hơn","formula":"还是 + cách làm được chọn + 吧","explain":"Mẫu 还是……吧 diễn tả lựa chọn thiên về một cách làm, hàm ý cách đó tốt hơn.","tip":"还是 ở đây đọc là háishi, mang nghĩa nên chọn cách này thì hơn.","examples":"我们还是打车去吧。 (Wǒmen háishi dǎchē qù ba.) — Chúng ta vẫn nên đi taxi thì hơn. 那件衣服很好看，还是买那件吧。 (Nà jiàn yīfu hěn hǎokàn, háishi mǎi nà jiàn ba.) — Cái áo kia rất đẹp, vẫn nên mua cái đó thì hơn. 你第一次去北京，还是找个人接你吧。 (Nǐ dì-yī cì qù Běijīng, háishi zhǎo ge rén jiē nǐ ba.) — Bạn lần đầu đến Bắc Kinh, vẫn nên tìm người đón bạn thì hơn.","error":"Không dùng 还是……吧 khi hai lựa chọn ngang nhau, mẫu này luôn thiên về một lựa chọn."},{"title":"Dùng 多 diễn tả số lượng ước chừng","formula":"Số từ (bội số của 10) + 多 + lượng từ + danh từ, hoặc số từ + lượng từ + 多 + danh từ","explain":"多 đặt sau số từ hoặc sau số từ kèm lượng từ, diễn tả số lượng hơi vượt con số đã nói, chỉ số lượng ước chừng. Khi số là bội số của 10 thì 多 thường đặt ngay sau số từ, khi số không phải bội số của 10 thì 多 thường đặt sau lượng từ.","tip":"Muốn nói số lượng ước chừng lớn hơn con số đã nói thì dùng 多.","examples":"北京大学有四万多名学生呢！ (Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!) — Đại học Bắc Kinh có hơn bốn vạn sinh viên đấy! 教室里有二十多个学生。 (Jiàoshì lǐ yǒu èrshí duō ge xuéshēng.) — Trong phòng học có hơn hai mươi học sinh. 这两个苹果五块多钱。 (Zhè liǎng ge píngguǒ wǔ kuài duō qián.) — Hai quả táo này hơn năm đồng.","error":"Không đặt 多 trước số từ, và không đặt 多 sau danh từ."},{"title":"Động từ và cụm chủ vị làm định ngữ","formula":"Động từ/cụm chủ vị + 的 + danh từ","explain":"Động từ, cụm động từ hay cụm chủ vị đặt trước danh từ, diễn tả đặc điểm hay trạng thái của danh từ đó.","tip":"Cụm chủ vị làm định ngữ luôn có 的 ở giữa, ví dụ 现在学中文的学生.","examples":"他们卖的电影票也很便宜。 (Tāmen mài de diànyǐngpiào yě hěn piányi.) — Vé xem phim họ bán cũng rất rẻ. 现在学中文的学生很多。 (Xiànzài xué Zhōngwén de xuéshēng hěn duō.) — Học sinh đang học tiếng Trung bây giờ rất đông. 这是朋友给我的杯子。 (Zhè shì péngyou gěi wǒ de bēizi.) — Đây là cái cốc bạn tôi tặng tôi.","error":"Không bỏ 的 giữa cụm động từ và danh từ, nếu không cụm định ngữ sẽ không rõ."}],"han":"还是打车去北大吧","natural":["Mạch ý: hỏi xe ở quầy lễ tân, quyết định đi taxi, tham quan trường, phát hiện rạp chiếu phim, nhắn tin kể lại.","还是……吧 khác với 还是 trong câu hỏi lựa chọn: ở đây bày tỏ ý kiến thiên về một phương án, cuối câu có 吧.","Khi nghe, chú ý vị trí của 多: sau số từ khi số là bội số của 10 (四万多), sau lượng từ khi số không phải bội số của 10 (二十多个, 五块多钱)."],"num":2,"photoPrefix":"h2-2","pinyin":"Háishi dǎchē qù Běidà ba","structures":[{"han":"我们还是打车去吧。","pinyin":"Wǒmen háishi dǎchē qù ba.","meaning":"Chúng ta vẫn nên đi taxi thì hơn.","note":"Mẫu 还是……吧 bày tỏ lựa chọn thiên về một cách, mang hàm ý cách này tốt hơn."},{"han":"北京大学有四万多名学生呢！","pinyin":"Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!","meaning":"Đại học Bắc Kinh có hơn bốn vạn sinh viên đấy!","note":"多 đặt sau số từ 四万 để chỉ số lượng ước chừng, hơn bốn vạn; 呢 ở cuối câu nhấn mạnh cảm thán."},{"han":"他们卖的电影票也很便宜。","pinyin":"Tāmen mài de diànyǐngpiào yě hěn piányi.","meaning":"Vé xem phim họ bán cũng rất rẻ.","note":"Cụm động từ 他们卖 làm định ngữ cho 电影票, phải thêm 的 giữa định ngữ và danh từ."},{"han":"学校里人真多啊！","pinyin":"Xuéxiào lǐ rén zhēn duō a!","meaning":"Trong trường đông người thật đấy!","note":"啊 ở cuối câu bày tỏ cảm thán, tán đồng; 真 nhấn mạnh mức độ đông."}],"theme":"Đi taxi và tham quan Đại học Bắc Kinh","translation":"Vẫn nên đi taxi đến Đại học Bắc Kinh thì hơn","vocab":[{"emoji":"🚌","example":"这儿有到北京大学的公交车吗？","examplePinyin":"Zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?","exampleVi":"Ở đây có xe buýt đi Đại học Bắc Kinh không?","meaning":"xe buýt","pinyin":"gōngjiāochē","pos":"Danh từ","word":"公交车"},{"emoji":"↔️","example":"有，但车站有点儿远。","examplePinyin":"Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","exampleVi":"Có, nhưng trạm xe hơi xa.","meaning":"nhưng","pinyin":"dàn","pos":"Liên từ","word":"但"},{"emoji":"🚏","example":"车站有点儿远。","examplePinyin":"Chēzhàn yǒudiǎnr yuǎn.","exampleVi":"Trạm xe hơi xa.","meaning":"trạm xe, bến xe","pinyin":"chēzhàn","pos":"Danh từ","word":"车站"},{"emoji":"🔭","example":"车站有点儿远。","examplePinyin":"Chēzhàn yǒudiǎnr yuǎn.","exampleVi":"Trạm xe hơi xa.","meaning":"xa","pinyin":"yuǎn","pos":"Tính từ","word":"远"},{"emoji":"🚕","example":"我们还是打车去吧。","examplePinyin":"Wǒmen háishi dǎchē qù ba.","exampleVi":"Chúng ta vẫn nên đi taxi thì hơn.","meaning":"đón taxi, đi taxi","pinyin":"dǎchē","pos":"Động từ","word":"打车"},{"emoji":"🤔","example":"我们还是打车去吧。","examplePinyin":"Wǒmen háishi dǎchē qù ba.","exampleVi":"Chúng ta vẫn nên đi taxi thì hơn.","meaning":"vẫn nên, thì hơn","pinyin":"háishi","pos":"Phó từ","word":"还是"},{"emoji":"😲","example":"学校里人真多啊！","examplePinyin":"Xuéxiào lǐ rén zhēn duō a!","exampleVi":"Trong trường đông người thật đấy!","meaning":"à, nhỉ (bày tỏ cảm thán, tán đồng)","pinyin":"a","pos":"Trợ từ","word":"啊"},{"emoji":"🔢","example":"北京大学有四万多名学生呢！","examplePinyin":"Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!","exampleVi":"Đại học Bắc Kinh có hơn bốn vạn sinh viên đấy!","meaning":"mười nghìn, vạn","pinyin":"wàn","pos":"Số từ","word":"万"},{"emoji":"👥","example":"北京大学有四万多名学生呢！","examplePinyin":"Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!","exampleVi":"Đại học Bắc Kinh có hơn bốn vạn sinh viên đấy!","meaning":"người (lượng từ chỉ người)","pinyin":"míng","pos":"Lượng từ","word":"名"},{"emoji":"🌐","example":"是网上说的。","examplePinyin":"Shì wǎngshang shuō de.","exampleVi":"Là trên mạng nói vậy.","meaning":"trên mạng","pinyin":"wǎngshang","pos":"Danh từ","word":"网上"},{"emoji":"🌍","example":"北京大学有三千多名外国学生。","examplePinyin":"Běijīng Dàxué yǒu sānqiān duō míng wàiguó xuéshēng.","exampleVi":"Đại học Bắc Kinh có hơn ba nghìn sinh viên nước ngoài.","meaning":"nước ngoài","pinyin":"wàiguó","pos":"Danh từ","word":"外国"},{"emoji":"🚪","example":"那边就有一间教室。","examplePinyin":"Nàbiān jiù yǒu yì jiān jiàoshì.","exampleVi":"Bên kia có một phòng học.","meaning":"gian, phòng (lượng từ chỉ phòng)","pinyin":"jiān","pos":"Lượng từ","word":"间"},{"emoji":"🏫","example":"那边就有一间教室。","examplePinyin":"Nàbiān jiù yǒu yì jiān jiàoshì.","exampleVi":"Bên kia có một phòng học.","meaning":"phòng học, lớp học","pinyin":"jiàoshì","pos":"Danh từ","word":"教室"},{"emoji":"🎫","example":"他们卖的电影票也很便宜。","examplePinyin":"Tāmen mài de diànyǐngpiào yě hěn piányi.","exampleVi":"Vé xem phim họ bán cũng rất rẻ.","meaning":"vé","pinyin":"piào","pos":"Danh từ","word":"票"},{"emoji":"🚫","example":"还是别看电影了。","examplePinyin":"Háishi bié kàn diànyǐng le.","exampleVi":"Vẫn là đừng xem phim nữa.","meaning":"đừng, chớ","pinyin":"bié","pos":"Phó từ","word":"别"},{"emoji":"🚶","example":"我们有时间还想再过来看个电影。","examplePinyin":"Wǒmen yǒu shíjiān hái xiǎng zài guòlái kàn ge diànyǐng.","exampleVi":"Khi có thời gian chúng tôi còn muốn quay lại xem một bộ phim.","meaning":"qua đây, đến đây","pinyin":"guòlái","pos":"Động từ","word":"过来"}]},{"emoji":"🏯","grammar":[{"title":"Bổ ngữ kết quả","formula":"Chủ ngữ + động từ + bổ ngữ kết quả + (了), phủ định: 没(有) + động từ + bổ ngữ kết quả","explain":"Một số động từ hay tính từ đặt sau động từ chính, diễn tả kết quả của hành động. Phủ định thêm 没(有) trước động từ và bỏ 了.","tip":"Câu phủ định của bổ ngữ kết quả dùng 没, không dùng 不, và phải bỏ 了.","examples":"菜都做好了。 (Cài dōu zuòhǎo le.) — Món ăn đều làm xong rồi. 我吃完饭了。 (Wǒ chīwán fàn le.) — Tôi ăn cơm xong rồi. 小雪今天来晚了。 (Xiǎoxuě jīntiān láiwǎn le.) — Tiểu Tuyết hôm nay đến muộn rồi.","error":"Không dùng 不 để phủ định bổ ngữ kết quả, và không giữ 了 trong câu phủ định."},{"title":"Động từ lặp lại (1) cho hành động chưa xảy ra","formula":"Động từ đơn âm: A (一) A, động từ song âm: ABAB, động từ li hợp: AAB","explain":"Động từ chỉ hành động mạnh, có thể lặp lại hay kéo dài mới dùng dạng lặp lại, diễn tả hành động ngắn, số lần ít hay làm thử, giọng nhẹ nhàng, thường dùng trong khẩu ngữ.","tip":"Động từ song âm lặp lại dạng ABAB, ví dụ 休息休息.","examples":"那你再想一想，你想好了，我来买票。 (Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎi piào.) — Vậy bạn nghĩ thêm một chút, bạn nghĩ xong thì tôi đi mua vé. 我有点儿累，现在想休息休息。 (Wǒ yǒudiǎnr lèi, xiànzài xiǎng xiūxi xiūxi.) — Tôi hơi mệt, bây giờ muốn nghỉ ngơi một chút. 你能过来帮帮忙吗？ (Nǐ néng guòlái bāngbang máng ma?) — Bạn có thể qua đây giúp một tay không?","error":"Không lặp lại động từ chỉ trạng thái hay động từ không thể lặp lại, và không dùng dạng lặp lại trong văn viết trang trọng."},{"title":"Động từ lặp lại (2) cho hành động đã xảy ra","formula":"Động từ đơn âm: A了A, động từ song âm: AB了一下, động từ li hợp: A了AB","explain":"Khi diễn tả hành động đã xảy ra, động từ đơn âm lặp lại dạng A了A, động từ song âm thường không lặp lại mà dùng AB了一下, động từ li hợp dùng dạng A了AB.","tip":"Hành động đã xảy ra thì động từ song âm không lặp lại, phải dùng AB了一下.","examples":"我看了看网上的介绍。 (Wǒ kànle kàn wǎngshang de jièshào.) — Tôi đã xem qua phần giới thiệu trên mạng. 我休息了一下，现在觉得不累了。 (Wǒ xiūxi le yíxià, xiànzài juéde bù lèi le.) — Tôi đã nghỉ một lát, bây giờ thấy không mệt nữa. 他昨天来帮了帮忙。 (Tā zuótiān lái bāngle bāng máng.) — Hôm qua anh ấy đã đến giúp một tay.","error":"Không dùng dạng ABAB cho hành động đã xảy ra với động từ song âm, phải dùng AB了一下."}],"han":"我想去西安旅游","natural":["Mạch ý: về nhà muộn vì việc nhiều, hẹn đi du lịch, quyết định đi Tây An, gọi điện kể chuyện Lưu Minh mệt vì việc.","Bổ ngữ kết quả đứng ngay sau động từ: 做好, 做完, 来晚, 想好; dạng phủ định dùng 没 và bỏ 了.","Động từ láy diễn tả hành động ngắn, thử làm: chưa xảy ra dùng A(一)A và ABAB, đã xảy ra dùng A了A và AB了一下."],"num":3,"photoPrefix":"h2-3","pinyin":"Wǒ xiǎng qù Xī'ān lǚyóu","structures":[{"han":"菜都做好了，过来吃饭吧。","pinyin":"Cài dōu zuòhǎo le, guòlái chī fàn ba.","meaning":"Cơm đã nấu xong hết rồi, qua đây ăn cơm đi.","note":"做好 là động từ 做 cộng bổ ngữ kết quả 好, nói món ăn đã làm xong và đạt kết quả tốt."},{"han":"下班的时候没做完。","pinyin":"Gōngzuò tài duō le, xiàbān de shíhou méi zuòwán.","meaning":"Lúc tan làm vẫn chưa làm xong.","note":"Dạng phủ định của bổ ngữ kết quả là 没 cộng động từ, đồng thời bỏ 了 ở cuối câu."},{"han":"那你再想一想，你想好了，我来买票。","pinyin":"Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎi piào.","meaning":"Vậy bạn nghĩ thêm đi, bạn nghĩ xong rồi thì tôi đi mua vé.","note":"想一想 là dạng láy của động từ đơn âm tiết, diễn tả hành động ngắn và nhẹ nhàng; 想好 là bổ ngữ kết quả."},{"han":"我看了看网上的介绍，这个时候去西安很不错！","pinyin":"Wǒ kànle kàn wǎngshang de jièshào, zhège shíhou qù Xī'ān hěn búcuò!","meaning":"Tôi đã xem qua giới thiệu trên mạng, đi Tây An vào lúc này rất tuyệt!","note":"看了看 là dạng láy A了A của hành động đã xảy ra, diễn tả xem qua một chút; 不错 khen một cách nhẹ nhàng."}],"theme":"Du lịch Tây An và nghỉ ngơi","translation":"Tôi muốn đi Tây An du lịch","vocab":[{"emoji":"🏠","example":"今天回来这么晚啊！","examplePinyin":"Jīntiān huílái zhème wǎn a!","exampleVi":"Hôm nay về muộn thế!","meaning":"trở về, quay về","pinyin":"huílái","pos":"Động từ","word":"回来"},{"emoji":"🤏","example":"今天回来这么晚啊！","examplePinyin":"Jīntiān huílái zhème wǎn a!","exampleVi":"Hôm nay về muộn thế!","meaning":"như thế, như vậy","pinyin":"zhème","pos":"Đại từ","word":"这么"},{"emoji":"✅","example":"下班的时候没做完。","examplePinyin":"Xiàbān de shíhou méi zuòwán.","exampleVi":"Lúc tan làm vẫn chưa làm xong.","meaning":"xong, hoàn thành","pinyin":"wán","pos":"Động từ","word":"完"},{"emoji":"👫","example":"我也很想一起出去玩。","examplePinyin":"Wǒ yě hěn xiǎng yìqǐ chūqù wán.","exampleVi":"Tôi cũng rất muốn cùng đi chơi.","meaning":"cùng nhau","pinyin":"yìqǐ","pos":"Phó từ","word":"一起"},{"emoji":"🚶","example":"我也很想一起出去玩。","examplePinyin":"Wǒ yě hěn xiǎng yìqǐ chūqù wán.","exampleVi":"Tôi cũng rất muốn cùng đi chơi.","meaning":"đi ra ngoài","pinyin":"chūqù","pos":"Động từ","word":"出去"},{"emoji":"🧼","example":"我都洗好了。","examplePinyin":"Wǒ dōu xǐhǎo le.","exampleVi":"Tôi đã rửa sạch hết rồi.","meaning":"rửa, giặt","pinyin":"xǐ","pos":"Động từ","word":"洗"},{"emoji":"🙋","example":"你自己拿。","examplePinyin":"Nǐ zìjǐ ná.","exampleVi":"Bạn tự lấy đi.","meaning":"tự mình, bản thân","pinyin":"zìjǐ","pos":"Đại từ","word":"自己"},{"emoji":"🤲","example":"你自己拿。","examplePinyin":"Nǐ zìjǐ ná.","exampleVi":"Bạn tự lấy đi.","meaning":"lấy, cầm","pinyin":"ná","pos":"Động từ","word":"拿"},{"emoji":"✋","example":"我去洗洗手。","examplePinyin":"Wǒ qù xǐxi shǒu.","exampleVi":"Tôi đi rửa tay một cái.","meaning":"tay","pinyin":"shǒu","pos":"Danh từ","word":"手"},{"emoji":"❓","example":"为什么想去西安？","examplePinyin":"Wèi shénme xiǎng qù Xī'ān?","exampleVi":"Tại sao muốn đi Tây An?","meaning":"tại sao","pinyin":"wèi shénme","pos":"Cụm từ","word":"为什么"},{"emoji":"👍","example":"这个时候去西安很不错！","examplePinyin":"Zhège shíhou qù Xī'ān hěn búcuò!","exampleVi":"Đi Tây An vào lúc này rất tuyệt!","meaning":"không tệ, khá tốt","pinyin":"búcuò","pos":"Tính từ","word":"不错"},{"emoji":"🚗","example":"刘明开车送孩子去学校。","examplePinyin":"Liú Míng kāichē sòng háizi qù xuéxiào.","exampleVi":"Lưu Minh lái xe đưa con đi học.","meaning":"đưa, tiễn, tặng","pinyin":"sòng","pos":"Động từ","word":"送"},{"emoji":"↩️","example":"让他回去上班。","examplePinyin":"Ràng tā huíqù shàngbān.","exampleVi":"Bảo anh ấy quay lại đi làm.","meaning":"trở về, quay lại","pinyin":"huíqù","pos":"Động từ","word":"回去"},{"emoji":"📅","example":"他这个月每天都很累。","examplePinyin":"Tā zhège yuè měitiān dōu hěn lèi.","exampleVi":"Tháng này ngày nào anh ấy cũng rất mệt.","meaning":"mỗi","pinyin":"měi","pos":"Đại từ","word":"每"},{"emoji":"😫","example":"他这个月每天都很累。","examplePinyin":"Tā zhège yuè měitiān dōu hěn lèi.","exampleVi":"Tháng này ngày nào anh ấy cũng rất mệt.","meaning":"mệt","pinyin":"lèi","pos":"Tính từ","word":"累"}]},{"emoji":"👖","grammar":[{"title":"Trợ từ thể 过 chỉ kinh nghiệm đã qua","formula":"Chủ ngữ + động từ + 过 + tân ngữ, phủ định: 没(有) + động từ + 过","explain":"过 đặt sau động từ, diễn tả hành động từng xảy ra trong quá khứ nhưng không kéo dài đến hiện tại. Phủ định thêm 没(有) trước động từ.","tip":"Câu hỏi với 过 có ba dạng: thêm 吗, thêm 没有, hoặc động từ + 没 + động từ + 过.","examples":"她去过中国。 (Tā qùguo Zhōngguó.) — Cô ấy đã từng đến Trung Quốc. 我吃过饺子，很好吃。 (Wǒ chīguo jiǎozi, hěn hǎochī.) — Tôi đã từng ăn sủi cảo, rất ngon. 她没去过中国。 (Tā méi qùguo Zhōngguó.) — Cô ấy chưa từng đến Trung Quốc.","error":"Không dùng 过 với hành động đang tiếp diễn hay hành động trong tương lai."},{"title":"Câu phức nhân quả 因为……, 所以……","formula":"因为 + nguyên nhân, 所以 + kết quả (có thể chỉ dùng một vế)","explain":"因为……, 所以…… tạo thành câu phức nhân quả. 因为 và 所以 có thể dùng thành cặp, cũng có thể chỉ dùng một trong hai.","tip":"Vì đã có 因为 nên không cần thêm từ chỉ nguyên nhân khác, và không dùng 但是 sau 所以.","examples":"就是因为没穿过，所以要试试啊！ (Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!) — Chính vì chưa từng mặc nên mới phải thử chứ! 因为我生病了，今天没去上班。 (Yīnwèi wǒ shēngbìng le, jīntiān méi qù shàngbān.) — Vì tôi bị ốm nên hôm nay không đi làm. 我没去过他家，所以让他来车站接我。 (Wǒ méi qùguo tā jiā, suǒyǐ ràng tā lái chēzhàn jiē wǒ.) — Tôi chưa từng đến nhà anh ấy nên bảo anh ấy đến ga đón tôi.","error":"Không dùng 因为 và 所以 lộn thứ tự, nguyên nhân luôn ở vế 因为."},{"title":"Cụm từ 的 thay cho danh từ","formula":"Danh từ/đại từ/động từ/tính từ + 的 (thay cho danh từ đã nhắc)","explain":"Trợ từ kết cấu 的 đặt sau danh từ, đại từ, động từ hay tính từ, tạo thành cụm từ 的, tương đương một cụm danh từ, dùng thay cho danh từ đã nhắc đến trước đó.","tip":"Cụm từ 的 giúp tránh lặp lại danh từ, ví dụ 红色的 tức là 红色的书包.","examples":"红色的、绿色的、黑色的，你想买哪个？ (Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?) — Màu đỏ, màu xanh lá, màu đen, bạn muốn mua cái nào? 这个面包是爸爸买的，妈妈买的在那儿。 (Zhège miànbāo shì bàba mǎi de, māma mǎi de zài nàr.) — Cái bánh mì này là bố mua, cái mẹ mua ở đằng kia. 这件衣服太贵了，还是买那件便宜的吧。 (Zhè jiàn yīfu tài guì le, háishi mǎi nà jiàn piányi de ba.) — Cái áo này đắt quá, vẫn nên mua cái rẻ kia thì hơn.","error":"Không thêm danh từ sau 的, vì cụm từ 的 đã thay cho danh từ rồi."}],"han":"你穿红色的很好看","natural":["Mạch ý: đến trung tâm mới mở, chọn quần trắng rồi thử quần đỏ, chọn cặp sách xanh lá, viết nhật ký kể lại.","过 chỉ kinh nghiệm quá khứ, khác với 了 chỉ hành động đã hoàn thành; dạng phủ định là 没...过, không dùng 不...过.","Khi nghe, chú ý cụm 的 đứng sau màu sắc hay động từ để chỉ đồ vật: 白色的, 红色的, 爸爸买的, 便宜的."],"num":4,"photoPrefix":"h2-4","pinyin":"Nǐ chuān hóngsè de hěn hǎokàn","structures":[{"han":"妈妈，我们来过这家商场吗？","pinyin":"Wǒmen láiguo zhè jiā shāngchǎng ma?","meaning":"Mẹ ơi, chúng ta đã từng đến trung tâm thương mại này chưa?","note":"过 đứng sau động từ 来, chỉ hành động đã từng xảy ra trong quá khứ nhưng không kéo dài đến hiện tại; dạng phủ định dùng 没来过."},{"han":"就是因为没穿过，所以要试试啊！","pinyin":"Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!","meaning":"Chính vì chưa từng mặc nên mới phải thử chứ!","note":"Câu phức nhân quả, 因为 nêu nguyên nhân, 所以 nêu kết quả; 就是 nhấn mạnh chính là vì lý do đó."},{"han":"红色的、绿色的、黑色的，你想买哪个？","pinyin":"Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?","meaning":"Màu đỏ, màu xanh lá, màu đen, bạn muốn mua cái nào?","note":"Cụm 的 sau tính từ chỉ màu sắc thay cho danh từ 书包, không cần lặp lại danh từ đã biết."},{"han":"我觉得我穿红色的也很好看。","pinyin":"Wǒ méi chuānguo hóngsè de kùzi, māma ràng wǒ shìle shì, wǒ juéde wǒ chuān hóngsè de yě hěn hǎokàn.","meaning":"Tôi thấy mình mặc màu đỏ cũng rất đẹp.","note":"穿红色的 là động từ cộng cụm 的 chỉ quần áo màu đỏ; 也 cho biết ngoài màu trắng, màu đỏ cũng đẹp."},{"han":"我们来过这家商场吗？","pinyin":"Wǒmen láiguo zhè jiā shāngchǎng ma?","meaning":"Chúng ta đã từng đến trung tâm thương mại này chưa?","note":""}],"theme":"Mua sắm quần áo và màu sắc","translation":"Bạn mặc màu đỏ rất đẹp","vocab":[{"emoji":"⏳","example":"我们来过这家商场吗？","examplePinyin":"Wǒmen láiguo zhè jiā shāngchǎng ma?","exampleVi":"Chúng ta đã từng đến trung tâm thương mại này chưa?","meaning":"đã từng (chỉ hành động quá khứ)","pinyin":"guo","pos":"Trợ từ","word":"过"},{"emoji":"🏬","example":"我们来过这家商场吗？","examplePinyin":"Wǒmen láiguo zhè jiā shāngchǎng ma?","exampleVi":"Chúng ta đã từng đến trung tâm thương mại này chưa?","meaning":"trung tâm thương mại","pinyin":"shāngchǎng","pos":"Danh từ","word":"商场"},{"emoji":"🚶","example":"我们进去看看吧。","examplePinyin":"Wǒmen jìnqù kànkan ba.","exampleVi":"Chúng ta vào trong xem thử đi.","meaning":"đi vào","pinyin":"jìnqù","pos":"Động từ","word":"进去"},{"emoji":"📏","example":"我想买条裤子。","examplePinyin":"Wǒ xiǎng mǎi tiáo kùzi.","exampleVi":"Tôi muốn mua một chiếc quần.","meaning":"chiếc, cái (lượng từ chỉ vật dài, hẹp)","pinyin":"tiáo","pos":"Lượng từ","word":"条"},{"emoji":"👖","example":"我想买条裤子。","examplePinyin":"Wǒ xiǎng mǎi tiáo kùzi.","exampleVi":"Tôi muốn mua một chiếc quần.","meaning":"quần","pinyin":"kùzi","pos":"Danh từ","word":"裤子"},{"emoji":"⬜","example":"我想买这条白色的裤子。","examplePinyin":"Wǒ xiǎng mǎi zhè tiáo báisè de kùzi.","exampleVi":"Tôi muốn mua chiếc quần màu trắng này.","meaning":"màu trắng","pinyin":"báisè","pos":"Danh từ","word":"白色"},{"emoji":"❓","example":"因为我喜欢白色啊！","examplePinyin":"Yīnwèi wǒ xǐhuan báisè a!","exampleVi":"Vì tôi thích màu trắng mà!","meaning":"vì, bởi vì","pinyin":"yīnwèi","pos":"Liên từ","word":"因为"},{"emoji":"👗","example":"你试试那条红色的吧。","examplePinyin":"Nǐ shìshi nà tiáo hóngsè de ba.","exampleVi":"Bạn thử chiếc màu đỏ kia đi.","meaning":"thử","pinyin":"shì","pos":"Động từ","word":"试"},{"emoji":"🟥","example":"我没穿过红色的，红色的好看吗？","examplePinyin":"Wǒ méi chuānguo hóngsè de, hóngsè de hǎokàn ma?","exampleVi":"Tôi chưa từng mặc màu đỏ, màu đỏ có đẹp không?","meaning":"màu đỏ","pinyin":"hóngsè","pos":"Danh từ","word":"红色"},{"emoji":"👉","example":"就是因为没穿过，所以要试试啊！","examplePinyin":"Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!","exampleVi":"Chính vì chưa từng mặc nên mới phải thử chứ!","meaning":"vì vậy, cho nên","pinyin":"suǒyǐ","pos":"Liên từ","word":"所以"},{"emoji":"🎒","example":"我想买个新书包。","examplePinyin":"Wǒ xiǎng mǎi ge xīn shūbāo.","exampleVi":"Tôi muốn mua một chiếc cặp sách mới.","meaning":"cặp sách","pinyin":"shūbāo","pos":"Danh từ","word":"书包"},{"emoji":"🚶","example":"我们过去看看吧。","examplePinyin":"Wǒmen guòqù kànkan ba.","exampleVi":"Chúng ta qua đó xem thử đi.","meaning":"qua đó, đi qua","pinyin":"guòqù","pos":"Động từ","word":"过去"},{"emoji":"🟩","example":"绿色的吧。","examplePinyin":"Lǜsè de ba.","exampleVi":"Lấy màu xanh lá đi.","meaning":"màu xanh lá","pinyin":"lǜsè","pos":"Danh từ","word":"绿色"},{"emoji":"⬛","example":"红色的、绿色的、黑色的，你想买哪个？","examplePinyin":"Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?","exampleVi":"Màu đỏ, màu xanh lá, màu đen, bạn muốn mua cái nào?","meaning":"màu đen","pinyin":"hēisè","pos":"Danh từ","word":"黑色"},{"emoji":"📈","example":"我也觉得绿色的更好看。","examplePinyin":"Wǒ yě juéde lǜsè de gèng hǎokàn.","exampleVi":"Tôi cũng thấy màu xanh lá đẹp hơn.","meaning":"càng, hơn","pinyin":"gèng","pos":"Phó từ","word":"更"},{"emoji":"🎨","example":"商场里的衣服颜色很多。","examplePinyin":"Shāngchǎng lǐ de yīfu yánsè hěn duō.","exampleVi":"Quần áo trong trung tâm thương mại có rất nhiều màu sắc.","meaning":"màu sắc","pinyin":"yánsè","pos":"Danh từ","word":"颜色"}]},{"emoji":"🏠","grammar":[{"title":"Bổ ngữ xu hướng đơn (1) động từ + 来/去","formula":"Động từ (上/下/进/出/回/过) + 来/去","explain":"Bổ ngữ xu hướng đơn có cấu trúc động từ + 来/去. 来 diễn tả hành động hướng về phía người nói, 去 diễn tả hành động hướng ra xa người nói. Động từ thường dùng: 上, 下, 进, 出, 回, 过.","tip":"Xác định vị trí người nói trước rồi mới chọn 来 hay 去.","examples":"我不上去了，就在下面等你。 (Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.) — Tôi không lên nữa, cứ đợi bạn ở dưới này. 家月到下边了，你下去接她吧。 (Jiāyuè dào xiàbiān le, nǐ xiàqù jiē tā ba.) — Gia Nguyệt đã xuống dưới rồi, bạn xuống đón cô ấy đi. 我在外边呢，你出来吧。 (Wǒ zài wàibiān ne, nǐ chūlái ba.) — Tôi đang ở ngoài này, bạn ra đây đi.","error":"Không dùng 来 khi hành động hướng ra xa người nói, và ngược lại với 去."},{"title":"Bổ ngữ xu hướng đơn (2) mang tân ngữ","formula":"Động từ + tân ngữ chỉ nơi chốn + 来/去, hoặc động từ + 来/去 + tân ngữ chỉ đồ vật","explain":"Khi động từ vừa có bổ ngữ xu hướng đơn vừa có tân ngữ, nếu tân ngữ là danh từ chỉ nơi chốn thì đặt trước 来/去, nếu tân ngữ là danh từ chỉ đồ vật thì đặt trước hay sau 来/去 đều được.","tip":"Danh từ chỉ nơi chốn luôn đứng trước 来/去, danh từ chỉ đồ vật có thể đứng sau.","examples":"你们太客气了，还拿这么多礼物来！ (Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!) — Các bạn khách sáo quá, còn mang nhiều quà đến thế này! 家月给我送来了一本书。 (Jiāyuè gěi wǒ sònglái le yì běn shū.) — Gia Nguyệt đã mang đến cho tôi một quyển sách. 上课了，你们快进教室来吧。 (Shàngkè le, nǐmen kuài jìn jiàoshì lái ba.) — Vào học rồi, các bạn mau vào lớp đi.","error":"Không đặt danh từ chỉ nơi chốn sau 来/去, ví dụ phải nói 进教室来, không nói 进来教室."},{"title":"Mẫu cố định 都……了 chỉ đã đến mức nào đó","formula":"都 + (số lượng/thời gian/mức độ) + 了","explain":"Mẫu 都……了 diễn tả đã đạt đến một mức nào đó, thường kèm giọng nhấn mạnh hay không hài lòng.","tip":"都……了 thường đi với thời gian hay số lần, nhấn mạnh đã quá muộn hay đã đủ rồi.","examples":"都12点了，我们吃饭吧。 (Dōu shí'èr diǎn le, wǒmen chī fàn ba.) — Đã 12 giờ rồi, chúng ta ăn cơm đi. 都8点半了，你还不起床吗？ (Dōu bā diǎn bàn le, nǐ hái bù qǐchuáng ma?) — Đã 8 giờ rưỡi rồi mà bạn còn chưa dậy à? 我都去过北京了，不想再去了。 (Wǒ dōu qùguo Běijīng le, bù xiǎng zài qù le.) — Tôi đã từng đến Bắc Kinh rồi, không muốn đi nữa.","error":"Không dùng 都……了 cho sự việc chưa xảy ra, mẫu này chỉ dùng khi mức độ đã đạt được."}],"han":"第一次去中国朋友家","natural":["Mạch ý: giục nhau xuống khách sạn, đến nhà chào hỏi ông bà và tặng quà, ăn cơm với trà sữa của ông, nhắn tin kể lại cho Lý Văn.","Bổ ngữ xu hướng 来 chỉ hướng về phía người nói, 去 chỉ hướng ra xa người nói; tân ngữ chỉ địa điểm đặt trước 来/去, tân ngữ chỉ vật đặt trước hoặc sau 来/去.","Khi nghe, chú ý cách xưng hô khi gặp người Trung Quốc: gọi chị là 一雪姐, gọi ông là 爷爷, chào hỏi bằng 你们好 và đáp lại bằng 别客气."],"num":5,"photoPrefix":"h2-5","pinyin":"Dì-yī cì qù Zhōngguó péngyou jiā","structures":[{"han":"家月，快下来吧，第一次去中国朋友家，别晚了。","pinyin":"Jiāyuè, kuài xiàlái ba, dì-yī cì qù Zhōngguó péngyou jiā, bié wǎn le.","meaning":"Gia Nguyệt, mau xuống đi, lần đầu đến nhà bạn người Trung Quốc, đừng muộn nhé.","note":"下来 là bổ ngữ xu hướng chỉ hướng về phía người nói (Annie ở dưới), 第一次 nhấn mạnh lần đầu tiên."},{"han":"你们太客气了，还拿这么多礼物来！","pinyin":"Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!","meaning":"Các cháu khách sáo quá, còn mang nhiều quà đến thế!","note":"拿...来 là động từ cộng bổ ngữ xu hướng 来, tân ngữ chỉ vật 这么多礼物 đặt trước 来."},{"han":"都12点了，我们吃饭吧。","pinyin":"Dōu shí'èr diǎn le, wǒmen chī fàn ba.","meaning":"Đã 12 giờ rồi, chúng ta ăn cơm đi.","note":"Mẫu cố định 都……了 nhấn mạnh đã đến 12 giờ, mang giọng nhấn mạnh hoặc sốt ruột."},{"han":"因为吃了太多东西，我们吃完饭是走回酒店的。","pinyin":"Yīnwèi chī le tài duō dōngxi, wǒmen chīwán fàn shì zǒu huí jiǔdiàn de.","meaning":"Vì ăn quá nhiều nên ăn cơm xong chúng tôi đi bộ về khách sạn.","note":"Câu 是……的 nhấn mạnh phương thức đi bộ về khách sạn; 走回 là động từ 走 cộng bổ ngữ xu hướng 回."}],"theme":"Đến nhà bạn chơi và cách chào hỏi","translation":"Lần đầu đến nhà bạn người Trung Quốc","vocab":[{"emoji":"⏰","example":"家月，快下来吧。","examplePinyin":"Jiāyuè, kuài xiàlái ba.","exampleVi":"Gia Nguyệt, mau xuống đi.","meaning":"nhanh, mau","pinyin":"kuài","pos":"Phó từ","word":"快"},{"emoji":"⬇️","example":"家月，快下来吧。","examplePinyin":"Jiāyuè, kuài xiàlái ba.","exampleVi":"Gia Nguyệt, mau xuống đi.","meaning":"xuống đây, đi xuống","pinyin":"xiàlái","pos":"Động từ","word":"下来"},{"emoji":"⬆️","example":"你上来吧。","examplePinyin":"Nǐ shànglái ba.","exampleVi":"Bạn lên đây đi.","meaning":"lên đây, đi lên","pinyin":"shànglái","pos":"Động từ","word":"上来"},{"emoji":"⬆️","example":"我不上去了。","examplePinyin":"Wǒ bú shàngqù le.","exampleVi":"Tôi không lên nữa.","meaning":"lên đó, đi lên","pinyin":"shàngqù","pos":"Động từ","word":"上去"},{"emoji":"👇","example":"就在下面等你。","examplePinyin":"Jiù zài xiàmiàn děng nǐ.","exampleVi":"Cứ đợi bạn ở dưới này.","meaning":"phía dưới, tầng dưới","pinyin":"xiàmiàn","pos":"Danh từ","word":"下面"},{"emoji":"⏳","example":"就在下面等你。","examplePinyin":"Jiù zài xiàmiàn děng nǐ.","exampleVi":"Cứ đợi bạn ở dưới này.","meaning":"đợi, chờ","pinyin":"děng","pos":"Động từ","word":"等"},{"emoji":"🕐","example":"那我一会儿就下去。","examplePinyin":"Nà wǒ yíhuìr jiù xiàqù.","exampleVi":"Vậy tôi sẽ xuống ngay trong một lát.","meaning":"một lát, một lúc","pinyin":"yíhuìr","pos":"Lượng từ","word":"一会儿"},{"emoji":"⬇️","example":"那我一会儿就下去。","examplePinyin":"Nà wǒ yíhuìr jiù xiàqù.","exampleVi":"Vậy tôi sẽ xuống ngay trong một lát.","meaning":"xuống đó, đi xuống","pinyin":"xiàqù","pos":"Động từ","word":"下去"},{"emoji":"🚪","example":"家月、安妮，快进来！","examplePinyin":"Jiāyuè, Ānnī, kuài jìnlái!","exampleVi":"Gia Nguyệt, Annie, mau vào đây!","meaning":"vào đây, đi vào","pinyin":"jìnlái","pos":"Động từ","word":"进来"},{"emoji":"👴","example":"这是孩子们的爷爷、奶奶。","examplePinyin":"Zhè shì háizimen de yéye, nǎinai.","exampleVi":"Đây là ông và bà của các cháu.","meaning":"ông nội/ngoại","pinyin":"yéye","pos":"Danh từ","word":"爷爷"},{"emoji":"👵","example":"这是孩子们的爷爷、奶奶。","examplePinyin":"Zhè shì háizimen de yéye, nǎinai.","exampleVi":"Đây là ông và bà của các cháu.","meaning":"bà nội/ngoại","pinyin":"nǎinai","pos":"Danh từ","word":"奶奶"},{"emoji":"🎁","example":"这是送你们的礼物。","examplePinyin":"Zhè shì sòng nǐmen de lǐwù.","exampleVi":"Đây là quà tặng ông bà.","meaning":"quà tặng","pinyin":"lǐwù","pos":"Danh từ","word":"礼物"},{"emoji":"📝","example":"这是给孩子们准备的礼物。","examplePinyin":"Zhè shì gěi háizimen zhǔnbèi de lǐwù.","exampleVi":"Đây là quà đã chuẩn bị cho các cháu.","meaning":"chuẩn bị","pinyin":"zhǔnbèi","pos":"Động từ","word":"准备"},{"emoji":"🧋","example":"奶茶也很好喝。","examplePinyin":"Nǎichá yě hěn hǎohē.","exampleVi":"Trà sữa cũng rất ngon.","meaning":"trà sữa","pinyin":"nǎichá","pos":"Danh từ","word":"奶茶"},{"emoji":"👫","example":"吃完饭你们可以跟我去看看。","examplePinyin":"Chīwán fàn nǐmen kěyǐ gēn wǒ qù kànkan.","exampleVi":"Ăn cơm xong các bạn có thể đi xem cùng tôi.","meaning":"cùng, với","pinyin":"gēn","pos":"Giới từ","word":"跟"},{"emoji":"🚶","example":"我们吃完饭是走回酒店的。","examplePinyin":"Wǒmen chīwán fàn shì zǒu huí jiǔdiàn de.","exampleVi":"Ăn cơm xong chúng tôi đi bộ về khách sạn.","meaning":"đi bộ, đi","pinyin":"zǒu","pos":"Động từ","word":"走"},{"emoji":"🏨","example":"我们吃完饭是走回酒店的。","examplePinyin":"Wǒmen chīwán fàn shì zǒu huí jiǔdiàn de.","exampleVi":"Ăn cơm xong chúng tôi đi bộ về khách sạn.","meaning":"khách sạn","pinyin":"jiǔdiàn","pos":"Danh từ","word":"酒店"}]},{"emoji":"🎂","grammar":[{"title":"Tính từ láy 形容词重叠","formula":"Tính từ đơn âm tiết thành AA, tính từ hai âm tiết thành AABB","explain":"Tính từ láy lại để nhấn mạnh mức độ, thường mang sắc thái yêu mến hoặc làm câu sinh động hơn. Dạng láy thường đứng trước danh từ có 的, hoặc đứng sau động từ làm trạng ngữ.","tip":"Dạng AABB như 高高兴兴 thường đi với 地 trước động từ.","examples":"我再给她买个大大的生日蛋糕。 (Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo.) — Tôi sẽ mua thêm cho con bé một cái bánh sinh nhật thật to. 这只猫小小的，真让人喜欢。 (Zhè zhī māo xiǎoxiǎo de, zhēn ràng rén xǐhuan.) — Con mèo này nhỏ xíu, thật khiến người ta thích. 一雪的女儿每天都漂漂亮亮的。 (Yìxuě de nǚ'ér měitiān dōu piàopiàoliàngliàng de.) — Con gái của Nhất Tuyết ngày nào cũng xinh xắn.","error":"Không láy bừa mọi tính từ, chỉ dùng dạng láy mà sách và thói quen dùng, ví dụ không nói 很高高."},{"title":"Cụm cố định 什么的","formula":"Liệt kê vài thứ + 什么的","explain":"什么的 đứng cuối chuỗi liệt kê để nói còn nhiều thứ tương tự nữa, không cần kể hết. Trước nó thường có 还有.","tip":"什么的 luôn đứng ở cuối chuỗi, không đứng đầu câu.","examples":"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。 (Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.) — Vẽ nhà của chúng ta! Có bố, mẹ, em trai, còn có con chó đen, con mèo trắng các thứ nữa. 桌子上有电脑、杯子、书和画笔什么的。 (Zhuōzi shàng yǒu diànnǎo, bēizi, shū hé huàbǐ shénmede.) — Trên bàn có máy tính, cốc, sách và bút vẽ các thứ. 她拿来了一些水、面包和苹果什么的。 (Tā ná lái le yìxiē shuǐ, miànbāo hé píngguǒ shénmede.) — Cô ấy mang đến một ít nước, bánh mì và táo các thứ.","error":"Đừng dùng 什么的 khi chỉ có một thứ duy nhất, vì nó hàm ý còn nhiều thứ tương tự chưa kể."},{"title":"Trợ từ kết cấu 地","formula":"Tính từ (thường đã láy) + 地 + động từ","explain":"地 nối tính từ hoặc cụm tính từ với động từ, nói rõ cách thức hành động diễn ra như thế nào.","tip":"地 đọc là de thanh nhẹ, khác với 的 và 得.","examples":"过生日就要吃好吃的，还要高高兴兴地玩。 (Guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.) — Mừng sinh nhật thì phải ăn ngon, còn phải chơi thật vui vẻ. 老师早早地到了教室。 (Lǎoshī zǎozǎo de dào le jiàoshì.) — Thầy cô đến lớp từ rất sớm. 爸爸很快地吃完早饭，就去上班了。 (Bàba hěn kuài de chī wán zǎofàn, jiù qù shàngbān le.) — Bố ăn sáng xong rất nhanh rồi đi làm.","error":"Đừng nhầm 地 với 的: 地 đứng trước động từ để nói cách làm, còn 的 đứng trước danh từ."}],"han":"小雪，生日快乐！","natural":["Mạch ý: bố mẹ bàn quà sinh nhật, tặng bút vẽ cho Tiểu Tuyết, bữa tiệc với mì sợi và bánh kem, nhật ký kể lại một ngày vui.","Tính từ láy: đơn âm tiết thành AA như 大大, 长长, hai âm tiết thành AABB như 高高兴兴, 舒舒服服, đều nhấn mạnh mức độ hoặc tỏ ý yêu mến.","什么的 đứng cuối chuỗi liệt kê để nói còn nhiều thứ tương tự; 地 đứng giữa tính từ (thường đã láy) và động từ để nói cách thức hành động."],"num":6,"photoPrefix":"h2-6","pinyin":"Xiǎoxuě, shēngrì kuàilè!","structures":[{"han":"我再给她买个大大的生日蛋糕。","pinyin":"Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo.","meaning":"Tôi sẽ mua thêm cho con bé một cái bánh sinh nhật thật to.","note":"大大的 là dạng láy của tính từ đơn âm tiết 大, nhấn mạnh cái bánh rất to và tỏ ý yêu thương; 再 ở đây nghĩa là mua thêm."},{"han":"画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。","pinyin":"Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.","meaning":"Vẽ nhà của chúng ta! Có bố, mẹ, em trai, còn có con chó đen, con mèo trắng các thứ nữa.","note":"什么的 đứng cuối chuỗi liệt kê, nghĩa là còn nhiều thứ tương tự nữa, không cần kể hết; trước nó thường có 还有."},{"han":"过生日就要吃好吃的，还要高高兴兴地玩。","pinyin":"Guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.","meaning":"Mừng sinh nhật thì phải ăn ngon, còn phải chơi thật vui vẻ.","note":"高高兴兴地 là tính từ hai âm tiết láy thành AABB rồi thêm 地, làm trạng ngữ nói cách chơi: chơi một cách vui vẻ."},{"han":"明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。","pinyin":"Míngtiān bú shàngxué, tāmen shuō yào shūshūfúfú de shuì yí jiào, ràng wǒmen wǎn diǎnr jiào tāmen qǐchuáng.","meaning":"Ngày mai không phải đi học, chúng bảo muốn ngủ một giấc thật thoải mái, nhờ chúng tôi gọi dậy muộn một chút.","note":"舒舒服服地 cũng là dạng AABB cộng 地, làm trạng ngữ cho 睡一觉; 晚点儿 là cách nói giảm nhẹ, muộn một chút."}],"theme":"Sinh nhật & gia đình","translation":"Tiểu Tuyết, chúc mừng sinh nhật!","vocab":[{"emoji":"🎂","example":"明天就是女儿的生日了。","examplePinyin":"Míngtiān jiù shì nǚ'ér de shēngrì le.","exampleVi":"Ngày mai là sinh nhật của con gái rồi.","meaning":"sinh nhật","pinyin":"shēngrì","pos":"Danh từ","word":"生日"},{"emoji":"🤔","example":"你不说，我还真忘了。","examplePinyin":"Nǐ bù shuō, wǒ hái zhēn wàng le.","exampleVi":"Bạn không nói thì tôi thật sự đã quên mất rồi.","meaning":"quên","pinyin":"wàng","pos":"Động từ","word":"忘"},{"emoji":"🎨","example":"她喜欢画画。","examplePinyin":"Tā xǐhuan huà huà.","exampleVi":"Cô ấy thích vẽ tranh.","meaning":"vẽ; bức tranh","pinyin":"huà","pos":"Động từ","word":"画"},{"emoji":"🖍️","example":"就送画笔吧！","examplePinyin":"Jiù sòng huàbǐ ba!","exampleVi":"Cứ tặng bút vẽ đi!","meaning":"bút vẽ, bút màu","pinyin":"huàbǐ","pos":"Danh từ","word":"画笔"},{"emoji":"🍰","example":"我再给她买个大大的生日蛋糕。","examplePinyin":"Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo.","exampleVi":"Tôi sẽ mua thêm cho con bé một cái bánh sinh nhật thật to.","meaning":"bánh ga tô, bánh sinh nhật","pinyin":"dàngāo","pos":"Danh từ","word":"蛋糕"},{"emoji":"😊","example":"小雪，生日快乐！","examplePinyin":"Xiǎoxuě, shēngrì kuàilè!","exampleVi":"Tiểu Tuyết, chúc mừng sinh nhật!","meaning":"vui vẻ, hạnh phúc","pinyin":"kuàilè","pos":"Tính từ","word":"快乐"},{"emoji":"📦","example":"你打开看看喜欢不喜欢。","examplePinyin":"Nǐ dǎkāi kànkan xǐhuan bu xǐhuan.","exampleVi":"Con mở ra xem có thích không.","meaning":"mở ra","pinyin":"dǎkāi","pos":"Động từ","word":"打开"},{"emoji":"📏","example":"长长的面条儿，大大的蛋糕。","examplePinyin":"Chángcháng de miàntiáor, dàdà de dàngāo.","exampleVi":"Mì sợi dài dài, bánh kem to to.","meaning":"dài","pinyin":"cháng","pos":"Tính từ","word":"长"},{"emoji":"🐟","example":"还有鱼啊肉啊什么的，都是你喜欢吃的。","examplePinyin":"Hái yǒu yú a ròu a shénmede, dōu shì nǐ xǐhuan chī de.","exampleVi":"Còn có cá, thịt các thứ nữa, đều là món con thích ăn.","meaning":"cá","pinyin":"yú","pos":"Danh từ","word":"鱼"},{"emoji":"🍖","example":"我喜欢吃鱼，不喜欢吃肉。","examplePinyin":"Wǒ xǐhuan chī yú, bù xǐhuan chī ròu.","exampleVi":"Tôi thích ăn cá, không thích ăn thịt.","meaning":"thịt","pinyin":"ròu","pos":"Danh từ","word":"肉"},{"emoji":"🎉","example":"过生日真好啊！","examplePinyin":"Guò shēngrì zhēn hǎo a!","exampleVi":"Được mừng sinh nhật thật là thích!","meaning":"trải qua, đón (sinh nhật, ngày lễ)","pinyin":"guò","pos":"Động từ","word":"过"},{"emoji":"✨","example":"过生日就要吃好吃的，还要高高兴兴地玩。","examplePinyin":"Guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.","exampleVi":"Mừng sinh nhật thì phải ăn ngon, còn phải chơi thật vui vẻ.","meaning":"trợ từ nối trạng ngữ với động từ","pinyin":"de","pos":"Trợ từ","word":"地"},{"emoji":"🛏️","example":"孩子们早早地就上床了。","examplePinyin":"Háizimen zǎozǎo de jiù shàng chuáng le.","exampleVi":"Bọn trẻ đã lên giường đi ngủ từ sớm.","meaning":"giường","pinyin":"chuáng","pos":"Danh từ","word":"床"},{"emoji":"😌","example":"他们说要舒舒服服地睡一觉。","examplePinyin":"Tāmen shuō yào shūshūfúfú de shuì yí jiào.","exampleVi":"Chúng bảo muốn ngủ một giấc thật thoải mái.","meaning":"thoải mái, dễ chịu","pinyin":"shūfu","pos":"Tính từ","word":"舒服"}]},{"emoji":"🏀","grammar":[{"title":"Câu rút gọn 一……就……","formula":"一 + hành động 1 + 就 + hành động 2","explain":"一……就…… nói hai hành động xảy ra gần như ngay nhau: vừa làm xong việc trước thì làm ngay việc sau.","tip":"就 nhấn mạnh sự tiếp nối nhanh, đừng bỏ 就 ở vế sau.","examples":"你怎么一下课就往外跑？ (Nǐ zěnme yí xiàkè jiù wǎng wài pǎo?) — Sao bạn vừa tan học đã chạy ra ngoài? 我一到家，妈妈就打来电话了。 (Wǒ yí dào jiā, māma jiù dǎ lái diànhuà le.) — Tôi vừa về đến nhà thì mẹ gọi điện đến. 一到星期六，陈天中就跟同学去打篮球。 (Yí dào Xīngqītiān, Chén Tiānzhōng jiù gēn tóngxué qù dǎ lánqiú.) — Cứ đến thứ Bảy là Trần Thiên Trung đi đánh bóng rổ cùng bạn.","error":"Đừng quên 就 ở vế sau, nếu thiếu 就 thì câu mất ý tiếp nối ngay lập tức."},{"title":"Bổ ngữ trạng thái (1) 状态补语（1）","formula":"Động từ + 得 + tính từ hoặc cụm tính từ","explain":"Động từ cộng 得 rồi cộng tính từ để nói kết quả hoặc mức độ của hành động, ví dụ chạy nhanh hay chậm, chơi vui hay không.","tip":"Phủ định thì thêm 不 trước tính từ, ví dụ 跑得不快. Hỏi mức độ thì dùng 怎么样, ví dụ 你跑得怎么样？","examples":"我踢得还可以。 (Wǒ tī de hái kěyǐ.) — Tôi đá cũng tạm được. 他们玩得很高兴。 (Tāmen wán de hěn gāoxìng.) — Họ chơi rất vui. 白家月跑得不快。 (Bái Jiāyuè pǎo de bù kuài.) — Bạch Gia Nguyệt chạy không nhanh.","error":"Đừng viết 得 thành 的 hoặc 地, và đừng đặt tính từ ngay sau động từ mà thiếu 得."},{"title":"Bổ ngữ trạng thái (2) 状态补语（2）","formula":"Động từ + tân ngữ + động từ lặp lại + 得 + tính từ","explain":"Khi động từ có tân ngữ thì lặp lại động từ trước 得, còn tân ngữ đứng sau động từ lần đầu. Đây là dạng mở rộng của bổ ngữ trạng thái.","tip":"Động từ lặp lại giữ nguyên dạng, không thêm 了 vào động từ lần đầu.","examples":"我游泳游得不快。 (Wǒ yóuyǒng yóu de bù kuài.) — Tôi bơi không nhanh. 你篮球打得怎么样？ (Nǐ lánqiú dǎ de zěnmeyàng?) — Bạn đánh bóng rổ thế nào? 白家月写汉字写得很好看。 (Bái Jiāyuè xiě Hànzì xiě de hěn hǎokàn.) — Bạch Gia Nguyệt viết chữ Hán rất đẹp.","error":"Đừng viết 我游泳得不快 mà thiếu động từ lặp lại, vì tân ngữ 游泳 đã chiếm chỗ sau động từ."}],"han":"他篮球打得很好","natural":["Mạch ý: An Ni hỏi Thiên Trung về bóng rổ, hai người nói về các môn thể thao yêu thích, rồi nhật ký kể sở thích thể thao từ nhỏ.","一……就…… dùng khi hành động sau xảy ra ngay sau hành động trước, chủ ngữ giống nhau thì đứng trước 一, khác nhau thì mỗi chủ ngữ đứng trước một vế.","Bổ ngữ trạng thái dùng 得 sau động từ; với từ ly hợp như 游泳 phải lặp động từ, với động từ có tân ngữ như 打篮球 thì đưa tân ngữ lên trước động từ."],"num":7,"photoPrefix":"h2-7","pinyin":"Tā lánqiú dǎ de hěn hǎo","structures":[{"han":"你怎么一下课就往外跑？","pinyin":"Nǐ zěnme yí xiàkè jiù wǎng wài pǎo?","meaning":"Sao bạn vừa tan học đã chạy ra ngoài?","note":"一……就…… nói hành động sau xảy ra ngay sau hành động trước; ở đây vừa tan học đã chạy ra ngoài, nhấn mạnh sự gấp gáp."},{"han":"一到星期天就跟朋友们去踢球。","pinyin":"Yí dào Xīngqītiān jiù gēn péngyoumen qù tī qiú.","meaning":"Cứ đến Chủ nhật là tôi cùng các bạn đi đá bóng.","note":"一到星期天 là điều kiện thời gian, 就 nối kết quả: cứ đến Chủ nhật là đi đá bóng với bạn bè."},{"han":"你篮球打得怎么样？","pinyin":"Nǐ lánqiú dǎ de zěnmeyàng?","meaning":"Bạn chơi bóng rổ thế nào?","note":"篮球 đặt trước động từ 打 để làm rõ tân ngữ, rồi 打得怎么样 hỏi mức độ chơi ra sao; đây là mẫu trạng ngữ bổ ngữ với động từ có tân ngữ."},{"han":"我游泳游得不快。","pinyin":"Wǒ yóuyǒng yóu de bú kuài.","meaning":"Tôi bơi không nhanh.","note":"游泳 là từ ly hợp nên khi thêm bổ ngữ trạng thái phải lặp lại động từ 游: 游泳游得不快."}],"theme":"Thể thao & vận động","translation":"Cậu ấy chơi bóng rổ rất giỏi","vocab":[{"emoji":"➡️","example":"你是什么时候从北京回来的？","examplePinyin":"Nǐ shì shénme shíhou cóng Běijīng huílái de?","exampleVi":"Bạn trở về từ Bắc Kinh lúc nào?","meaning":"từ (nơi nào đó)","pinyin":"cóng","pos":"Giới từ","word":"从"},{"emoji":"🧭","example":"你怎么一下课就往外跑？","examplePinyin":"Nǐ zěnme yí xiàkè jiù wǎng wài pǎo?","exampleVi":"Sao bạn vừa tan học đã chạy ra ngoài?","meaning":"hướng về, về phía","pinyin":"wǎng","pos":"Giới từ","word":"往"},{"emoji":"🏃","example":"你跑得快不快？","examplePinyin":"Nǐ pǎo de kuài bu kuài?","exampleVi":"Bạn chạy có nhanh không?","meaning":"chạy","pinyin":"pǎo","pos":"Động từ","word":"跑"},{"emoji":"🏀","example":"我跟同学说好了，一起去打篮球。","examplePinyin":"Wǒ gēn tóngxué shuōhǎo le, yìqǐ qù dǎ lánqiú.","exampleVi":"Tôi đã hẹn với bạn học, cùng nhau đi chơi bóng rổ.","meaning":"chơi (bóng); đánh","pinyin":"dǎ","pos":"Động từ","word":"打"},{"emoji":"🏀","example":"你篮球打得怎么样？","examplePinyin":"Nǐ lánqiú dǎ de zěnmeyàng?","exampleVi":"Bạn chơi bóng rổ thế nào?","meaning":"bóng rổ","pinyin":"lánqiú","pos":"Danh từ","word":"篮球"},{"emoji":"⚽","example":"你还喜欢什么运动？","examplePinyin":"Nǐ hái xǐhuan shénme yùndòng?","exampleVi":"Bạn còn thích môn thể thao nào nữa?","meaning":"thể thao, vận động","pinyin":"yùndòng","pos":"Danh từ","word":"运动"},{"emoji":"🦶","example":"我还喜欢踢足球。","examplePinyin":"Wǒ hái xǐhuan tī zúqiú.","exampleVi":"Tôi còn thích đá bóng.","meaning":"đá","pinyin":"tī","pos":"Động từ","word":"踢"},{"emoji":"⚽","example":"现在我足球踢得不错。","examplePinyin":"Xiànzài wǒ zúqiú tī de búcuò.","exampleVi":"Bây giờ tôi đá bóng cũng khá tốt.","meaning":"bóng đá","pinyin":"zúqiú","pos":"Danh từ","word":"足球"},{"emoji":"⚽","example":"一到星期天就跟朋友们去踢球。","examplePinyin":"Yí dào Xīngqītiān jiù gēn péngyoumen qù tī qiú.","exampleVi":"Cứ đến Chủ nhật là cùng các bạn đi đá bóng.","meaning":"quả bóng","pinyin":"qiú","pos":"Danh từ","word":"球"},{"emoji":"✨","example":"我踢得还可以。","examplePinyin":"Wǒ tī de hái kěyǐ.","exampleVi":"Tôi đá cũng tạm được.","meaning":"trợ từ nối bổ ngữ trạng thái","pinyin":"de","pos":"Trợ từ","word":"得"},{"emoji":"🏃","example":"我跑得不快，也不太喜欢跑步。","examplePinyin":"Wǒ pǎo de bú kuài, yě bú tài xǐhuan pǎobù.","exampleVi":"Tôi chạy không nhanh, cũng không thích chạy bộ lắm.","meaning":"chạy bộ","pinyin":"pǎobù","pos":"Động từ","word":"跑步"},{"emoji":"🏊","example":"那你喜欢游泳吗？","examplePinyin":"Nà nǐ xǐhuan yóuyǒng ma?","exampleVi":"Vậy bạn có thích bơi không?","meaning":"bơi lội","pinyin":"yóuyǒng","pos":"Động từ","word":"游泳"},{"emoji":"🏊","example":"喜欢，但我游泳游得不快。","examplePinyin":"Xǐhuan, dàn wǒ yóuyǒng yóu de bú kuài.","exampleVi":"Thích, nhưng tôi bơi không nhanh.","meaning":"bơi","pinyin":"yóu","pos":"Động từ","word":"游"},{"emoji":"❤️","example":"我的爱好是运动。","examplePinyin":"Wǒ de àihào shì yùndòng.","exampleVi":"Sở thích của tôi là thể thao.","meaning":"sở thích; yêu thích","pinyin":"àihào","pos":"Danh từ","word":"爱好"},{"emoji":"▶️","example":"从上小学开始，我每天都跟爸爸去运动。","examplePinyin":"Cóng shàng xiǎoxué kāishǐ, wǒ měitiān dōu gēn bàba qù yùndòng.","exampleVi":"Từ khi học tiểu học, ngày nào tôi cũng cùng bố đi tập thể thao.","meaning":"bắt đầu; sự bắt đầu","pinyin":"kāishǐ","pos":"Động từ","word":"开始"}]},{"emoji":"⌚","grammar":[{"title":"Câu so sánh (1) 比较句（1）","formula":"A + 比 + B + tính từ hoặc cụm tính từ","explain":"Dùng giới từ 比 để so sánh tính chất hoặc trạng thái của A và B, A hơn B ở điểm mà tính từ nêu ra.","tip":"Tính từ trong câu 比 thường đứng một mình, không cần 很.","examples":"我也觉得左边的比右边的好看。 (Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.) — Tôi cũng thấy cái bên trái đẹp hơn cái bên phải. 今天比昨天冷。 (Jīntiān bǐ zuótiān lěng.) — Hôm nay lạnh hơn hôm qua. 他觉得踢足球比打篮球有意思。 (Tā juéde tī zúqiú bǐ dǎ lánqiú yǒu yìsi.) — Anh ấy thấy đá bóng thú vị hơn đánh bóng rổ.","error":"Đừng thêm 很 hoặc 非常 trước tính từ trong câu 比, đó là lỗi mà điểm so sánh (2) nói rõ."},{"title":"Câu so sánh (2) 比较句（2）","formula":"A + 比 + B + (还/更) + tính từ","explain":"Trong câu 比, trước tính từ không dùng phó từ mức độ như 很 hoặc 非常, nhưng có thể dùng 还 và 更 để nhấn mạnh mức độ cao hơn.","tip":"更 nghĩa là còn hơn nữa, 还 nghĩa là vẫn còn hơn, cả hai đều đứng trước tính từ.","examples":"我看网上说这个电影比那个爱情片更有意思。 (Wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.) — Tôi đọc trên mạng nói bộ phim này thú vị hơn bộ phim tình cảm kia. 今天比昨天更热。 (Jīntiān bǐ zuótiān gèng rè.) — Hôm nay nóng hơn hôm qua. 我觉得奶茶比牛奶还好喝。 (Wǒ juéde nǎichá bǐ niúnǎi hái hǎohē.) — Tôi thấy trà sữa còn ngon hơn sữa.","error":"Đừng viết 今天比昨天很冷, vì 很 không đi được với 比, hãy dùng 更 hoặc 还."},{"title":"Câu phức chuyển ý 虽然……，但是……","formula":"虽然 + vế 1, 但是 + vế 2","explain":"虽然……，但是…… tạo câu phức chuyển ý: vế trước nêu sự thật, vế sau nêu kết quả trái với suy đoán thường gặp. Hai từ có thể dùng thành đôi hoặc chỉ dùng một trong hai.","tip":"虽然 đứng đầu vế trước, 但是 đứng đầu vế sau, hai vế ngăn nhau bằng dấu phẩy.","examples":"虽然你忘了，但是我记得。 (Suīrán nǐ wàng le, dànshì wǒ jìde.) — Dù bạn quên rồi, nhưng tôi vẫn nhớ. 外边下雪了，但是不太冷。 (Wàibian xià xuě le, dànshì bù tài lěng.) — Bên ngoài tuyết rơi rồi, nhưng không lạnh lắm. 虽然觉得有点儿累，我还是走回家了。 (Suīrán juéde yǒudiǎnr lèi, wǒ háishi zǒu huí jiā le.) — Dù thấy hơi mệt, tôi vẫn đi bộ về nhà.","error":"Đừng dùng 虽然 mà quên mất ý chuyển ý ở vế sau, câu sẽ thiếu vế đối lập và nghe chưa trọn."}],"han":"虽然你忘了，但是我记得","natural":["Mạch ý: hai vợ chồng đi mua đồng hồ, bàn xem phim nào, rồi chồng bí mật tổ chức sinh nhật cho vợ ở nhà hàng, câu chuyện được kể lại ở cảnh cuối.","Câu 比 có dạng A 比 B + tính từ; trong câu 比 không dùng 很 hay 非常 trước tính từ, muốn tăng mức độ thì dùng 还 hoặc 更.","虽然 và 但是 tạo thành câu phức chuyển ý, có thể dùng cả cặp hoặc chỉ dùng một từ, vế sau thường nói kết quả trái với suy đoán."],"num":8,"photoPrefix":"h2-8","pinyin":"Suīrán nǐ wàng le, dànshì wǒ jìde","structures":[{"han":"我也觉得左边的比右边的好看。","pinyin":"Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.","meaning":"Tôi cũng thấy cái bên trái đẹp hơn cái bên phải.","note":"左边的比右边的好看 là mẫu A 比 B + tính từ: A là cái bên trái, B là cái bên phải, 好看 là tính từ so sánh."},{"han":"我看网上说这个电影比那个爱情片更有意思。","pinyin":"Zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","meaning":"Tôi đọc trên mạng nói bộ phim này thú vị hơn bộ phim tình cảm kia.","note":"更有意思 dùng 更 trước tính từ để tăng mức độ trong câu 比; không được dùng 很 hay 非常 trong câu 比."},{"han":"虽然你忘了，但是我记得。","pinyin":"Suīrán nǐ wàng le, dànshì wǒ jìde.","meaning":"Tuy bạn quên mất, nhưng tôi vẫn nhớ.","note":"虽然 mở đầu vế nhượng bộ, 但是 mở đầu vế chuyển ý; hai từ có thể dùng cùng nhau hoặc chỉ dùng một trong hai."},{"han":"虽然花了一些钱，但是我们过了一个快乐的生日。","pinyin":"Suīrán huā le yìxiē qián, dànshì wǒmen guò le yí ge kuàilè de shēngrì.","meaning":"Tuy tiêu tốn một ít tiền, nhưng chúng tôi đã có một sinh nhật vui vẻ.","note":"虽然花了一些钱 là vế nhượng bộ, 但是我们过了一个快乐的生日 là kết quả trái với dự đoán: tốn tiền nhưng vẫn vui."},{"han":"这个电影比那个爱情片更有意思。","pinyin":"Zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","meaning":"Bộ phim này thú vị hơn bộ phim tình cảm kia.","note":""}],"theme":"Sinh nhật bất ngờ & so sánh","translation":"Tuy bạn quên mất, nhưng tôi vẫn nhớ","vocab":[{"emoji":"⌚","example":"你看，这两块手表怎么样？","examplePinyin":"Nǐ kàn, zhè liǎng kuài shǒubiǎo zěnmeyàng?","exampleVi":"Bạn xem, hai cái đồng hồ này thế nào?","meaning":"đồng hồ đeo tay","pinyin":"shǒubiǎo","pos":"Danh từ","word":"手表"},{"emoji":"⬅️","example":"我喜欢左边这个。","examplePinyin":"Wǒ xǐhuan zuǒbian zhège.","exampleVi":"Tôi thích cái bên trái này.","meaning":"bên trái","pinyin":"zuǒbian","pos":"Danh từ","word":"左边"},{"emoji":"⬅️","example":"往左走就是饭馆。","examplePinyin":"Wǎng zuǒ zǒu jiù shì fànguǎn.","exampleVi":"Rẽ trái là đến nhà hàng.","meaning":"trái","pinyin":"zuǒ","pos":"Danh từ","word":"左"},{"emoji":"⚖️","example":"左边的比右边的好看。","examplePinyin":"Zuǒbian de bǐ yòubian de hǎokàn.","exampleVi":"Cái bên trái đẹp hơn cái bên phải.","meaning":"hơn; so với","pinyin":"bǐ","pos":"Giới từ","word":"比"},{"emoji":"➡️","example":"请往右边看。","examplePinyin":"Qǐng wǎng yòubian kàn.","exampleVi":"Xin hãy nhìn sang bên phải.","meaning":"bên phải","pinyin":"yòubian","pos":"Danh từ","word":"右边"},{"emoji":"➡️","example":"向右转。","examplePinyin":"Xiàng yòu zhuǎn.","exampleVi":"Rẽ phải.","meaning":"phải","pinyin":"yòu","pos":"Danh từ","word":"右"},{"emoji":"🧠","example":"我记得你喜欢看爱情片。","examplePinyin":"Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn.","exampleVi":"Tôi nhớ bạn thích xem phim tình cảm.","meaning":"nhớ","pinyin":"jìde","pos":"Động từ","word":"记得"},{"emoji":"🎬","example":"我们看那个爱情片，怎么样？","examplePinyin":"Wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?","exampleVi":"Chúng ta xem bộ phim tình cảm kia nhé, thế nào?","meaning":"phim tình cảm","pinyin":"àiqíngpiàn","pos":"Danh từ","word":"爱情片"},{"emoji":"😄","example":"这个电影比那个爱情片更有意思。","examplePinyin":"Zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","exampleVi":"Bộ phim này thú vị hơn bộ phim tình cảm kia.","meaning":"thú vị, có ý nghĩa","pinyin":"yǒu yìsi","pos":"Tính từ","word":"有意思"},{"emoji":"🍽️","example":"怎么点这么多菜？","examplePinyin":"Zěnme diǎn zhème duō cài?","exampleVi":"Sao lại gọi nhiều món thế?","meaning":"gọi (món ăn)","pinyin":"diǎn","pos":"Động từ","word":"点"},{"emoji":"🤔","example":"虽然你忘了，但是我记得。","examplePinyin":"Suīrán nǐ wàng le, dànshì wǒ jìde.","exampleVi":"Tuy bạn quên mất, nhưng tôi vẫn nhớ.","meaning":"tuy, mặc dù","pinyin":"suīrán","pos":"Liên từ","word":"虽然"},{"emoji":"🔄","example":"虽然花了一些钱，但是我们过了一个快乐的生日。","examplePinyin":"Suīrán huā le yìxiē qián, dànshì wǒmen guò le yí ge kuàilè de shēngrì.","exampleVi":"Tuy tiêu tốn một ít tiền, nhưng chúng tôi đã có một sinh nhật vui vẻ.","meaning":"nhưng, tuy nhiên","pinyin":"dànshì","pos":"Liên từ","word":"但是"},{"emoji":"💰","example":"今天花了不少钱吧？","examplePinyin":"Jīntiān huā le bùshǎo qián ba?","exampleVi":"Hôm nay tiêu không ít tiền nhỉ?","meaning":"tiêu (tiền)","pinyin":"huā","pos":"Động từ","word":"花"},{"emoji":"👩","example":"虽然妻子忘了今天是自己的生日，但是丈夫记得。","examplePinyin":"Suīrán qīzi wàng le jīntiān shì zìjǐ de shēngrì, dànshì zhàngfu jìde.","exampleVi":"Tuy người vợ quên mất hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ.","meaning":"vợ","pinyin":"qīzi","pos":"Danh từ","word":"妻子"},{"emoji":"👨","example":"丈夫请妻子去饭馆吃饭。","examplePinyin":"Zhàngfu qǐng qīzi qù fànguǎn chī fàn.","exampleVi":"Người chồng mời vợ đi ăn ở nhà hàng.","meaning":"chồng","pinyin":"zhàngfu","pos":"Danh từ","word":"丈夫"},{"emoji":"🍜","example":"丈夫请妻子去饭馆吃饭、去电影院看电影。","examplePinyin":"Zhàngfu qǐng qīzi qù fànguǎn chī fàn, qù diànyǐngyuàn kàn diànyǐng.","exampleVi":"Người chồng mời vợ đi ăn ở nhà hàng, đi xem phim ở rạp chiếu phim.","meaning":"nhà hàng, quán ăn","pinyin":"fànguǎn","pos":"Danh từ","word":"饭馆"}]},{"emoji":"🧋","grammar":[{"title":"Câu so sánh (3) với 没有","formula":"A + 没有 + B + tính từ","explain":"没有 dùng trong câu so sánh mang nghĩa không bằng, A kém B ở điểm mà tính từ nêu ra. Trước tính từ có thể thêm 这么 hoặc 那么 để nói B cao hơn hẳn.","tip":"Dạng khẳng định tương ứng là 有, thường dùng trong câu hỏi so sánh, ví dụ 妹妹有姐姐高吗？","examples":"儿子的个子没有他那么高。 (Érzi de gèzi méiyǒu tā nàme gāo.) — Con trai không cao bằng cậu ấy. 昨天没有今天这么冷。 (Zuótiān méiyǒu jīntiān zhème lěng.) — Hôm qua không lạnh bằng hôm nay. 这块手表没有那块好看。 (Zhè kuài shǒubiǎo méiyǒu nà kuài hǎokàn.) — Chiếc đồng hồ này không đẹp bằng chiếc kia.","error":"Đừng nhầm 没有 ở đây với phủ định của 有 trong câu sở hữu, ở đây nó là dấu hiệu so sánh."},{"title":"Động từ 离","formula":"A + 离 + B + (xa/gần/khoảng cách)","explain":"Động từ 离 nói khoảng cách về chỗ ở hoặc thời gian giữa A và B, ví dụ trường cách bệnh viện bao xa, còn mấy ngày nữa đến sinh nhật.","tip":"离 luôn đi với hai địa điểm hoặc hai thời điểm, sau nó là từ chỉ xa, gần hoặc số ngày.","examples":"咖啡店离这儿有点儿远。 (Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.) — Quán cà phê cách chỗ này hơi xa. 学校离医院不远。 (Xuéxiào lí yīyuàn bù yuǎn.) — Trường học cách bệnh viện không xa. 现在离我的生日还有三天。 (Xiànzài lí wǒ de shēngrì hái yǒu sān tiān.) — Bây giờ còn ba ngày nữa là đến sinh nhật tôi.","error":"Đừng dùng 离 khi muốn nói đi từ đâu đến đâu, đó là việc của 从 hoặc 到."},{"title":"Bổ ngữ thời lượng (1) 时量补语（1）","formula":"Chủ ngữ + động từ + bổ ngữ thời lượng","explain":"Cụm chỉ khoảng thời gian đứng sau động từ làm bổ ngữ thời lượng, nói hành động kéo dài bao lâu. Khi động từ có tân ngữ là danh từ đồ vật thì tân ngữ thường đứng sau bổ ngữ, còn tân ngữ là người hoặc đại từ thì đứng trước bổ ngữ, hoặc lặp lại động từ.","tip":"Động từ li hợp như 游泳、跑步 thì lặp lại phần động từ trước bổ ngữ, ví dụ 游泳游了一个下午. Khi sau động từ có 了 và cuối câu cũng có 了 thì hành động vẫn đang tiếp diễn.","examples":"走半个多小时就到了。 (Zǒu bàn gè duō xiǎoshí jiù dào le.) — Đi bộ hơn nửa tiếng là tới. 他们学了两年。 (Tāmen xué le liǎng nián.) — Họ đã học hai năm. 我们休息十分钟。 (Wǒmen xiūxi shí fēnzhōng.) — Chúng tôi nghỉ mười phút.","error":"Đừng đặt bổ ngữ thời lượng trước động từ, và đừng quên lặp động từ khi động từ đã có tân ngữ."}],"han":"我去买杯奶茶","natural":["Mạch ý: hai vợ chồng đi mua quần cho con trai, bàn chuyện uống trà sữa hay cà phê, rồi đi bộ về nhà, nhật ký kể lại một ngày đi dạo.","没有 dùng trong câu so sánh có dạng A没有B + tính từ, câu hỏi so sánh dùng 有; 离 nói khoảng cách không gian hoặc thời gian theo mẫu A离B.","Bổ ngữ thời lượng đứng sau động từ để nói hành động kéo dài bao lâu; có tân ngữ thì tân ngữ thường đứng sau bổ ngữ, tân ngữ là người hoặc đại từ thì đứng trước bổ ngữ."],"num":9,"photoPrefix":"h2-9","pinyin":"Wǒ qù mǎi bēi nǎichá","structures":[{"han":"儿子的个子没有他那么高。","pinyin":"Érzi de gèzi méiyǒu tā nàme gāo.","meaning":"Con trai tôi không cao bằng cậu ấy.","note":"没有……那么高 là mẫu A没有B + tính từ, có thể thêm 那么 trước tính từ để nhấn mạnh mức độ của B; 儿子 không cao bằng cậu bé kia."},{"han":"咖啡店离这儿有点儿远。","pinyin":"Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.","meaning":"Quán cà phê cách đây hơi xa.","note":"离……有点儿远 dùng động từ 离 nói khoảng cách giữa hai nơi: quán cà phê cách đây hơi xa."},{"han":"走半个多小时就到了。","pinyin":"Zǒu bàn ge duō xiǎoshí jiù dào le.","meaning":"Đi bộ hơn nửa tiếng là đến.","note":"走半个多小时 là bổ ngữ thời lượng sau động từ 走, nói đi bộ mất bao lâu; 就到了 nói kết quả."},{"han":"我们没有买到喜欢的衣服。","pinyin":"","meaning":"Chúng tôi không mua được bộ quần áo nào mình thích.","note":"没有买到 dùng 没有 + động từ + 到, nói không mua được thứ mình thích; 到 ở đây là bổ ngữ kết quả chỉ hành động đạt mục đích."}],"theme":"Mua sắm & đi bộ về nhà","translation":"Tôi đi mua một cốc trà sữa","vocab":[{"emoji":"😞","example":"儿子的裤子坏了，我们给他买条新的吧。","examplePinyin":"Érzi de kùzi huài le, wǒmen gěi tā mǎi tiáo xīn de ba.","exampleVi":"Quần của con trai bị rách rồi, chúng ta mua cho con một cái mới nhé.","meaning":"hỏng, rách","pinyin":"huài","pos":"Tính từ","word":"坏"},{"emoji":"↔️","example":"旁边那个男孩儿就穿了这样的裤子。","examplePinyin":"Pángbiān nàge nánháir jiù chuān le zhèyàng de kùzi.","exampleVi":"Cậu bé bên cạnh đang mặc chiếc quần như thế này.","meaning":"bên cạnh","pinyin":"pángbiān","pos":"Danh từ","word":"旁边"},{"emoji":"👦","example":"旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","examplePinyin":"Pángbiān nàge nánháir jiù chuān le zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!","exampleVi":"Cậu bé bên cạnh đang mặc chiếc quần như thế này, tôi thấy đẹp lắm!","meaning":"cậu bé, bé trai","pinyin":"nánháir","pos":"Danh từ","word":"男孩儿"},{"emoji":"👍","example":"我觉得这样的裤子很好看。","examplePinyin":"Wǒ juéde zhèyàng de kùzi hěn hǎokàn.","exampleVi":"Tôi thấy chiếc quần như thế này đẹp lắm.","meaning":"như thế này, như vậy","pinyin":"zhèyàng","pos":"Đại từ","word":"这样"},{"emoji":"📏","example":"儿子的个子没有他那么高。","examplePinyin":"Érzi de gèzi méiyǒu tā nàme gāo.","exampleVi":"Con trai tôi không cao bằng cậu ấy.","meaning":"chiều cao, vóc dáng","pinyin":"gèzi","pos":"Danh từ","word":"个子"},{"emoji":"👉","example":"儿子的个子没有他那么高。","examplePinyin":"Érzi de gèzi méiyǒu tā nàme gāo.","exampleVi":"Con trai tôi không cao bằng cậu ấy.","meaning":"đến như vậy, đến thế","pinyin":"nàme","pos":"Đại từ","word":"那么"},{"emoji":"📏","example":"儿子的个子没有他那么高，穿上就不会太好看。","examplePinyin":"Érzi de gèzi méiyǒu tā nàme gāo, chuānshang jiù bú huì tài hǎokàn.","exampleVi":"Con trai tôi không cao bằng cậu ấy, mặc vào sẽ không đẹp lắm.","meaning":"cao","pinyin":"gāo","pos":"Tính từ","word":"高"},{"emoji":"🚪","example":"门口有家奶茶店。","examplePinyin":"Ménkǒu yǒu jiā nǎichádiàn.","exampleVi":"Ở cửa có một quán trà sữa.","meaning":"cửa ra vào, cổng","pinyin":"ménkǒu","pos":"Danh từ","word":"门口"},{"emoji":"☕","example":"我想喝咖啡，还是去咖啡店吧。","examplePinyin":"Wǒ xiǎng hē kāfēi, háishi qù kāfēidiàn ba.","exampleVi":"Tôi muốn uống cà phê, hay là đến quán cà phê đi.","meaning":"cà phê","pinyin":"kāfēi","pos":"Danh từ","word":"咖啡"},{"emoji":"📍","example":"咖啡店离这儿有点儿远。","examplePinyin":"Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.","exampleVi":"Quán cà phê cách đây hơi xa.","meaning":"cách (khoảng cách)","pinyin":"lí","pos":"Động từ","word":"离"},{"emoji":"📍","example":"这里离家很近，还是走路吧。","examplePinyin":"Zhèlǐ lí jiā hěn jìn, háishi zǒulù ba.","exampleVi":"Ở đây cách nhà rất gần, hay là đi bộ đi.","meaning":"gần","pinyin":"jìn","pos":"Tính từ","word":"近"},{"emoji":"🚶","example":"走半个多小时就到了。","examplePinyin":"Zǒu bàn ge duō xiǎoshí jiù dào le.","exampleVi":"Đi bộ hơn nửa tiếng là đến.","meaning":"đi bộ","pinyin":"zǒulù","pos":"Động từ","word":"走路"},{"emoji":"📅","example":"这周刘明休息。","examplePinyin":"Zhè zhōu Liú Míng xiūxi.","exampleVi":"Tuần này Lưu Minh được nghỉ.","meaning":"tuần","pinyin":"zhōu","pos":"Danh từ","word":"周"}]},{"emoji":"📝","grammar":[{"title":"Câu chủ vị làm vị ngữ 主谓谓语句","formula":"Chủ ngữ + cụm chủ vị (chủ ngữ nhỏ + vị ngữ nhỏ)","explain":"Cụm chủ vị có thể làm vị ngữ để giải thích hoặc miêu tả chủ ngữ cả câu. Chủ ngữ trong cụm thường là một bộ phận của chủ ngữ chính hoặc liên quan chặt với nó.","tip":"Đừng thêm 的 giữa hai phần, đây không phải là cụm định ngữ.","examples":"我的书包你看见了吗？ (Wǒ de shūbāo nǐ kànjiàn le ma?) — Cặp sách của tôi bạn có thấy không? 弟弟手很小。 (Dìdi shǒu hěn xiǎo.) — Tay em trai rất nhỏ. 这件事他知道。 (Zhè jiàn shì tā zhīdào.) — Việc này anh ấy biết.","error":"Đừng đọc 我的书包你看见了吗 thành câu có hai chủ ngữ rời rạc, cả cụm 你看见了 mới là vị ngữ của 我的书包."},{"title":"Câu hỏi lựa chọn với 还是","formula":"(是) A + 还是 + B","explain":"Liên từ 还是 dùng trong câu hỏi để đưa ra lựa chọn, người nghe phải chọn một trong các phương án, không trả lời chỉ bằng 是 hay 不是.","tip":"还是 chỉ dùng trong câu hỏi, còn 或者 dùng trong câu trần thuật.","examples":"妈妈，是您准备考试还是我准备考试？ (Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?) — Mẹ ơi, là mẹ chuẩn bị thi hay con chuẩn bị thi? 你更喜欢打篮球、踢足球还是游泳？ (Nǐ gèng xǐhuan dǎ lánqiú, tī zúqiú háishi yóuyǒng?) — Bạn thích đánh bóng rổ, đá bóng hay bơi lội hơn? 我们什么时候去看电影？今天还是明天？ (Wǒmen shénme shíhou qù kàn diànyǐng? Jīntiān háishi míngtiān?) — Chúng ta khi nào đi xem phim? Hôm nay hay ngày mai?","error":"Đừng thêm 吗 vào cuối câu hỏi 还是, và đừng dùng 还是 trong câu trần thuật."},{"title":"Mẫu cố định 要/快/快要/就要……了","formula":"要/快/快要/就要 + động từ + 了","explain":"Mẫu này nói một việc sắp xảy ra. Nếu trong câu có trạng ngữ thời gian thì thường dùng 就要……了.","tip":"了 ở cuối câu là bắt buộc trong mẫu này, thiếu nó câu sẽ sai.","examples":"饭菜快要做好了。 (Fàncài kuàiyào zuò hǎo le.) — Cơm sắp xong rồi. 火车快开了。 (Huǒchē kuài kāi le.) — Tàu sắp chạy rồi. 我们下星期就要考试了。 (Wǒmen xià xīngqī jiù yào kǎoshì le.) — Tuần sau chúng ta sắp thi rồi.","error":"Đừng dùng mẫu này cho việc đã xảy ra rồi, nó chỉ nói việc sắp xảy ra."}],"han":"就要考试了","natural":["Mạch ý: bố giúp Tiểu Minh chuẩn bị đồ dùng trước ngày khai giảng, mẹ nhắc Tiểu Tuyết ôn bài trước kỳ thi, Tiểu Tuyết thi xong về nhà, nhật ký kể lại sự bận rộn của cả nhà.","Câu chủ vị làm vị ngữ có dạng chủ ngữ lớn + cụm chủ vị nhỏ làm vị ngữ, thường dùng để nhấn mạnh bộ phận nào đó của chủ ngữ lớn.","Câu hỏi lựa chọn dùng 还是 nối hai phương án, người nghe phải chọn một; mẫu 要/快/快要/就要……了 nói sự việc sắp xảy ra, có trạng ngữ thời gian thì thường dùng 就要."],"num":10,"photoPrefix":"h2-10","pinyin":"Jiù yào kǎoshì le","structures":[{"han":"我的书包你看见了吗？","pinyin":"Wǒ de shūbāo nǐ kànjiàn le ma?","meaning":"Cặp sách của con bố có nhìn thấy không?","note":"我的书包你看见了吗 là câu chủ vị làm vị ngữ: chủ ngữ cả câu là 我的书包, vị ngữ là một cụm chủ vị 你看见了吗, trong đó 你 là chủ ngữ nhỏ."},{"han":"妈妈，是您准备考试还是我准备考试？","pinyin":"Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?","meaning":"Mẹ ơi, là mẹ chuẩn bị thi hay là con chuẩn bị thi?","note":"还是 nối hai lựa chọn trong câu hỏi lựa chọn: là mẹ chuẩn bị thi hay là con chuẩn bị thi, người nghe phải chọn một trong hai."},{"han":"我就要考试了。","pinyin":"Wǒ jiù yào kǎoshì le.","meaning":"Tôi sắp thi rồi.","note":"就要考试了 dùng mẫu 就要……了 nói sự việc sắp xảy ra; vì có trạng ngữ thời gian nên dùng 就要 chứ không dùng 快要."},{"han":"饭菜快要做好了。","pinyin":"","meaning":"Cơm sắp nấu xong rồi.","note":"快要做好了 dùng mẫu 快要……了 nói cơm sắp nấu xong; 爸爸、妈妈比我们还忙 dùng 还 trong câu 比 để tăng mức độ bận rộn."}],"theme":"Khai giảng & kỳ thi","translation":"Sắp thi rồi","vocab":[{"emoji":"🎒","example":"小明，你们明天开学，你准备好了吗？","examplePinyin":"Xiǎomíng, nǐmen míngtiān kāixué, nǐ zhǔnbèi hǎo le ma?","exampleVi":"Tiểu Minh, ngày mai các con khai giảng, con đã chuẩn bị xong chưa?","meaning":"khai giảng, bắt đầu năm học","pinyin":"kāixué","pos":"Động từ","word":"开学"},{"emoji":"🚪","example":"书包在门后面。","examplePinyin":"Shūbāo zài mén hòumiàn.","exampleVi":"Cặp sách ở sau cửa.","meaning":"cửa","pinyin":"mén","pos":"Danh từ","word":"门"},{"emoji":"🔙","example":"书包在门后面。","examplePinyin":"Shūbāo zài mén hòumiàn.","exampleVi":"Cặp sách ở sau cửa.","meaning":"phía sau","pinyin":"hòumiàn","pos":"Danh từ","word":"后面"},{"emoji":"✏️","example":"书在床上，笔在桌子上。","examplePinyin":"Shū zài chuáng shang, bǐ zài zhuōzi shang.","exampleVi":"Sách ở trên giường, bút ở trên bàn.","meaning":"bút","pinyin":"bǐ","pos":"Danh từ","word":"笔"},{"emoji":"🤝","example":"这次爸爸帮你，下次你自己准备，好不好？","examplePinyin":"Zhè cì bàba bāng nǐ, xià cì nǐ zìjǐ zhǔnbèi, hǎo bu hǎo?","exampleVi":"Lần này bố giúp con, lần sau con tự chuẩn bị, được không?","meaning":"giúp","pinyin":"bāng","pos":"Động từ","word":"帮"},{"emoji":"📝","example":"明天考试，我在看书呢。","examplePinyin":"Míngtiān kǎoshì, wǒ zài kàn shū ne.","exampleVi":"Ngày mai thi, con đang đọc sách đây.","meaning":"kỳ thi; thi","pinyin":"kǎoshì","pos":"Danh từ","word":"考试"},{"emoji":"🔤","example":"这些词要好好看看。","examplePinyin":"Zhèxiē cí yào hǎohǎo kànkan.","exampleVi":"Những từ này phải xem lại thật kỹ.","meaning":"từ","pinyin":"cí","pos":"Danh từ","word":"词"},{"emoji":"📓","example":"你的本子呢？本子上做错的题也要看一看。","examplePinyin":"Nǐ de běnzi ne? Běnzi shang zuòcuò de tí yě yào kàn yí kàn.","exampleVi":"Vở của con đâu? Những bài làm sai trong vở cũng phải xem lại.","meaning":"vở, sổ tay","pinyin":"běnzi","pos":"Danh từ","word":"本子"},{"emoji":"❌","example":"本子上做错的题也要看一看。","examplePinyin":"Běnzi shang zuòcuò de tí yě yào kàn yí kàn.","exampleVi":"Những bài làm sai trong vở cũng phải xem lại.","meaning":"sai, nhầm","pinyin":"cuò","pos":"Tính từ","word":"错"},{"emoji":"❓","example":"本子上做错的题也要看一看。","examplePinyin":"Běnzi shang zuòcuò de tí yě yào kàn yí kàn.","exampleVi":"Những bài làm sai trong vở cũng phải xem lại.","meaning":"câu hỏi, bài tập","pinyin":"tí","pos":"Danh từ","word":"题"},{"emoji":"🤔","example":"妈妈，是您准备考试还是我准备考试？","examplePinyin":"Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?","exampleVi":"Mẹ ơi, là mẹ chuẩn bị thi hay là con chuẩn bị thi?","meaning":"hay là, hoặc","pinyin":"háishi","pos":"Liên từ","word":"还是"},{"emoji":"📝","example":"今天考试考得怎么样？","examplePinyin":"Jīntiān kǎoshì kǎo de zěnmeyàng?","exampleVi":"Hôm nay thi thế nào?","meaning":"thi, làm bài thi","pinyin":"kǎo","pos":"Động từ","word":"考"},{"emoji":"⏰","example":"饭菜快要做好了。","examplePinyin":"Fàncài kuàiyào zuòhǎo le.","exampleVi":"Cơm sắp nấu xong rồi.","meaning":"sắp, sắp sửa","pinyin":"kuàiyào","pos":"Phó từ","word":"快要"},{"emoji":"😄","example":"我问完，他们都笑了。","examplePinyin":"Wǒ wènwán, tāmen dōu xiào le.","exampleVi":"Tôi hỏi xong, họ đều cười.","meaning":"cười","pinyin":"xiào","pos":"Động từ","word":"笑"}]},{"emoji":"🍲","grammar":[{"title":"Trợ từ động thái 着 (1): không có tân ngữ","formula":"Chủ ngữ + động từ + 着","explain":"着 đứng ngay sau động từ, sau đó không có tân ngữ, diễn tả một trạng thái đang duy trì, ví dụ cửa đang mở, người đang ngồi. Phủ định dùng 没(有), không dùng 不.","tip":"Nhớ mẫu phủ định là 没开着, không nói 不开着.","examples":"那你在这儿坐着。 (Nà nǐ zài zhèr zuòzhe) — Vậy bạn cứ ngồi ở đây. 教室的门开着。 (Jiàoshì de mén kāizhe) — Cửa phòng học đang mở. 教室的门没开着。 (Jiàoshì de mén méi kāizhe) — Cửa phòng học không mở.","error":"Đừng thêm tân ngữ sau 着 trong mẫu này, ví dụ không nói 坐着车; muốn có tân ngữ thì dùng mẫu 着 (2). Phủ định phải dùng 没(有), không dùng 不."},{"title":"Trợ từ động thái 着 (2): có tân ngữ","formula":"Chủ ngữ + động từ + 着 + tân ngữ","explain":"着 đứng sau động từ, sau 着 là tân ngữ, diễn tả hành động đang diễn ra. Phủ định: 没(有) + động từ + 着 + tân ngữ. Hỏi có ba cách: động từ + 着 + 吗, động từ + 着 + 没有, động từ + 没 + động từ + 着.","tip":"Muốn hỏi ai đó có đang làm gì không, dùng mẫu động từ + 着 + 吗.","examples":"现在路上车多，还下着雪，我开慢一点儿。 (Xiànzài lùshang chē duō, hái xiàzhe xuě, wǒ kāi màn yìdiǎnr) — Bây giờ trên đường nhiều xe, lại còn đang có tuyết rơi, tôi lái chậm lại một chút. 她穿着白色的裤子。 (Tā chuānzhe báisè de kùzi) — Cô ấy đang mặc quần màu trắng. 陈天中没拿着咖啡。 (Chén Tiānzhōng méi názhe kāfēi) — Trần Thiên Trung không cầm cà phê.","error":"Đừng đặt tân ngữ trước 着, ví dụ không nói 穿白色的裤子着; phải nói 穿着白色的裤子."},{"title":"Phó từ mức độ 最: nhất","formula":"最 + tính từ / động từ tâm lý","explain":"最 đứng trước tính từ hoặc động từ chỉ tâm lý như 喜欢, 爱, nhấn mạnh mức độ cao nhất trong nhóm được so sánh.","tip":"最 luôn đứng trước từ mà nó nhấn mạnh, không đứng sau.","examples":"你最喜欢吃中国菜。 (Nǐ zuì xǐhuan chī Zhōngguó cài) — Bạn thích ăn món Trung Quốc nhất. 在我们家，爸爸最高。 (Zài wǒmen jiā, bàba zuì gāo) — Trong nhà tôi, bố cao nhất. 你们班谁说中文说得最好？ (Nǐmen bān shéi shuō Zhōngwén shuō de zuì hǎo) — Lớp các bạn ai nói tiếng Trung giỏi nhất?","error":"Đừng đặt 最 sau tính từ, ví dụ không nói 高最; phải nói 最高. Đừng dùng 最 với động từ thường, 最 chỉ đi với tính từ hoặc động từ tâm lý."}],"han":"我最喜欢吃中国菜","natural":["Mạch ý: Gia Nguyệt đau đầu ở lớp, cô Vương đưa đi bệnh viện, Lý Văn gọi điện rồi đến thăm, cuối cùng mọi người cùng ăn món Trung Quốc.","着 có hai cách dùng: đứng sau động từ không có tân ngữ để nói trạng thái (坐着, 开着), và đứng sau động từ có tân ngữ để nói hành động đang diễn ra (下着雪, 开着车).","Khi nghe, chú ý phân biệt 一动就疼 (cứ động là đau) với 不能动 (không cử động được), và nhớ 最 luôn đứng trước từ nó nhấn mạnh."],"num":11,"photoPrefix":"h2-11","pinyin":"Wǒ zuì xǐhuan chī Zhōngguó cài","structures":[{"han":"你这几天经常头疼，去医院看看吧。","pinyin":"Nǐ zhè jǐ tiān jīngcháng tóu téng, qù yīyuàn kànkan ba.","meaning":"Mấy hôm nay bạn thường xuyên đau đầu, đi bệnh viện khám thử xem.","note":"经常 diễn tả hành động lặp lại thường xuyên; 吧 ở cuối câu đưa ra lời khuyên nhẹ nhàng."},{"han":"那你在这儿坐着，我去开车。","pinyin":"","meaning":"Vậy bạn cứ ngồi ở đây, tôi đi lấy xe.","note":"坐着 là động từ cộng trợ từ 着, diễn tả trạng thái ngồi đang tiếp diễn, không phải hành động ngồi xuống."},{"han":"现在路上车多，还下着雪。","pinyin":"","meaning":"Bây giờ trên đường nhiều xe, lại còn đang có tuyết.","note":"下着雪 là động từ cộng 着 rồi cộng tân ngữ 雪, mẫu 着(2) diễn tả hành động đang diễn ra kèm tân ngữ."},{"han":"你最喜欢吃中国菜。","pinyin":"","meaning":"Bạn thích ăn món Trung Quốc nhất.","note":"最 đứng trước động từ 喜欢, nhấn mạnh mức độ cao nhất trong số các lựa chọn."},{"han":"那你在这儿坐着，我去开车，一会儿送你去医院。","pinyin":"Nà nǐ zài zhèr zuòzhe, wǒ qù kāichē, yíhuìr sòng nǐ qù yīyuàn.","meaning":"Vậy bạn cứ ngồi ở đây, tôi đi lấy xe, lát nữa đưa bạn đi bệnh viện.","note":""},{"han":"你最喜欢吃中国菜，我做几个中国菜吧。","pinyin":"Nǐ zuì xǐhuan chī Zhōngguó cài, wǒ zuò jǐ ge Zhōngguó cài ba.","meaning":"Bạn thích ăn món Trung Quốc nhất, tôi làm vài món Trung Quốc nhé.","note":""}],"theme":"Sức khỏe và món ăn Trung Quốc","translation":"Tôi thích ăn món Trung Quốc nhất","vocab":[{"emoji":"🧠","example":"我头疼，不太舒服。","examplePinyin":"Wǒ tóu téng, bú tài shūfu.","exampleVi":"Tôi đau đầu, không được khỏe lắm.","meaning":"đầu","pinyin":"tóu","pos":"Danh từ","word":"头"},{"emoji":"😣","example":"我头有点儿疼。","examplePinyin":"Wǒ tóu yǒudiǎnr téng.","exampleVi":"Tôi hơi đau đầu.","meaning":"đau","pinyin":"téng","pos":"Tính từ","word":"疼"},{"emoji":"🔁","example":"你这几天经常头疼。","examplePinyin":"Nǐ zhè jǐ tiān jīngcháng tóu téng.","exampleVi":"Mấy hôm nay bạn thường xuyên đau đầu.","meaning":"thường xuyên","pinyin":"jīngcháng","pos":"Phó từ","word":"经常"},{"emoji":"🚶","example":"现在不能动，一动就疼。","examplePinyin":"Xiànzài bù néng dòng, yí dòng jiù téng.","exampleVi":"Bây giờ không cử động được, cứ động là đau.","meaning":"động đậy, cử động","pinyin":"dòng","pos":"Động từ","word":"动"},{"emoji":"🪑","example":"那你在这儿坐着。","examplePinyin":"Nà nǐ zài zhèr zuòzhe.","exampleVi":"Vậy bạn cứ ngồi ở đây.","meaning":"trợ từ chỉ trạng thái đang tiếp diễn","pinyin":"zhe","pos":"Trợ từ","word":"着"},{"emoji":"🛣️","example":"现在路上车多，还下着雪。","examplePinyin":"Xiànzài lùshang chē duō, hái xiàzhe xuě.","exampleVi":"Bây giờ trên đường nhiều xe, lại còn đang có tuyết.","meaning":"trên đường","pinyin":"lùshang","pos":"Danh từ","word":"路上"},{"emoji":"🐢","example":"我开慢一点儿。","examplePinyin":"Wǒ kāi màn yìdiǎnr.","exampleVi":"Tôi lái chậm lại một chút.","meaning":"chậm","pinyin":"màn","pos":"Tính từ","word":"慢"},{"emoji":"🚪","example":"李文，快请进！","examplePinyin":"Lǐ Wén, kuài qǐng jìn!","exampleVi":"Lý Văn, mau vào đi!","meaning":"vào","pinyin":"jìn","pos":"Động từ","word":"进"},{"emoji":"💊","example":"医生开了一些药，吃完就好多了。","examplePinyin":"Yīshēng kāi le yìxiē yào, chīwán jiù hǎoduō le.","exampleVi":"Bác sĩ kê một ít thuốc, uống xong sẽ đỡ nhiều.","meaning":"thuốc","pinyin":"yào","pos":"Danh từ","word":"药"},{"emoji":"💪","example":"身体不舒服时更要好好吃饭。","examplePinyin":"Shēntǐ bù shūfu shí gèng yào hǎohāo chī fàn.","exampleVi":"Khi cơ thể không khỏe càng phải ăn uống cho tốt.","meaning":"cơ thể, sức khỏe","pinyin":"shēntǐ","pos":"Danh từ","word":"身体"},{"emoji":"⏰","example":"下雪时，路上很滑。","examplePinyin":"Xià xuě shí, lùshang hěn huá.","exampleVi":"Khi tuyết rơi, đường rất trơn.","meaning":"lúc, khi","pinyin":"shí","pos":"Danh từ","word":"时"},{"emoji":"🥇","example":"你最喜欢吃中国菜。","examplePinyin":"Nǐ zuì xǐhuan chī Zhōngguó cài.","exampleVi":"Bạn thích ăn món Trung Quốc nhất.","meaning":"nhất","pinyin":"zuì","pos":"Phó từ","word":"最"},{"emoji":"🏪","example":"我从药店买了点儿药。","examplePinyin":"Wǒ cóng yàodiàn mǎi le diǎnr yào.","exampleVi":"Tôi mua một ít thuốc ở hiệu thuốc.","meaning":"hiệu thuốc","pinyin":"yàodiàn","pos":"Danh từ","word":"药店"}]},{"emoji":"❄️","grammar":[{"title":"Câu so sánh với 比 (4): hơn nhiều, 多了/得多","formula":"A + 比 + B + tính từ + 多了/得多","explain":"Trong câu so sánh với 比, 多了 hoặc 得多 đặt sau tính từ, nhấn mạnh hai bên chênh lệch rất lớn.","tip":"多了 và 得多 đều diễn tả chênh lệch lớn, chọn một trong hai.","examples":"我这里比北京冷多了。 (Wǒ zhèlǐ bǐ Běijīng lěng duō le) — Chỗ tôi lạnh hơn Bắc Kinh nhiều. 坐飞机比坐火车快得多。 (Zuò fēijī bǐ zuò huǒchē kuài de duō) — Đi máy bay nhanh hơn đi tàu hỏa nhiều. 他觉得红茶比绿茶好喝得多。 (Tā juéde hóngchá bǐ lǜchá hǎohē de duō) — Anh ấy thấy trà đen ngon hơn trà xanh nhiều.","error":"Đừng đặt 多了 trước tính từ, ví dụ không nói 比北京多了冷; phải nói 比北京冷多了."},{"title":"Câu so sánh với 比 (5): động từ mang bổ ngữ trạng thái","formula":"A + 比 + B + động từ + 得 + bổ ngữ trạng thái, hoặc A + động từ + 得 + 比 + B + bổ ngữ trạng thái","explain":"Khi động từ mang bổ ngữ trạng thái (động từ + 得 + tính từ), 比 có thể đặt trước động từ hoặc sau động từ, nghĩa không đổi.","tip":"比 đặt trước hay sau động từ đều đúng, cứ chọn cách nào thuận miệng.","examples":"昨天比今天下得大。 (Zuótiān bǐ jīntiān xià de dà) — Tuyết hôm qua rơi to hơn hôm nay. 妈妈比我睡得晚。 (Māma bǐ wǒ shuì de wǎn) — Mẹ ngủ muộn hơn tôi. 李文跑得比白家月快。 (Lǐ Wén pǎo de bǐ Bái Jiāyuè kuài) — Lý Văn chạy nhanh hơn Bạch Gia Nguyệt.","error":"Đừng đặt 比 sau bổ ngữ trạng thái, ví dụ không nói 睡得晚比我; 比 phải đứng trước động từ hoặc ngay sau động từ."},{"title":"Câu so sánh với 比 (6): động từ vừa có tân ngữ vừa có bổ ngữ trạng thái","formula":"Tân ngữ + động từ + 得 + 比 + B + bổ ngữ trạng thái, hoặc động từ + tân ngữ + động từ + 得 + 比 + B + bổ ngữ trạng thái","explain":"Khi động từ vừa có tân ngữ vừa có bổ ngữ trạng thái, có thể đưa tân ngữ lên đầu câu, hoặc lặp lại động từ. Nếu động từ là từ ly hợp như 跑步, chỉ lặp lại yếu tố động từ (跑).","tip":"Động từ ly hợp như 跑步, 游泳 chỉ lặp phần động từ: 跑步跑得, 游泳游得.","examples":"你跑步跑得比我快。 (Nǐ pǎobù pǎo de bǐ wǒ kuài) — Bạn chạy bộ nhanh hơn tôi. 白家月汉字写得比陈天中好。 (Bái Jiāyuè Hànzì xiě de bǐ Chén Tiānzhōng hǎo) — Bạch Gia Nguyệt viết chữ Hán đẹp hơn Trần Thiên Trung. 他踢足球比我踢得好。 (Tā tī zúqiú bǐ wǒ tī de hǎo) — Anh ấy đá bóng giỏi hơn tôi.","error":"Khi lặp động từ, đừng lặp cả tân ngữ, ví dụ không nói 跑步跑步跑得比我快; chỉ lặp động từ: 跑步跑得比我快."}],"han":"这里比北京冷多了","natural":["Mạch ý: hỏi thời tiết qua điện thoại, dặn dò mặc ấm và mua đồ, rủ nhau chạy bộ, nhật ký kể lại một ngày nắng đẹp.","Ba mẫu so sánh: tính từ cộng 多了/得多, động từ cộng 得 cộng 比, động từ ly hợp lặp lại động từ rồi cộng 得.","Khi nghe, chú ý 正下着雪 (đang có tuyết) khác với 不下雪了 (hết tuyết rồi), và phân biệt 比...冷多了 với 比...冷一点儿 ở bài sau."],"num":12,"photoPrefix":"h2-12","pinyin":"Zhèlǐ bǐ Běijīng lěngduō le","structures":[{"han":"我这里比北京冷多了。","pinyin":"","meaning":"Chỗ tôi lạnh hơn Bắc Kinh nhiều.","note":"比...冷多了 là mẫu so sánh (4): tính từ 冷 rồi thêm 多了 hoặc 得多 để nhấn mạnh chênh lệch lớn."},{"han":"昨天比今天下得大。","pinyin":"Zuótiān bǐ jīntiān xià de dà.","meaning":"Hôm qua tuyết rơi lớn hơn hôm nay.","note":"So sánh (5): động từ 下 mang bổ ngữ trạng thái 下得大, 比 đặt trước động từ, 得 nối động từ với bổ ngữ."},{"han":"你跑步跑得比我快。","pinyin":"","meaning":"Bạn chạy bộ nhanh hơn tôi.","note":"So sánh (6): 跑步 là động từ ly hợp nên phải lặp lại động từ 跑 rồi mới cộng 得 và 比."},{"han":"外边还正下着雪呢！","pinyin":"Wǒ zhèlǐ bǐ Běijīng lěngduō le, wàibian hái zhèng xiàzhe xuě ne!","meaning":"Bên ngoài vẫn đang có tuyết rơi đấy!","note":"正...着 kết hợp diễn tả hành động đang diễn ra ngay lúc nói; 呢 ở cuối câu nhấn mạnh."},{"han":"我这里比北京冷多了，外边还正下着雪呢！","pinyin":"Wǒ zhèlǐ bǐ Běijīng lěngduō le, wàibian hái zhèng xiàzhe xuě ne!","meaning":"Chỗ tôi lạnh hơn Bắc Kinh nhiều, bên ngoài vẫn đang có tuyết rơi đấy!","note":""},{"han":"你跑步跑得比我快，我们能一起跑吗？","pinyin":"Nǐ pǎobù pǎo de bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?","meaning":"Bạn chạy bộ nhanh hơn tôi, chúng ta có thể chạy cùng nhau không?","note":""}],"theme":"Thời tiết và so sánh","translation":"Ở đây lạnh hơn Bắc Kinh nhiều","vocab":[{"emoji":"📋","example":"没什么事，就想跟您说说话。","examplePinyin":"Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà.","exampleVi":"Không có việc gì, chỉ muốn nói chuyện với cô thôi.","meaning":"việc, chuyện","pinyin":"shìqing","pos":"Danh từ","word":"事情"},{"emoji":"☀️","example":"北京这几天虽然是晴天，但是有点儿冷。","examplePinyin":"Běijīng zhè jǐ tiān suīrán shì qíng tiān, dànshì yǒudiǎnr lěng.","exampleVi":"Mấy hôm nay Bắc Kinh tuy trời nắng nhưng hơi lạnh.","meaning":"nắng, quang đãng","pinyin":"qíng","pos":"Tính từ","word":"晴"},{"emoji":"⏳","example":"外边还正下着雪呢！","examplePinyin":"Wàibian hái zhèng xiàzhe xuě ne!","exampleVi":"Bên ngoài vẫn đang có tuyết rơi đấy!","meaning":"đang, đúng lúc","pinyin":"zhèng","pos":"Phó từ","word":"正"},{"emoji":"🚪","example":"天气不好，你去外面的时候多穿点儿衣服。","examplePinyin":"Tiānqì bù hǎo, nǐ qù wàimian de shíhou duō chuān diǎnr yīfu.","exampleVi":"Thời tiết không tốt, khi ra ngoài bạn mặc thêm áo nhé.","meaning":"bên ngoài","pinyin":"wàimian","pos":"Danh từ","word":"外面"},{"emoji":"☁️","example":"阴天下雪什么的就少出去吧。","examplePinyin":"Yīn tiān xià xuě shénmede jiù shǎo chūqù ba.","exampleVi":"Trời âm u hay có tuyết thì ít ra ngoài thôi.","meaning":"âm u, nhiều mây","pinyin":"yīn","pos":"Tính từ","word":"阴"},{"emoji":"👶","example":"我从小就经常跟爸爸跑步。","examplePinyin":"Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù.","exampleVi":"Tôi từ nhỏ đã thường xuyên chạy bộ cùng bố.","meaning":"từ nhỏ","pinyin":"cóngxiǎo","pos":"Phó từ","word":"从小"},{"emoji":"🚇","example":"我现在坐地铁去找你。","examplePinyin":"Wǒ xiànzài zuò dìtiě qù zhǎo nǐ.","exampleVi":"Bây giờ tôi đi tàu điện ngầm đến tìm bạn.","meaning":"tàu điện ngầm","pinyin":"dìtiě","pos":"Danh từ","word":"地铁"},{"emoji":"🏢","example":"一会儿楼下见。","examplePinyin":"Yíhuìr lóu xià jiàn.","exampleVi":"Lát nữa gặp nhau dưới lầu nhé.","meaning":"tòa nhà, tầng lầu","pinyin":"lóu","pos":"Danh từ","word":"楼"},{"emoji":"🚉","example":"每天坐两站地铁去学校。","examplePinyin":"Měi tiān zuò liǎng zhàn dìtiě qù xuéxiào.","exampleVi":"Mỗi ngày đi hai trạm tàu điện ngầm đến trường.","meaning":"trạm, bến","pinyin":"zhàn","pos":"Danh từ","word":"站"},{"emoji":"🧒","example":"他小时候经常跑步。","examplePinyin":"Tā xiǎoshíhou jīngcháng pǎobù.","exampleVi":"Hồi nhỏ anh ấy thường xuyên chạy bộ.","meaning":"thời thơ ấu","pinyin":"xiǎoshíhou","pos":"Danh từ","word":"小时候"},{"emoji":"😄","example":"跟李文一起跑步，我好高兴啊！","examplePinyin":"Gēn Lǐ Wén yìqǐ pǎobù, wǒ hǎo gāoxìng a!","exampleVi":"Chạy bộ cùng Lý Văn, tôi vui lắm!","meaning":"rất, lắm","pinyin":"hǎo","pos":"Phó từ","word":"好"}]},{"emoji":"🎁","grammar":[{"title":"Câu hai tân ngữ (2): động từ 拿/送/卖 + 给","formula":"Chủ ngữ + 拿/送/卖 + 给 + người + vật","explain":"Câu hai tân ngữ có một động từ mang hai tân ngữ, tân ngữ đầu chỉ người, tân ngữ sau chỉ vật. Bài này học ba động từ 拿, 送, 卖 kết hợp với 给.","tip":"Nhớ thứ tự: cho ai trước, cho cái gì sau.","examples":"王老师喜欢花，就送给她花吧。 (Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba) — Cô Vương thích hoa, cứ tặng cô hoa đi. 她拿给我一杯水。 (Tā ná gěi wǒ yì bēi shuǐ) — Cô ấy lấy cho tôi một cốc nước. 他卖给我一本中文书。 (Tā mài gěi wǒ yì běn Zhōngwén shū) — Anh ấy bán cho tôi một cuốn sách tiếng Trung.","error":"Đừng đảo thứ tự hai tân ngữ, ví dụ không nói 送给花她; phải nói 送给她花, người trước, vật sau."},{"title":"Câu so sánh với 比 (7): chênh lệch cụ thể bằng số lượng","formula":"A + 比 + B + tính từ + số từ + lượng từ","explain":"Trong câu so sánh với 比, cụm số lượng đặt sau tính từ để nói rõ chênh lệch cụ thể là bao nhiêu.","tip":"Sau tính từ phải có cả số từ và lượng từ, ví dụ 大三岁, 多了十个.","examples":"今天的词比昨天多了十个。 (Jīntiān de cí bǐ zuótiān duō le shí gè) — Từ mới hôm nay nhiều hơn hôm qua mười từ. 姐姐比我大三岁。 (Jiějie bǐ wǒ dà sān suì) — Chị gái hơn tôi ba tuổi. 坐飞机比坐火车快五个多小时。 (Zuò fēijī bǐ zuò huǒchē kuài wǔ gè duō xiǎoshí) — Đi máy bay nhanh hơn đi tàu hỏa hơn năm tiếng.","error":"Đừng quên lượng từ sau số từ, ví dụ không nói 大三; phải nói 大三岁."},{"title":"Câu so sánh với 比 (8): chênh lệch nhỏ, 一点儿/一些","formula":"A + 比 + B + tính từ + 一点儿/一些","explain":"Trong câu so sánh với 比, 一点儿 hoặc 一些 đặt sau tính từ để nói chênh lệch không lớn, chỉ hơn một chút.","tip":"一点儿 và 一些 đều chỉ chênh lệch nhỏ, 一点儿 dùng nhiều hơn trong khẩu ngữ.","examples":"比我们一起买的那个本子贵一点儿。 (Bǐ wǒmen yìqǐ mǎi de nàge běnzi guì yìdiǎnr) — Đắt hơn quyển vở chúng ta cùng mua một chút. 姐姐比我高一点儿。 (Jiějie bǐ wǒ gāo yìdiǎnr) — Chị gái cao hơn tôi một chút. 那间教室比这间大一些。 (Nà jiān jiàoshì bǐ zhè jiān dà yìxiē) — Phòng học kia to hơn phòng này một chút.","error":"Đừng dùng 一点儿 với số lượng cụ thể, ví dụ không nói 贵三块一点儿; chênh lệch cụ thể dùng mẫu 比较句 (7)."}],"han":"我们爱上中文课","natural":["Mạch ý: bàn tặng quà cho cô giáo, chữa chữ viết sai trong giờ học, tặng nhau quà năm mới, nhật ký tổng kết.","Câu hai tân ngữ với 拿, 送, 卖 cộng 给: người nhận đứng trước, đồ vật đứng sau, ví dụ 送给她花, 拿给我一杯水.","Khi nghe, phân biệt 多了十个 (nhiều hơn hẳn mười từ) với 贵一点儿 (chỉ đắt hơn một chút), và nhớ chữ 间 bên trong là 日 chứ không phải 口."],"num":13,"photoPrefix":"h2-13","pinyin":"Wǒmen ài shàng Zhōngwén kè","structures":[{"han":"王老师喜欢花，就送给她花吧。","pinyin":"Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","meaning":"Cô Vương thích hoa, tặng hoa cho cô nhé.","note":"送给她花 là câu hai tân ngữ: 送 cộng 给, tân ngữ chỉ người 她 đứng trước tân ngữ chỉ vật 花."},{"han":"今天的词比昨天多了十个。","pinyin":"Jīntiān de cí bǐ zuótiān duō le shí ge.","meaning":"Từ hôm nay nhiều hơn hôm qua mười từ.","note":"So sánh (7): sau tính từ 多 là cụm số lượng 十个, nói rõ chênh lệch cụ thể là mười từ."},{"han":"比我们一起买的那个本子贵一点儿。","pinyin":"Bǐ wǒmen yìqǐ mǎi de nà ge běnzi guì yìdiǎnr.","meaning":"Đắt hơn quyển vở chúng ta cùng mua một chút.","note":"So sánh (8): sau tính từ 贵 là 一点儿, nói chênh lệch rất nhỏ, không đáng kể."},{"han":"“日”比“口”多一笔。","pinyin":"","meaning":"Chữ 日 nhiều hơn chữ 口 một nét.","note":"多一笔 cũng là mẫu so sánh (7), dùng số lượng 一笔 để nói chênh lệch cụ thể giữa hai chữ."}],"theme":"Quà năm mới và giờ học tiếng Trung","translation":"Chúng tôi đã yêu thích giờ học tiếng Trung","vocab":[{"emoji":"🎉","example":"时间过得真快啊！新年就要到了。","examplePinyin":"Shíjiān guò de zhēn kuài a! Xīnnián jiù yào dào le.","exampleVi":"Thời gian trôi nhanh thật! Năm mới sắp đến rồi.","meaning":"năm mới","pinyin":"xīnnián","pos":"Danh từ","word":"新年"},{"emoji":"👩‍🏫","example":"这一年王老师教我们中文，每天工作都很累。","examplePinyin":"Zhè yì nián Wáng lǎoshī jiāo wǒmen Zhōngwén, měi tiān gōngzuò dōu hěn lèi.","exampleVi":"Năm nay cô Vương dạy chúng tôi tiếng Trung, mỗi ngày làm việc đều rất mệt.","meaning":"dạy","pinyin":"jiāo","pos":"Động từ","word":"教"},{"emoji":"🌸","example":"王老师喜欢花，就送给她花吧。","examplePinyin":"Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","exampleVi":"Cô Vương thích hoa, tặng hoa cho cô nhé.","meaning":"hoa","pinyin":"huā","pos":"Danh từ","word":"花"},{"emoji":"🙏","example":"希望花店还有漂亮的花。","examplePinyin":"Xīwàng huādiàn hái yǒu piàoliang de huā.","exampleVi":"Mong là tiệm hoa vẫn còn hoa đẹp.","meaning":"hi vọng, mong","pinyin":"xīwàng","pos":"Động từ","word":"希望"},{"emoji":"⬆️","example":"现在我来说，你们在本子上面写。","examplePinyin":"Xiànzài wǒ lái shuō, nǐmen zài běnzi shàngmian xiě.","exampleVi":"Bây giờ tôi đọc, các bạn viết lên vở nhé.","meaning":"phía trên, mặt trên","pinyin":"shàngmian","pos":"Danh từ","word":"上面"},{"emoji":"🚻","example":"同学们，“洗手间”的“间”字写错了。","examplePinyin":"Tóngxuémen, \"xǐshǒujiān\" de \"jiān\" zì xiěcuò le.","exampleVi":"Các bạn ơi, chữ 间 trong từ nhà vệ sinh viết sai rồi.","meaning":"nhà vệ sinh","pinyin":"xǐshǒujiān","pos":"Danh từ","word":"洗手间"},{"emoji":"📦","example":"它的里面是“日”，不是“口”。","examplePinyin":"Tā de lǐmian shì \"rì\", bú shì \"kǒu\".","exampleVi":"Bên trong của nó là chữ 日, không phải chữ 口.","meaning":"bên trong","pinyin":"lǐmian","pos":"Danh từ","word":"里面"},{"emoji":"✏️","example":"“日”比“口”多一笔。","examplePinyin":"\"Rì\" bǐ \"kǒu\" duō yì bǐ.","exampleVi":"Chữ 日 nhiều hơn chữ 口 một nét.","meaning":"nét (chữ)","pinyin":"bǐ","pos":"Lượng từ","word":"笔"},{"emoji":"🤔","example":"这么漂亮的本子，不可能贵一点儿吧？","examplePinyin":"Zhème piàoliang de běnzi, bù kěnéng guì yìdiǎnr ba?","exampleVi":"Quyển vở đẹp thế này, không thể chỉ đắt hơn một chút chứ?","meaning":"có thể, có lẽ","pinyin":"kěnéng","pos":"Động từ","word":"可能"},{"emoji":"💻","example":"我是上网买的，真没那么贵。","examplePinyin":"Wǒ shì shàngwǎng mǎi de, zhēn méi nàme guì.","exampleVi":"Tôi mua trên mạng, thật sự không đắt như thế đâu.","meaning":"lên mạng","pinyin":"shàngwǎng","pos":"Động từ","word":"上网"},{"emoji":"👍","example":"好，那样我们就都有新年礼物了！","examplePinyin":"Hǎo, nà yàng wǒmen jiù dōu yǒu xīnnián lǐwù le!","exampleVi":"Được, như vậy chúng ta đều có quà năm mới rồi!","meaning":"như thế, như vậy","pinyin":"nà yàng","pos":"Đại từ","word":"那样"},{"emoji":"🗣️","example":"她告诉我是在网上买的。","examplePinyin":"Tā gàosu wǒ shì zài wǎngshang mǎi de.","exampleVi":"Cô ấy nói với tôi là mua trên mạng.","meaning":"nói cho biết, bảo","pinyin":"gàosu","pos":"Động từ","word":"告诉"},{"emoji":"🏫","example":"我们班同学也送了王老师漂亮的花。","examplePinyin":"Wǒmen bān tóngxué yě sòng le Wáng lǎoshī piàoliang de huā.","exampleVi":"Các bạn cùng lớp chúng tôi cũng tặng cô Vương hoa đẹp.","meaning":"lớp học","pinyin":"bān","pos":"Danh từ","word":"班"}]},{"emoji":"🧧","grammar":[{"title":"Câu tồn hiện (2): nơi chốn + động từ + 着 + người/vật","formula":"Nơi chốn + động từ + 着 + người/vật không xác định","explain":"着 đặt sau động từ tạo thành câu tồn hiện, trước động từ là cụm chỉ nơi chốn, sau động từ thường là người hoặc vật không xác định.","tip":"Người hoặc vật sau 着 thường là mới xuất hiện, chưa xác định, nên hay có số từ 一.","examples":"你家楼下站着一个人。 (Nǐ jiā lóuxià zhànzhe yí gè rén) — Dưới lầu nhà bạn có một người đang đứng. 爸爸手里拿着一杯咖啡。 (Bàba shǒulǐ názhe yì bēi kāfēi) — Trên tay bố đang cầm một cốc cà phê. 那间教室里坐着不少学生。 (Nà jiān jiàoshì lǐ zuòzhe bùshǎo xuésheng) — Trong phòng học kia có không ít học sinh đang ngồi.","error":"Sau 着 thường là người hoặc vật chưa xác định, nên hay có 一 + lượng từ, ví dụ 一个人, 一杯咖啡."},{"title":"Phó từ mức độ 多 trong câu cảm thán","formula":"多 + tính từ/động từ + 啊!","explain":"多 dùng trong câu cảm thán, diễn tả mức độ rất cao, thường đi với 啊 ở cuối câu.","tip":"Câu có 多 thường kết thúc bằng 啊 và dấu chấm than.","examples":"你一个人在这儿多没意思啊！ (Nǐ yí gè rén zài zhèr duō méi yìsi a) — Bạn ở đây một mình chán biết bao! 我们一起去多好啊！ (Wǒmen yìqǐ qù duō hǎo a) — Chúng ta cùng đi thì tốt biết bao! 多好看啊！买这件吧。 (Duō hǎokàn a! Mǎi zhè jiàn ba) — Đẹp quá! Mua cái này đi.","error":"Đừng dùng 多 trong câu trần thuật bình thường để diễn tả mức độ; 多 chỉ dùng trong câu cảm thán với 啊."},{"title":"Bổ ngữ xu hướng phức hợp: 上/下/进/出/回/过 + 来/去/起来","formula":"Động từ + 上/下/进/出/回/过 + 来/去, hoặc động từ + 起来","explain":"上, 下, 进, 出, 回, 过 kết hợp với 来, 去, cùng với 起来, đặt sau động từ tạo thành bổ ngữ xu hướng phức hợp, diễn tả hướng của hành động. Tân ngữ là danh từ chỉ nơi chốn đặt trước 来/去; tân ngữ là danh từ chỉ vật đặt trước hoặc sau 来/去 đều được.","tip":"Nhớ 来 là hướng về phía người nói, 去 là hướng ra xa người nói.","examples":"她经常跑上来找我玩。 (Tā jīngcháng pǎo shànglái zhǎo wǒ wán) — Cô ấy thường chạy lên tìm tôi chơi. 楼不高，我们走上去吧。 (Lóu bù gāo, wǒmen zǒu shàngqù ba) — Lầu không cao, chúng ta đi bộ lên đi. 一听到老师叫他的名字，他就站起来了。 (Yí tīngdào lǎoshī jiào tā de míngzi, tā jiù zhàn qǐlái le) — Vừa nghe thầy gọi tên mình, anh ấy liền đứng dậy.","error":"Đừng đặt tân ngữ chỉ nơi chốn sau 来/去, ví dụ không nói 走出去教室; phải nói 走出教室去. Tân ngữ chỉ vật thì đặt trước hay sau 来/去 đều được."}],"han":"一个人过年多没意思啊","natural":["Mạch ý: thấy người lạ dưới lầu, gặp bạn trai, trò chuyện về hàng xóm dưới lầu, nhật ký kể về bạn trai.","Câu tồn tại dùng 着: nơi chốn cộng động từ cộng 着 cộng người hoặc vật chưa xác định, ví dụ 楼下站着一个人, 教室里坐着不少学生.","Khi nghe, chú ý 多 trong câu cảm thán (多没意思啊, 多好啊) khác với 多 chỉ số lượng, và phân biệt 跑上来 (chạy lên) với 走上去 (đi lên)."],"num":14,"photoPrefix":"h2-14","pinyin":"Yí gè rén guònián duō méi yìsi a","structures":[{"han":"你家楼下站着一个人。","pinyin":"Nǐ jiā lóu xià zhànzhe yí ge rén.","meaning":"Dưới lầu nhà bạn có một người đang đứng.","note":"Câu tồn tại (2): nơi chốn 楼下 cộng động từ 站 cộng 着, phía sau là người không xác định 一个人."},{"han":"你一个人在这儿多没意思啊！","pinyin":"","meaning":"Bạn một mình ở đây chán biết bao!","note":"多 đứng trước 没意思 trong câu cảm thán, nhấn mạnh mức độ rất cao, không phải số lượng."},{"han":"她经常跑上来找我玩。","pinyin":"Méi cuò, tā jīngcháng pǎo shànglái zhǎo wǒ wán.","meaning":"Em ấy thường xuyên chạy lên tìm tôi chơi.","note":"跑上来 là động từ 跑 cộng bổ ngữ xu hướng phức hợp 上来, chỉ hướng chạy là lên trên, về phía người nói."},{"han":"我男朋友姓杨，叫杨同乐。","pinyin":"Wǒ nánpéngyou xìng Yáng, jiào Yáng Tónglè.","meaning":"Bạn trai tôi họ Dương, tên là Dương Đồng Lạc.","note":"姓...叫... là mẫu giới thiệu họ tên: họ đứng sau 姓, tên đầy đủ đứng sau 叫."},{"han":"就要过年了，你一个人在这儿多没意思啊。","pinyin":"Jiù yào guònián le, nǐ yí ge rén zài zhèr duō méi yìsi a.","meaning":"Sắp đến Tết rồi, bạn một mình ở đây chán biết bao.","note":""}],"theme":"Đón năm mới và bạn trai","translation":"Một mình đón năm mới chán biết bao","vocab":[{"emoji":"🧍","example":"王老师，你家楼下站着一个人。","examplePinyin":"Wáng lǎoshī, nǐ jiā lóu xià zhànzhe yí ge rén.","exampleVi":"Cô Vương ơi, dưới lầu nhà cô có một người đang đứng.","meaning":"đứng","pinyin":"zhàn","pos":"Động từ","word":"站"},{"emoji":"👜","example":"手里还拿着一个黑色的包。","examplePinyin":"Shǒulǐ hái názhe yí ge hēisè de bāo.","exampleVi":"Trên tay còn cầm một cái túi màu đen.","meaning":"túi, cái bọc","pinyin":"bāo","pos":"Danh từ","word":"包"},{"emoji":"🧨","example":"就要过年了，你一个人在这儿多没意思啊。","examplePinyin":"Jiù yào guònián le, nǐ yí ge rén zài zhèr duō méi yìsi a.","exampleVi":"Sắp đến Tết rồi, bạn một mình ở đây chán biết bao.","meaning":"đón năm mới, ăn Tết","pinyin":"guònián","pos":"Động từ","word":"过年"},{"emoji":"😒","example":"一个人过年多没意思啊。","examplePinyin":"Yí gè rén guònián duō méi yìsi a.","exampleVi":"Một mình đón năm mới chán biết bao.","meaning":"chán, vô vị","pinyin":"méi yìsi","pos":"Tính từ","word":"没意思"},{"emoji":"🙋","example":"一飞，你旁边这位是？","examplePinyin":"Yīfēi, nǐ pángbiān zhè wèi shì?","exampleVi":"Nhất Phi, người bên cạnh bạn đây là ai?","meaning":"vị (chỉ người, trang trọng)","pinyin":"wèi","pos":"Lượng từ","word":"位"},{"emoji":"➡️","example":"我家就在前面那个楼。","examplePinyin":"Wǒ jiā jiù zài qiánmian nà ge lóu.","exampleVi":"Nhà tôi ở ngay tòa nhà phía trước kia.","meaning":"phía trước","pinyin":"qiánmian","pos":"Danh từ","word":"前面"},{"emoji":"🏠","example":"一飞，你住的房子真不错，很大，离学校也不远。","examplePinyin":"Yīfēi, nǐ zhù de fángzi zhēn búcuò, hěn dà, lí xuéxiào yě bù yuǎn.","exampleVi":"Nhất Phi, căn nhà bạn ở thật tốt, rất to, lại không xa trường.","meaning":"nhà, căn nhà","pinyin":"fángzi","pos":"Danh từ","word":"房子"},{"emoji":"🧒","example":"我也帮他们家的小孩儿学中文。","examplePinyin":"Wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén.","exampleVi":"Tôi cũng giúp đứa trẻ nhà họ học tiếng Trung.","meaning":"trẻ con","pinyin":"xiǎoháir","pos":"Danh từ","word":"小孩儿"},{"emoji":"👧","example":"我记得你跟我说过，是个女孩儿，学得也很好。","examplePinyin":"Wǒ jìde nǐ gēn wǒ shuō guo, shì ge nǚháir, xué de yě hěn hǎo.","exampleVi":"Tôi nhớ bạn từng nói với tôi, đó là một bé gái, học cũng rất tốt.","meaning":"bé gái, cô gái","pinyin":"nǚháir","pos":"Danh từ","word":"女孩儿"},{"emoji":"📛","example":"我男朋友姓杨，叫杨同乐。","examplePinyin":"Wǒ nánpéngyou xìng Yáng, jiào Yáng Tónglè.","exampleVi":"Bạn trai tôi họ Dương, tên là Dương Đồng Lạc.","meaning":"mang họ","pinyin":"xìng","pos":"Động từ","word":"姓"},{"emoji":"👀","example":"他高个子、大眼睛，唱歌唱得很好。","examplePinyin":"Tā gāo gèzi, dà yǎnjing, chànggē chàng de hěn hǎo.","exampleVi":"Anh ấy cao, mắt to, hát rất hay.","meaning":"mắt","pinyin":"yǎnjing","pos":"Danh từ","word":"眼睛"},{"emoji":"💃","example":"跳舞跳得也不错。","examplePinyin":"Tiàowǔ tiào de yě búcuò.","exampleVi":"Nhảy múa cũng không tệ.","meaning":"nhảy múa, khiêu vũ","pinyin":"tiàowǔ","pos":"Động từ","word":"跳舞"}]},{"emoji":"✈️","grammar":[{"title":"Bổ ngữ động lượng (1): số từ + 次","formula":"Động từ + số từ + 次","explain":"Số từ + 次 đặt sau động từ tạo thành bổ ngữ động lượng, diễn tả hành động xảy ra mấy lần. Nếu động từ có tân ngữ là tên người hoặc tên nơi chốn, tân ngữ có thể đặt trước hoặc sau bổ ngữ động lượng.","tip":"次 là lượng từ chỉ số lần, luôn đi với số từ: 一次, 两次, 三次.","examples":"我想去中国，虽然去过一次，但是很想再去一次。 (Wǒ xiǎng qù Zhōngguó, suīrán qùguò yí cì, dànshì hěn xiǎng zài qù yí cì) — Tôi muốn đi Trung Quốc, tuy đã đi một lần nhưng rất muốn đi thêm một lần nữa. 安妮去过一次北京。 (Ānnī qùguò yí cì Běijīng) — Annie đã đi Bắc Kinh một lần. 李文见了杨同乐两次。 (Lǐ Wén jiàn le Yáng Tónglè liǎng cì) — Lý Văn đã gặp Dương Đồng Lạc hai lần.","error":"Đừng đặt 次 trước động từ, ví dụ không nói 一次去过北京; phải nói 去过一次北京."},{"title":"Bổ ngữ động lượng (2): vị trí tân ngữ","formula":"Động từ + số từ + 次 + tân ngữ là danh từ chỉ vật; động từ + đại từ + số từ + 次","explain":"Động từ vừa mang bổ ngữ động lượng vừa mang tân ngữ: tân ngữ là danh từ chỉ vật thường đặt sau bổ ngữ động lượng; tân ngữ là đại từ đặt trước bổ ngữ động lượng.","tip":"Đại từ như 他, 它 phải đứng trước 次, không đứng sau.","examples":"因为我想再吃一次烤鸭，再喝一次奶茶。 (Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá) — Vì tôi muốn ăn vịt quay thêm một lần nữa, uống trà sữa thêm một lần nữa. 我想找他一次。 (Wǒ xiǎng zhǎo tā yí cì) — Tôi muốn tìm anh ấy một lần. 安妮来过这儿两次。 (Ānnī láiguò zhèr liǎng cì) — Annie đã đến đây hai lần.","error":"Đừng đặt đại từ sau 次, ví dụ không nói 找一次他; phải nói 找他一次. Tân ngữ là danh từ chỉ vật thì đặt sau 次, ví dụ 吃一次饺子."},{"title":"Câu chữ 有 (2): 有 + số lượng, đạt đến một số lượng","formula":"Chủ ngữ + 有 + số từ + lượng từ + (động từ)...","explain":"有 + cụm số lượng diễn tả đã đạt đến một số lượng nào đó, thường dùng để nói khoảng thời gian đã trôi qua hoặc tuổi tác.","tip":"Mẫu này hay dùng với 没 để nói đã bao lâu không làm gì.","examples":"你有一年没回国了吧？ (Nǐ yǒu yì nián méi huíguó le ba) — Bạn đã một năm không về nước rồi phải không? 你女儿今年有10岁了吗？ (Nǐ nǚ'ér jīnnián yǒu shí suì le ma) — Con gái bạn năm nay đã mười tuổi rồi à? 我有一个月没给家里打电话了。 (Wǒ yǒu yí gè yuè méi gěi jiālǐ dǎ diànhuà le) — Tôi đã một tháng không gọi điện về nhà rồi.","error":"Đừng quên 有 ở đầu mẫu, ví dụ không nói 一年没回国了; phải nói 有一年没回国了."}],"han":"我想再去一次中国","natural":["Mạch ý: thi xong bàn chuyện đi du lịch, kế hoạch đi Bắc Kinh, nhớ lại lần về nước trước, nhật ký kể chuyện cùng bay thứ sáu.","Bổ ngữ số lần: số từ cộng 次 đứng sau động từ, tân ngữ là tên người hoặc địa danh có thể đứng trước hoặc sau, tân ngữ là đồ vật đứng sau, đại từ đứng trước.","Khi nghe, chú ý 去过一次 (đã từng đến một lần) khác với 再去一次 (đến thêm một lần nữa), và 有一年没回国 (đã một năm không về nước) là mẫu 有 cộng số lượng."],"num":15,"photoPrefix":"h2-15","pinyin":"Wǒ xiǎng zài qù yí cì Zhōngguó","structures":[{"han":"我很想去中国，虽然去过一次，但是很想再去一次。","pinyin":"Wǒ hěn xiǎng qù Zhōngguó, suīrán qù guo yí cì, dànshì hěn xiǎng zài qù yí cì.","meaning":"Tôi rất muốn đến Trung Quốc, tuy đã đến một lần rồi nhưng rất muốn đến thêm một lần nữa.","note":"去过一次 là động từ cộng 过 cộng bổ ngữ số lần 一次, nói đã từng đến một lần; 再去一次 nói muốn đến thêm một lần nữa."},{"han":"出门旅游，多个朋友多条路。","pinyin":"Chūmén lǚyóu, duō ge péngyou duō tiáo lù.","meaning":"Đi du lịch, càng nhiều bạn càng nhiều đường.","note":"多个...多... là cấu trúc đối xứng: càng nhiều bạn thì càng nhiều đường đi, diễn tả quan hệ tỉ lệ thuận."},{"han":"你有一年没回国了吧？","pinyin":"Nǐ yǒu yì nián méi huí guó le ba?","meaning":"Bạn đã một năm không về nước rồi phải không?","note":"有一年 là 有 cộng cụm số lượng, nói đã đạt đến khoảng thời gian một năm không về nước."},{"han":"家月说我们好像小鸟，一起飞到北京。","pinyin":"","meaning":"Gia Nguyệt nói chúng tôi giống như những chú chim nhỏ, cùng bay đến Bắc Kinh.","note":"好像 cộng danh từ 小鸟 diễn tả sự ví von; 飞到北京 là động từ 飞 cộng bổ ngữ xu hướng 到 chỉ đích đến."}],"theme":"Du lịch và số lần","translation":"Tôi muốn đến Trung Quốc thêm một lần nữa","vocab":[{"emoji":"📝","example":"请大家写上姓名，写好后就可以做题了。","examplePinyin":"Qǐng dàjiā xiě shang xìngmíng, xiěhǎo hòu jiù kěyǐ zuò tí le.","exampleVi":"Mời mọi người viết họ tên lên, viết xong là có thể làm bài.","meaning":"họ tên","pinyin":"xìngmíng","pos":"Danh từ","word":"姓名"},{"emoji":"🛫","example":"考完试了，我现在可以出国旅游了。","examplePinyin":"Kǎowán shì le, wǒ xiànzài kěyǐ chūguó lǚyóu le.","exampleVi":"Thi xong rồi, bây giờ tôi có thể ra nước ngoài du lịch.","meaning":"ra nước ngoài","pinyin":"chūguó","pos":"Động từ","word":"出国"},{"emoji":"🎟️","example":"我还在网上买好颐和园的门票了呢。","examplePinyin":"Wǒ hái zài wǎngshang mǎihǎo Yíhé Yuán de ménpiào le ne.","exampleVi":"Tôi còn mua sẵn vé vào Di Hòa Viên trên mạng rồi.","meaning":"vé vào cửa","pinyin":"ménpiào","pos":"Danh từ","word":"门票"},{"emoji":"🏫","example":"我的高中同学就在颐和园上班。","examplePinyin":"Wǒ de gāozhōng tóngxué jiù zài Yíhé Yuán shàngbān.","exampleVi":"Bạn học cấp ba của tôi làm việc ở Di Hòa Viên.","meaning":"trung học phổ thông","pinyin":"gāozhōng","pos":"Danh từ","word":"高中"},{"emoji":"🚶","example":"出门旅游，多个朋友多条路。","examplePinyin":"Chūmén lǚyóu, duō ge péngyou duō tiáo lù.","exampleVi":"Đi du lịch, càng nhiều bạn càng nhiều đường.","meaning":"ra khỏi nhà, đi ra ngoài","pinyin":"chūmén","pos":"Động từ","word":"出门"},{"emoji":"🛣️","example":"去机场的路很远。","examplePinyin":"Qù jīchǎng de lù hěn yuǎn.","exampleVi":"Đường đi sân bay rất xa.","meaning":"đường","pinyin":"lù","pos":"Danh từ","word":"路"},{"emoji":"🛬","example":"还是我送你去的机场呢。","examplePinyin":"Hái shì wǒ sòng nǐ qù de jīchǎng ne.","exampleVi":"Vẫn là tôi đưa bạn ra sân bay mà.","meaning":"sân bay","pinyin":"jīchǎng","pos":"Danh từ","word":"机场"},{"emoji":"🎫","example":"我记得你那次的机票很便宜。","examplePinyin":"Wǒ jìde nǐ nà cì de jīpiào hěn piányi.","exampleVi":"Tôi nhớ vé máy bay lần đó của bạn rất rẻ.","meaning":"vé máy bay","pinyin":"jīpiào","pos":"Danh từ","word":"机票"},{"emoji":"✈️","example":"但想到就要飞北京了，我还是很高兴的。","examplePinyin":"Dàn xiǎngdào jiù yào fēi Běijīng le, wǒ hái shì hěn gāoxìng de.","exampleVi":"Nhưng nghĩ đến việc sắp bay đến Bắc Kinh, tôi vẫn rất vui.","meaning":"bay","pinyin":"fēi","pos":"Động từ","word":"飞"},{"emoji":"🤔","example":"家月说我们好像小鸟，一起飞到北京。","examplePinyin":"Jiāyuè shuō wǒmen hǎoxiàng xiǎoniǎo, yìqǐ fēi dào Běijīng.","exampleVi":"Gia Nguyệt nói chúng tôi giống như những chú chim nhỏ, cùng bay đến Bắc Kinh.","meaning":"giống như, dường như","pinyin":"hǎoxiàng","pos":"Động từ","word":"好像"},{"emoji":"🐦","example":"家月说我们好像小鸟。","examplePinyin":"Jiāyuè shuō wǒmen hǎoxiàng xiǎoniǎo.","exampleVi":"Gia Nguyệt nói chúng tôi giống như những chú chim nhỏ.","meaning":"chim","pinyin":"niǎo","pos":"Danh từ","word":"鸟"},{"emoji":"🏛️","example":"我的高中同学就在颐和园上班。","examplePinyin":"Wǒ de gāozhōng tóngxué jiù zài Yíhé Yuán shàngbān.","exampleVi":"Bạn học cấp ba của tôi làm việc ở Di Hòa Viên.","meaning":"Di Hòa Viên","pinyin":"Yíhéyuán","pos":"Danh từ","word":"颐和园"}]}];
window.sceneData = window.sceneData2 = {"1":[{"context":"Ở sân bay, Vương Nhất Tuyết đón Bạch Gia Nguyệt và Annie.","contextZh":"在机场，王一雪接到了白家月和安妮。","label":"1-1 · Đón ở sân bay","lines":[["白家月","请问，您是王一飞老师的姐姐吗？","Qǐngwèn, nín shì Wáng Yīfēi lǎoshī de jiějie ma?","Xin hỏi, cô có phải là chị gái của thầy Vương Nhất Phi không ạ?"],["王一雪","是的，你们就是她的学生吧？","Shì de, nǐmen jiù shì tā de xuéshēng ba?","Đúng vậy, các bạn chính là học sinh của cô ấy phải không?"],["白家月","对。我是白家月，她是安妮。","Duì. Wǒ shì Bái Jiāyuè, tā shì Ānnī.","Đúng ạ. Tôi là Bạch Gia Nguyệt, còn đây là Annie."],["王一雪","你们好，我叫王一雪。一飞给我打电话了，让我来接你们。","Nǐmen hǎo, wǒ jiào Wáng Yīxuě. Yīfēi gěi wǒ dǎ diànhuà le, ràng wǒ lái jiē nǐmen.","Chào các bạn, tôi tên là Vương Nhất Tuyết. Nhất Phi đã gọi điện cho tôi, nhờ tôi đến đón các bạn."],["白家月和安妮","谢谢您。","Xièxie nín.","Cảm ơn cô ạ."],["王一雪","不客气。","Bú kèqi.","Không có gì."]],"sides":{"王一雪":"R","白家月":"L","白家月和安妮":"L"}},{"context":"Trên xe của Vương Nhất Tuyết, Bạch Gia Nguyệt, Annie và Vương Nhất Tuyết đang trò chuyện.","contextZh":"在王一雪的车里，白家月、安妮和王一雪在聊天儿。","label":"1-2 · Trò chuyện trên xe","lines":[["王一雪","你们是第一次来北京吗？","Nǐmen shì dì-yī cì lái Běijīng ma?","Đây có phải là lần đầu tiên các bạn đến Bắc Kinh không?"],["白家月","是的，我们都是第一次来。","Shì de, wǒmen dōu shì dì-yī cì lái.","Vâng, chúng tôi đều là lần đầu tiên đến."],["王一雪","你们是来学中文的吗？","Nǐmen shì lái xué Zhōngwén de ma?","Các bạn đến để học tiếng Trung phải không?"],["安妮","不是，我们是来旅游的。","Bú shì, wǒmen shì lái lǚyóu de.","Không phải, chúng tôi đến để du lịch."],["王一雪","我这几天都不忙，你们有事就找我。","Wǒ zhè jǐ tiān dōu bù máng, nǐmen yǒu shì jiù zhǎo wǒ.","Mấy ngày này tôi đều không bận, các bạn có việc gì cứ tìm tôi."],["白家月","好的，谢谢您。","Hǎo de, xièxie nín.","Vâng, cảm ơn cô ạ."]],"sides":{"安妮":"R","王一雪":"L","白家月":"R"}},{"context":"Trên xe của Vương Nhất Tuyết, Bạch Gia Nguyệt nhận được điện thoại của Trần Thiên Trung.","contextZh":"在王一雪的车上，白家月接了个电话。","label":"1-3 · Cuộc điện thoại trên xe","lines":[["陈天中","喂，家月，你明天有时间吗？我想请你帮个忙。","Wèi, Jiāyuè, nǐ míngtiān yǒu shíjiān ma? Wǒ xiǎng qǐng nǐ bāng ge máng.","A lô, Gia Nguyệt, ngày mai bạn có thời gian không? Tôi muốn nhờ bạn giúp một việc."],["白家月","不好意思，天中，我已经到北京了。","Bù hǎoyìsi, Tiānzhōng, wǒ yǐjīng dào Běijīng le.","Xin lỗi, Thiên Trung, tôi đã đến Bắc Kinh rồi."],["陈天中","你是什么时候到的？","Nǐ shì shénme shíhou dào de?","Bạn đến lúc nào vậy?"],["白家月","我是今天早上到的。你有事可以叫李文帮忙，他还在学校呢。","Wǒ shì jīntiān zǎoshang dào de. Nǐ yǒu shì kěyǐ jiào Lǐ Wén bāngmáng, tā hái zài xuéxiào ne.","Tôi đến sáng nay. Bạn có việc gì có thể nhờ Lý Văn giúp, cậu ấy vẫn còn ở trường."],["陈天中","好的，那我给他打个电话。","Hǎo de, nà wǒ gěi tā dǎ ge diànhuà.","Được, vậy thì tôi gọi điện cho cậu ấy."],["白家月","好，再见！","Hǎo, zàijiàn!","Được, tạm biệt nhé!"]],"sides":{"白家月":"R","陈天中":"L"}},{"context":"Ở khách sạn, Bạch Gia Nguyệt nhắn tin cho thầy Vương Nhất Phi.","contextZh":"在酒店，白家月给王一飞发信息。","label":"1-4 · Tin nhắn gửi thầy Vương","lines":[["白家月","王老师，我们已经到北京了。","Wáng lǎoshī, wǒmen yǐjīng dào Běijīng le.","Thưa thầy Vương, chúng em đã đến Bắc Kinh rồi ạ."],["白家月","是您姐姐来接的我们。","Shì nín jiějie lái jiē de wǒmen.","Chính chị gái của thầy đã đến đón chúng em."],["白家月","她请我们吃了北京烤鸭，还给我们介绍了很多东西。","Tā qǐng wǒmen chī le Běijīng Kǎoyā, hái gěi wǒmen jièshào le hěn duō dōngxi.","Chị ấy mời chúng em ăn vịt quay Bắc Kinh, còn giới thiệu cho chúng em rất nhiều thứ."],["白家月","我们的中文不太好，有时不太懂她的意思。","Wǒmen de Zhōngwén bú tài hǎo, yǒushí bú tài dǒng tā de yìsi.","Tiếng Trung của chúng em không tốt lắm, đôi khi không hiểu rõ ý của chị ấy."]],"sides":{"白家月":"C"}}],"2":[{"context":"Ở quầy lễ tân khách sạn, Bạch Gia Nguyệt và Annie hỏi nhân viên phục vụ.","contextZh":"在宾馆前台，白家月和安妮向服务员咨询。","label":"2-1 · Hỏi đường ở quầy lễ tân","lines":[["白家月","请问，这儿有到北京大学的公交车吗？","Qǐngwèn, zhèr yǒu dào Běijīng Dàxué de gōngjiāochē ma?","Xin hỏi, ở đây có xe buýt đi Đại học Bắc Kinh không ạ?"],["服务员","有，但车站有点儿远。","Yǒu, dàn chēzhàn yǒudiǎnr yuǎn.","Có, nhưng trạm xe hơi xa."],["白家月","这儿好打车吗？","Zhèr hǎo dǎchē ma?","Ở đây có dễ đón taxi không?"],["服务员","好打车。","Hǎo dǎchē.","Dễ đón taxi."],["白家月","谢谢。安妮，我们还是打车去吧。","Xièxie. Ānnī, wǒmen háishi dǎchē qù ba.","Cảm ơn. Annie, chúng ta vẫn nên đi taxi thì hơn."],["安妮","好，没问题。","Hǎo, méi wèntí.","Được, không vấn đề gì."]],"sides":{"安妮":"L","服务员":"R","白家月":"L"}},{"context":"Ở Đại học Bắc Kinh, Bạch Gia Nguyệt và Annie đang tham quan khuôn viên trường.","contextZh":"在北京大学，白家月和安妮在参观校园。","label":"2-2 · Tham quan trường Đại học Bắc Kinh","lines":[["白家月","学校里人真多啊！","Xuéxiào lǐ rén zhēn duō a!","Trong trường đông người thật đấy!"],["安妮","是啊，北京大学有四万多名学生呢！","Shì a, Běijīng Dàxué yǒu sìwàn duō míng xuéshēng ne!","Đúng vậy, Đại học Bắc Kinh có hơn bốn vạn sinh viên đấy!"],["白家月","你是怎么知道的？","Nǐ shì zěnme zhīdào de?","Bạn biết bằng cách nào vậy?"],["安妮","是网上说的，网上还说北京大学有三千多名外国学生。","Shì wǎngshang shuō de, wǎngshang hái shuō Běijīng Dàxué yǒu sānqiān duō míng wàiguó xuéshēng.","Là trên mạng nói vậy, trên mạng còn nói Đại học Bắc Kinh có hơn ba nghìn sinh viên nước ngoài."],["白家月","我也想来这儿学习。","Wǒ yě xiǎng lái zhèr xuéxí.","Tôi cũng muốn đến đây học."],["安妮","那边就有一间教室，我们去看一下吧。","Nàbiān jiù yǒu yì jiān jiàoshì, wǒmen qù kàn yíxià ba.","Bên kia có một phòng học, chúng ta qua xem một chút nhé."]],"sides":{"安妮":"R","白家月":"L"}},{"context":"Ở Đại học Bắc Kinh, Bạch Gia Nguyệt và Annie đang tham quan khuôn viên trường.","contextZh":"在北京大学，白家月和安妮在参观校园。","label":"2-3 · Rạp chiếu phim trong trường","lines":[["安妮","家月，你看，学校里有家电影院！","Jiāyuè, nǐ kàn, xuéxiào lǐ yǒu jiā diànyǐngyuàn!","Gia Nguyệt, bạn xem này, trong trường có một rạp chiếu phim!"],["白家月","是啊，电影院还不小。","Shì a, diànyǐngyuàn hái bù xiǎo.","Đúng vậy, rạp chiếu phim còn không nhỏ đâu."],["安妮","他们卖的电影票也很便宜。","Tāmen mài de diànyǐngpiào yě hěn piányi.","Vé xem phim họ bán cũng rất rẻ."],["白家月","天啊！有的还不到二十块钱。","Tiān a! Yǒude hái bú dào èrshí kuài qián.","Trời ơi! Có vé còn chưa đến hai mươi đồng."],["安妮","那你想不想去看个电影？","Nà nǐ xiǎng bu xiǎng qù kàn ge diànyǐng?","Vậy bạn có muốn đi xem một bộ phim không?"],["白家月","还是别看电影了，北京大学就很好看！","Háishi bié kàn diànyǐng le, Běijīng Dàxué jiù hěn hǎokàn!","Vẫn là đừng xem phim nữa, Đại học Bắc Kinh đã rất đẹp rồi!"]],"sides":{"安妮":"L","白家月":"R"}},{"context":"Ở cổng Đại học Bắc Kinh, Bạch Gia Nguyệt nhắn tin cho Trần Thiên Trung.","contextZh":"在北京大学门口，白家月给陈天中发信息。","label":"2-4 · Tin nhắn gửi Trần Thiên Trung","lines":[["白家月","北京大学很大，有四万多名学生。","Běijīng Dàxué hěn dà, yǒu sìwàn duō míng xuéshēng.","Đại học Bắc Kinh rất lớn, có hơn bốn vạn sinh viên."],["白家月","学校很漂亮，里边还有家电影院。","Xuéxiào hěn piàoliang, lǐbian hái yǒu jiā diànyǐngyuàn.","Trường rất đẹp, bên trong còn có một rạp chiếu phim."],["白家月","电影票也不贵，我们有时间还想再过来看个电影。","Diànyǐngpiào yě bú guì, wǒmen yǒu shíjiān hái xiǎng zài guòlái kàn ge diànyǐng.","Vé xem phim cũng không đắt, khi có thời gian chúng tôi còn muốn quay lại xem một bộ phim."]],"sides":{"白家月":"C"}}],"3":[{"context":"Ở cửa nhà, Lưu Minh mở cửa bước vào nhà.","contextZh":"在家门口，刘明开门进到家里。","label":"3-1 · Về nhà muộn","lines":[["王一雪","今天回来这么晚啊！","Jīntiān huílái zhème wǎn a!","Hôm nay về muộn thế!"],["刘明","工作太多了，下班的时候没做完。","Gōngzuò tài duō le, xiàbān de shíhou méi zuòwán.","Việc nhiều quá, lúc tan làm vẫn chưa làm xong."],["王一雪","菜都做好了，过来吃饭吧。","Cài dōu zuòhǎo le, guòlái chī fàn ba.","Cơm đã nấu xong hết rồi, qua đây ăn cơm đi."],["刘明","我想休息一下，喝杯水。","Wǒ xiǎng xiūxi yíxià, hē bēi shuǐ.","Tôi muốn nghỉ một lát, uống cốc nước."],["王一雪","好的。","Hǎo de.","Được."]],"sides":{"刘明":"R","王一雪":"L"}},{"context":"Ở phòng khách, Lưu Minh và Vương Nhất Tuyết đang trò chuyện.","contextZh":"在客厅，刘明和王一雪在聊天儿。","label":"3-2 · Hẹn đi du lịch","lines":[["刘明","我们找个时间去旅游，怎么样？","Wǒmen zhǎo ge shíjiān qù lǚyóu, zěnmeyàng?","Chúng ta tìm thời gian đi du lịch nhé, thế nào?"],["王一雪","好啊，我也很想一起出去玩。","Hǎo a, wǒ yě hěn xiǎng yìqǐ chūqù wán.","Hay đấy, tôi cũng rất muốn cùng đi chơi."],["刘明","你想去哪儿？","Nǐ xiǎng qù nǎr?","Bạn muốn đi đâu?"],["王一雪","我还没想好呢。","Wǒ hái méi xiǎnghǎo ne.","Tôi vẫn chưa nghĩ ra."],["刘明","那你再想一想，你想好了，我来买票。","Nà nǐ zài xiǎng yi xiǎng, nǐ xiǎnghǎo le, wǒ lái mǎi piào.","Vậy bạn nghĩ thêm đi, bạn nghĩ xong rồi thì tôi đi mua vé."]],"sides":{"刘明":"L","王一雪":"R"}},{"context":"Ở phòng khách, Lưu Minh và Vương Nhất Tuyết đang trò chuyện.","contextZh":"在客厅，刘明和王一雪在聊天儿。","label":"3-3 · Muốn đi Tây An","lines":[["刘明","吃个苹果吧，我都洗好了。","Chī ge píngguǒ ba, wǒ dōu xǐhǎo le.","Ăn quả táo đi, tôi đã rửa sạch hết rồi."],["王一雪","好的。","Hǎo de.","Được."],["刘明","就在桌子上，你自己拿。","Jiù zài zhuōzi shang, nǐ zìjǐ ná.","Ngay trên bàn đấy, bạn tự lấy đi."],["王一雪","我去洗洗手。对了，我们去西安旅游，怎么样？","Wǒ qù xǐxi shǒu. Duìle, wǒmen qù Xī'ān lǚyóu, zěnmeyàng?","Tôi đi rửa tay một cái. À này, chúng ta đi Tây An du lịch nhé, thế nào?"],["刘明","为什么想去西安？","Wèi shénme xiǎng qù Xī'ān?","Tại sao muốn đi Tây An?"],["王一雪","我看了看网上的介绍，这个时候去西安很不错！","Wǒ kànle kàn wǎngshang de jièshào, zhège shíhou qù Xī'ān hěn búcuò!","Tôi đã xem qua giới thiệu trên mạng, đi Tây An vào lúc này rất tuyệt!"]],"sides":{"刘明":"L","王一雪":"R"}},{"context":"Ở nhà, Vương Nhất Tuyết gọi điện cho bạn thân.","contextZh":"在家里，王一雪给好朋友打电话。","label":"3-4 · Gọi điện cho bạn thân","lines":[["王一雪","早上，刘明开车送孩子去学校。","Zǎoshang, Liú Míng kāichē sòng háizi qù xuéxiào.","Buổi sáng, Lưu Minh lái xe đưa con đi học."],["王一雪","送完孩子回家后，医院就来电话了，让他回去上班。","Sòngwán háizi huí jiā hòu, yīyuàn jiù lái diànhuà le, ràng tā huíqù shàngbān.","Đưa con xong về đến nhà thì bệnh viện gọi điện đến, bảo anh ấy quay lại đi làm."],["王一雪","我觉得他这个月每天都很累，真想让他休息休息。","Wǒ juéde tā zhège yuè měitiān dōu hěn lèi, zhēn xiǎng ràng tā xiūxi xiūxi.","Tôi thấy tháng này ngày nào anh ấy cũng rất mệt, thật muốn để anh ấy nghỉ ngơi một chút."]],"sides":{"王一雪":"C"}}],"4":[{"context":"Ở cửa trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang trò chuyện.","contextZh":"在商场门口，王一雪和刘小雪在聊天儿。","label":"4-1 · Trước cửa trung tâm thương mại","lines":[["刘小雪","妈妈，我们来过这家商场吗？","Māma, wǒmen láiguo zhè jiā shāngchǎng ma?","Mẹ ơi, chúng ta đã từng đến trung tâm thương mại này chưa?"],["王一雪","没来过，这是新开的。","Méi láiguo, zhè shì xīn kāi de.","Chưa từng đến, đây là chỗ mới mở."],["刘小雪","我们进去看看吧。","Wǒmen jìnqù kànkan ba.","Chúng ta vào trong xem thử đi."],["王一雪","好啊！你想买点儿什么？","Hǎo a! Nǐ xiǎng mǎi diǎnr shénme?","Được đấy! Con muốn mua chút gì?"],["刘小雪","我想买条裤子。","Wǒ xiǎng mǎi tiáo kùzi.","Con muốn mua một chiếc quần."],["王一雪","没问题。","Méi wèntí.","Không vấn đề gì."]],"sides":{"刘小雪":"L","王一雪":"R"}},{"context":"Trong trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang xem quần áo.","contextZh":"在商场，王一雪和刘小雪在看衣服。","label":"4-2 · Chọn quần trong trung tâm","lines":[["刘小雪","妈妈，我想买这条白色的裤子。","Māma, wǒ xiǎng mǎi zhè tiáo báisè de kùzi.","Mẹ ơi, con muốn mua chiếc quần màu trắng này."],["王一雪","你有很多白色的衣服，为什么还买白色的？","Nǐ yǒu hěn duō báisè de yīfu, wèi shénme hái mǎi báisè de?","Con đã có rất nhiều quần áo màu trắng, tại sao còn mua màu trắng nữa?"],["刘小雪","因为我喜欢白色啊！","Yīnwèi wǒ xǐhuan báisè a!","Vì con thích màu trắng mà!"],["王一雪","我觉得这条白色的不太好看，你试试那条红色的吧。","Wǒ juéde zhè tiáo báisè de bú tài hǎokàn, nǐ shìshi nà tiáo hóngsè de ba.","Mẹ thấy chiếc quần màu trắng này không đẹp lắm, con thử chiếc màu đỏ kia đi."],["刘小雪","我没穿过红色的，红色的好看吗？","Wǒ méi chuānguo hóngsè de, hóngsè de hǎokàn ma?","Con chưa từng mặc màu đỏ, màu đỏ có đẹp không?"],["王一雪","就是因为没穿过，所以要试试啊！","Jiù shì yīnwèi méi chuānguo, suǒyǐ yào shìshi a!","Chính vì chưa từng mặc nên mới phải thử chứ!"]],"sides":{"刘小雪":"L","王一雪":"R"}},{"context":"Trong trung tâm thương mại, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang xem cặp sách.","contextZh":"在商场，王一雪和刘小雪在看书包。","label":"4-3 · Chọn cặp sách","lines":[["刘小雪","妈妈，我想买个新书包。","Māma, wǒ xiǎng mǎi ge xīn shūbāo.","Mẹ ơi, con muốn mua một chiếc cặp sách mới."],["王一雪","好，那边卖书包，我们过去看看吧。","Hǎo, nàbiān mài shūbāo, wǒmen guòqù kànkan ba.","Được, bên kia bán cặp sách, chúng ta qua đó xem thử đi."],["刘小雪","这么多漂亮的书包！","Zhème duō piàoliang de shūbāo!","Nhiều cặp sách đẹp thế!"],["王一雪","红色的、绿色的、黑色的，你想买哪个？","Hóngsè de, lǜsè de, hēisè de, nǐ xiǎng mǎi nǎge?","Màu đỏ, màu xanh lá, màu đen, con muốn mua cái nào?"],["刘小雪","绿色的吧。","Lǜsè de ba.","Lấy màu xanh lá đi."],["王一雪","不错，我也觉得绿色的更好看。","Búcuò, wǒ yě juéde lǜsè de gèng hǎokàn.","Không tệ, mẹ cũng thấy màu xanh lá đẹp hơn."]],"sides":{"刘小雪":"L","王一雪":"R"}},{"context":"Trong phòng, Lưu Tiểu Tuyết đang viết nhật ký.","contextZh":"在房间，刘小雪在写日记。","label":"4-4 · Nhật ký của Lưu Tiểu Tuyết","lines":[["刘小雪","我和妈妈去了一家商场。","Wǒ hé māma qùle yì jiā shāngchǎng.","Tôi và mẹ đã đi một trung tâm thương mại."],["刘小雪","因为是新开的，所以这几天东西很便宜。","Yīnwèi shì xīn kāi de, suǒyǐ zhè jǐ tiān dōngxi hěn piányi.","Vì là chỗ mới mở nên mấy ngày này đồ đạc rất rẻ."],["刘小雪","商场里的衣服颜色很多。","Shāngchǎng lǐ de yīfu yánsè hěn duō.","Quần áo trong trung tâm thương mại có rất nhiều màu sắc."],["刘小雪","我没穿过红色的裤子，妈妈让我试了试，我觉得我穿红色的也很好看。","Wǒ méi chuānguo hóngsè de kùzi, māma ràng wǒ shìle shì, wǒ juéde wǒ chuān hóngsè de yě hěn hǎokàn.","Tôi chưa từng mặc quần màu đỏ, mẹ bảo tôi thử một chút, tôi thấy mình mặc màu đỏ cũng rất đẹp."]],"sides":{"刘小雪":"C"}}],"5":[{"context":"Dưới khách sạn, Annie gọi điện cho Bạch Gia Nguyệt.","contextZh":"在宾馆楼下，安妮给白家月打电话。","label":"5-1 · Gọi điện dưới khách sạn","lines":[["安妮","家月，快下来吧，第一次去中国朋友家，别晚了。","Jiāyuè, kuài xiàlái ba, dì-yī cì qù Zhōngguó péngyou jiā, bié wǎn le.","Gia Nguyệt, mau xuống đi, lần đầu đến nhà bạn người Trung Quốc, đừng muộn nhé."],["白家月","还有时间，你上来吧。","Hái yǒu shíjiān, nǐ shànglái ba.","Vẫn còn thời gian, bạn lên đây đi."],["安妮","我不上去了，就在下面等你。","Wǒ bú shàngqù le, jiù zài xiàmiàn děng nǐ.","Tôi không lên nữa, cứ đợi bạn ở dưới này."],["白家月","那我一会儿就下去。","Nà wǒ yíhuìr jiù xiàqù.","Vậy tôi sẽ xuống ngay trong một lát."],["安妮","你快点儿吧。","Nǐ kuài diǎnr ba.","Bạn nhanh lên nhé."],["白家月","没事，一雪姐说11点前到就可以。","Méishì, Yīxuě jiě shuō 11 diǎn qián dào jiù kěyǐ.","Không sao, chị Nhất Tuyết nói đến trước 11 giờ là được."]],"sides":{"安妮":"L","白家月":"R"}},{"context":"Ở nhà Vương Nhất Tuyết, Bạch Gia Nguyệt và Annie đến làm khách.","contextZh":"在王一雪家，白家月和安妮来做客。","label":"5-2 · Đến nhà chị Nhất Tuyết","lines":[["王一雪","家月、安妮，快进来！我给你们介绍一下，这是孩子们的爷爷、奶奶。","Jiāyuè, Ānnī, kuài jìnlái! Wǒ gěi nǐmen jièshào yíxià, zhè shì háizimen de yéye, nǎinai.","Gia Nguyệt, Annie, mau vào đây! Tôi giới thiệu với các bạn một chút, đây là ông và bà của các cháu."],["白家月和安妮","你们好！","Nǐmen hǎo!","Chào ông bà ạ!"],["王一雪","爸，妈，这是白家月，这是安妮。她们都是一飞的学生。","Bà, mā, zhè shì Bái Jiāyuè, zhè shì Ānnī. Tāmen dōu shì Yīfēi de xuéshēng.","Bố, mẹ, đây là Bạch Gia Nguyệt, đây là Annie. Hai bạn đều là học sinh của Nhất Phi."],["刘爷爷","家月、安妮，你们好！","Jiāyuè, Ānnī, nǐmen hǎo!","Gia Nguyệt, Annie, chào các cháu!"],["白家月","这是送你们的礼物。","Zhè shì sòng nǐmen de lǐwù.","Đây là quà tặng ông bà."],["刘爷爷","你们太客气了，还拿这么多礼物来！","Nǐmen tài kèqi le, hái ná zhème duō lǐwù lái!","Các cháu khách sáo quá, còn mang nhiều quà đến thế!"],["白家月","一雪姐，这是给孩子们准备的礼物。","Yīxuě jiě, zhè shì gěi háizimen zhǔnbèi de lǐwù.","Chị Nhất Tuyết, đây là quà đã chuẩn bị cho các cháu."],["王一雪","谢谢！你们别客气，快坐吧！","Xièxie! Nǐmen bié kèqi, kuài zuò ba!","Cảm ơn! Các bạn đừng khách sáo, mau ngồi đi!"]],"sides":{"刘爷爷":"L","安妮":"R","王一雪":"L","白家月":"R","白家月和安妮":"R"}},{"context":"Ở nhà Vương Nhất Tuyết, Bạch Gia Nguyệt và Annie đang ăn cơm.","contextZh":"在王一雪家，白家月和安妮在吃饭。","label":"5-3 · Ăn cơm ở nhà chị Nhất Tuyết","lines":[["王一雪","都12点了，我们吃饭吧。","Dōu shí'èr diǎn le, wǒmen chī fàn ba.","Đã 12 giờ rồi, chúng ta ăn cơm đi."],["白家月","这么多好吃的，您太客气了！","Zhème duō hǎochī de, nín tài kèqi le!","Nhiều món ngon thế này, cô khách sáo quá!"],["王一雪","都是我自己做的，你们多吃点儿。","Dōu shì wǒ zìjǐ zuò de, nǐmen duō chī diǎnr.","Đều là tự tay tôi nấu, các bạn ăn nhiều một chút nhé."],["白家月","奶茶也很好喝，是您自己做的吗？","Nǎichá yě hěn hǎohē, shì nín zìjǐ zuò de ma?","Trà sữa cũng rất ngon, có phải tự tay cô làm không?"],["王一雪","不是，奶茶是爷爷买的。","Bú shì, nǎichá shì yéye mǎi de.","Không phải, trà sữa là ông mua đấy."],["白家月","在哪儿买的？我还没喝过这么好喝的奶茶。","Zài nǎr mǎi de? Wǒ hái méi hēguo zhème hǎohē de nǎichá.","Mua ở đâu vậy? Tôi chưa từng uống trà sữa nào ngon thế này."],["王一雪","就在前边的商场，吃完饭你们可以跟我去看看。","Jiù zài qiánbian de shāngchǎng, chīwán fàn nǐmen kěyǐ gēn wǒ qù kànkan.","Ngay ở trung tâm thương mại phía trước, ăn cơm xong các bạn có thể đi xem cùng tôi."]],"sides":{"王一雪":"L","白家月":"R"}},{"context":"Ở khách sạn, Bạch Gia Nguyệt nhắn tin cho Lý Văn.","contextZh":"在宾馆，白家月给李文发信息。","label":"5-4 · Tin nhắn gửi Lý Văn","lines":[["白家月","回国前一天，我们去一雪姐家了。","Huí guó qián yì tiān, wǒmen qù Yīxuě jiě jiā le.","Một ngày trước khi về nước, chúng tôi đã đến nhà chị Nhất Tuyết."],["白家月","到她家的时候，饭菜都做好了。","Dào tā jiā de shíhou, fàncài dōu zuòhǎo le.","Khi đến nhà chị, cơm canh đã nấu xong hết rồi."],["白家月","刘爷爷还准备了奶茶。","Liú yéye hái zhǔnbèi le nǎichá.","Ông Lưu còn chuẩn bị cả trà sữa."],["白家月","因为吃了太多东西，我们吃完饭是走回酒店的。","Yīnwèi chī le tài duō dōngxi, wǒmen chīwán fàn shì zǒu huí jiǔdiàn de.","Vì ăn quá nhiều nên ăn cơm xong chúng tôi đi bộ về khách sạn."]],"sides":{"白家月":"C"}}],"6":[{"context":"Ở nhà, Lưu Minh và Vương Nhất Tuyết đang trò chuyện.","contextZh":"在家里，刘明和王一雪在聊天儿。","label":"6-1 · Chuẩn bị quà sinh nhật","lines":[["王一雪","明天就是女儿的生日了。","Míngtiān jiù shì nǚ'ér de shēngrì le.","Ngày mai là sinh nhật của con gái rồi."],["刘明","你不说，我还真忘了。我们给她准备个什么礼物呢？","Nǐ bù shuō, wǒ hái zhēn wàng le. Wǒmen gěi tā zhǔnbèi ge shénme lǐwù ne?","Bạn không nói thì tôi thật sự đã quên mất rồi. Chúng ta chuẩn bị cho con bé món quà gì đây?"],["王一雪","她喜欢画画，你觉得画笔怎么样？","Tā xǐhuan huà huà, nǐ juéde huàbǐ zěnmeyàng?","Con bé thích vẽ tranh, bạn thấy bút vẽ thế nào?"],["刘明","就送画笔吧！","Jiù sòng huàbǐ ba!","Cứ tặng bút vẽ đi!"],["王一雪","那我明天上午就去买。","Nà wǒ míngtiān shàngwǔ jiù qù mǎi.","Vậy sáng mai tôi sẽ đi mua."],["刘明","好的！我再给她买个大大的生日蛋糕。","Hǎo de! Wǒ zài gěi tā mǎi ge dàdà de shēngrì dàngāo.","Được! Tôi sẽ mua thêm cho con bé một cái bánh sinh nhật thật to."]],"sides":{"刘明":"L","王一雪":"R"}},{"context":"Ở phòng khách, cả nhà Lưu Minh đang trò chuyện.","contextZh":"在客厅，刘明一家人在聊天儿。","label":"6-2 · Tặng quà sinh nhật","lines":[["刘明","小雪，生日快乐！","Xiǎoxuě, shēngrì kuàilè!","Tiểu Tuyết, chúc mừng sinh nhật!"],["刘小明","姐姐，生日快乐！","Jiějie, shēngrì kuàilè!","Chị ơi, chúc mừng sinh nhật!"],["王一雪","小雪，这是爸爸、妈妈送你的礼物。","Xiǎoxuě, zhè shì bàba, māma sòng nǐ de lǐwù.","Tiểu Tuyết, đây là quà bố mẹ tặng con."],["刘明","你打开看看喜欢不喜欢。","Nǐ dǎkāi kànkan xǐhuan bu xǐhuan.","Con mở ra xem có thích không."],["刘小雪","画笔！我很喜欢！","Huàbǐ! Wǒ hěn xǐhuan!","Bút vẽ! Con rất thích!"],["王一雪","那你想画点儿什么？","Nà nǐ xiǎng huà diǎnr shénme?","Vậy con muốn vẽ gì nào?"],["刘小雪","画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。","Huà wǒmen de jiā! Yǒu bàba, māma, dìdi, hái yǒu hēisè de gǒu, báisè de māo shénmede.","Vẽ nhà của chúng ta! Có bố, mẹ, em trai, còn có con chó đen, con mèo trắng các thứ nữa."],["刘小明","那我要画一个穿白色衣服的姐姐。","Nà wǒ yào huà yí ge chuān báisè yīfu de jiějie.","Vậy em sẽ vẽ một chị gái mặc quần áo trắng."]],"sides":{"刘小明":"R","刘小雪":"L","刘明":"L","王一雪":"R"}},{"context":"Ở phòng khách, cả nhà Lưu Minh đang mừng sinh nhật cho Lưu Tiểu Tuyết.","contextZh":"在客厅，刘明一家人给刘小雪过生日。","label":"6-3 · Bữa tiệc sinh nhật","lines":[["刘明","小雪，看看今天有什么好吃的。","Xiǎoxuě, kànkan jīntiān yǒu shénme hǎochī de.","Tiểu Tuyết, con xem hôm nay có món gì ngon nào."],["刘小雪","长长的面条儿，大大的蛋糕。","Chángcháng de miàntiáor, dàdà de dàngāo.","Mì sợi dài dài, bánh kem to to."],["刘明","你看，还有鱼啊肉啊什么的，都是你喜欢吃的。","Nǐ kàn, hái yǒu yú a ròu a shénmede, dōu shì nǐ xǐhuan chī de.","Con xem, còn có cá, thịt các thứ nữa, đều là món con thích ăn."],["刘小雪","谢谢爸爸、妈妈！","Xièxie bàba, māma!","Cảm ơn bố mẹ!"],["王一雪","快去叫弟弟过来吃饭吧，吃完饭我们还要出去玩呢。","Kuài qù jiào dìdi guòlái chī fàn ba, chīwán fàn wǒmen hái yào chūqù wán ne.","Mau đi gọi em trai lại ăn cơm đi, ăn xong chúng ta còn phải ra ngoài chơi nữa."],["刘小雪","过生日真好啊！","Guò shēngrì zhēn hǎo a!","Được mừng sinh nhật thật là thích!"],["王一雪","是的，过生日就要吃好吃的，还要高高兴兴地玩。","Shì de, guò shēngrì jiù yào chī hǎochī de, hái yào gāogāoxìngxìng de wán.","Đúng vậy, mừng sinh nhật thì phải ăn ngon, còn phải chơi thật vui vẻ."]],"sides":{"刘小雪":"R","刘明":"L","王一雪":"L"}},{"context":"Trong phòng, Vương Nhất Tuyết đang viết nhật ký.","contextZh":"在房间，王一雪在写日记。","label":"6-4 · Nhật ký của Vương Nhất Tuyết","lines":[["王一雪","今天是女儿的生日。","Jīntiān shì nǚ'ér de shēngrì.","Hôm nay là sinh nhật của con gái."],["王一雪","我们买了蛋糕，做了面条儿，还做了鱼啊肉啊什么的。","Wǒmen mǎi le dàngāo, zuò le miàntiáor, hái zuò le yú a ròu a shénmede.","Chúng tôi mua bánh kem, làm mì sợi, còn làm cả cá, thịt các thứ nữa."],["王一雪","吃完晚饭，一家人去看了个电影。","Chīwán wǎnfàn, yì jiā rén qù kàn le ge diànyǐng.","Ăn tối xong, cả nhà đi xem một bộ phim."],["王一雪","回家后，孩子们早早地就上床了。","Huí jiā hòu, háizimen zǎozǎo de jiù shàng chuáng le.","Về đến nhà, bọn trẻ đã lên giường đi ngủ từ sớm."],["王一雪","明天不上学，他们说要舒舒服服地睡一觉，让我们晚点儿叫他们起床。","Míngtiān bú shàngxué, tāmen shuō yào shūshūfúfú de shuì yí jiào, ràng wǒmen wǎn diǎnr jiào tāmen qǐchuáng.","Ngày mai không phải đi học, chúng bảo muốn ngủ một giấc thật thoải mái, nhờ chúng tôi gọi dậy muộn một chút."],["王一雪","这是很忙、很累，但很快乐的一天。","Zhè shì hěn máng, hěn lèi, dàn hěn kuàilè de yì tiān.","Đây là một ngày rất bận rộn, rất mệt, nhưng cũng rất vui."]],"sides":{"王一雪":"C"}}],"7":[{"context":"Trong lớp học, An Ni và Trần Thiên Trung đang trò chuyện.","contextZh":"在教室，安妮和陈天中在聊天儿。","label":"7-1 · Vừa tan học đã chạy đi chơi bóng","lines":[["陈天中","安妮，你是什么时候从北京回来的？","Ānnī, nǐ shì shénme shíhou cóng Běijīng huílái de?","An Ni, bạn trở về từ Bắc Kinh lúc nào?"],["安妮","昨天下午。天中，你怎么一下课就往外跑？","Zuótiān xiàwǔ. Tiānzhōng, nǐ zěnme yí xiàkè jiù wǎng wài pǎo?","Chiều hôm qua. Thiên Trung, sao bạn vừa tan học đã chạy ra ngoài?"],["陈天中","我跟同学说好了，一起去打篮球。","Wǒ gēn tóngxué shuōhǎo le, yìqǐ qù dǎ lánqiú.","Tôi đã hẹn với bạn học, cùng nhau đi chơi bóng rổ."],["安妮","我也想跟你们一起玩。","Wǒ yě xiǎng gēn nǐmen yìqǐ wán.","Tôi cũng muốn đi chơi cùng các bạn."],["陈天中","没问题，走吧。","Méi wèntí, zǒu ba.","Không vấn đề gì, đi thôi."]],"sides":{"安妮":"R","陈天中":"L"}},{"context":"Trên sân trường, An Ni và Trần Thiên Trung vừa đi vừa trò chuyện.","contextZh":"在校园，安妮和陈天中边走边聊。","label":"7-2 · Các môn thể thao yêu thích","lines":[["安妮","天中，你是不是很喜欢打篮球？","Tiānzhōng, nǐ shì bu shì hěn xǐhuan dǎ lánqiú?","Thiên Trung, bạn có rất thích chơi bóng rổ không?"],["陈天中","没错。","Méi cuò.","Đúng vậy."],["安妮","你还喜欢什么运动？","Nǐ hái xǐhuan shénme yùndòng?","Bạn còn thích môn thể thao nào nữa?"],["陈天中","我还喜欢踢足球，一到星期天就跟朋友们去踢球。","Wǒ hái xǐhuan tī zúqiú, yí dào Xīngqītiān jiù gēn péngyoumen qù tī qiú.","Tôi còn thích đá bóng nữa, cứ đến Chủ nhật là cùng các bạn đi đá bóng."],["安妮","你踢得怎么样？","Nǐ tī de zěnmeyàng?","Bạn đá thế nào?"],["陈天中","我踢得还可以。","Wǒ tī de hái kěyǐ.","Tôi đá cũng tạm được."]],"sides":{"安妮":"L","陈天中":"R"}},{"context":"Trên sân trường, An Ni và Trần Thiên Trung vừa đi vừa trò chuyện.","contextZh":"在校园，安妮和陈天中边走边聊。","label":"7-3 · Chơi bóng rổ, chạy bộ, bơi lội","lines":[["陈天中","你篮球打得怎么样？","Nǐ lánqiú dǎ de zěnmeyàng?","Bạn chơi bóng rổ thế nào?"],["安妮","打得还可以。","Dǎ de hái kěyǐ.","Chơi cũng tạm được."],["陈天中","跑步呢？你跑得快不快？","Pǎobù ne? Nǐ pǎo de kuài bu kuài?","Còn chạy bộ thì sao? Bạn chạy có nhanh không?"],["安妮","我跑得不快，也不太喜欢跑步。","Wǒ pǎo de bú kuài, yě bú tài xǐhuan pǎobù.","Tôi chạy không nhanh, cũng không thích chạy bộ lắm."],["陈天中","那你喜欢游泳吗？","Nà nǐ xǐhuan yóuyǒng ma?","Vậy bạn có thích bơi không?"],["安妮","喜欢，但我游泳游得不快。","Xǐhuan, dàn wǒ yóuyǒng yóu de bú kuài.","Thích, nhưng tôi bơi không nhanh."]],"sides":{"安妮":"R","陈天中":"L"}},{"context":"Trong phòng, Trần Thiên Trung đang viết nhật ký.","contextZh":"在房间，陈天中在写日记。","label":"7-4 · Nhật ký của Trần Thiên Trung","lines":[["陈天中","我的爱好是运动。","Wǒ de àihào shì yùndòng.","Sở thích của tôi là thể thao."],["陈天中","从上小学开始，我每天都跟爸爸去运动。","Cóng shàng xiǎoxué kāishǐ, wǒ měitiān dōu gēn bàba qù yùndòng.","Từ khi học tiểu học, ngày nào tôi cũng cùng bố đi tập thể thao."],["陈天中","现在我篮球打得很好，足球踢得不错，游泳游得也很快。","Xiànzài wǒ lánqiú dǎ de hěn hǎo, zúqiú tī de búcuò, yóuyǒng yóu de yě hěn kuài.","Bây giờ tôi chơi bóng rổ rất giỏi, đá bóng cũng khá tốt, bơi cũng rất nhanh."],["陈天中","我一有时间就去运动。","Wǒ yì yǒu shíjiān jiù qù yùndòng.","Cứ có thời gian rảnh là tôi lại đi tập thể thao."]],"sides":{"陈天中":"C"}}],"8":[{"context":"Ở trung tâm thương mại, Vương Nhất Tuyết và Lưu Minh đang mua sắm.","contextZh":"在商场，王一雪和刘明在购物。","label":"8-1 · Mua đồng hồ","lines":[["王一雪","你看，这两块手表怎么样？","Nǐ kàn, zhè liǎng kuài shǒubiǎo zěnmeyàng?","Bạn xem, hai cái đồng hồ này thế nào?"],["刘明","都不错！","Dōu búcuò!","Cả hai đều đẹp!"],["王一雪","我喜欢左边这个。","Wǒ xǐhuan zuǒbian zhège.","Tôi thích cái bên trái này."],["刘明","我也觉得左边的比右边的好看。","Wǒ yě juéde zuǒbian de bǐ yòubian de hǎokàn.","Tôi cũng thấy cái bên trái đẹp hơn cái bên phải."],["王一雪","你看看要多少钱！","Nǐ kànkan yào duōshao qián!","Bạn xem giá bao nhiêu tiền!"],["刘明","真不便宜！八千八！","Zhēn bù piányi! Bā qiān bā!","Thật không rẻ chút nào! Tám nghìn tám trăm tệ!"]],"sides":{"刘明":"R","王一雪":"L"}},{"context":"Ngoài rạp chiếu phim, Vương Nhất Tuyết và Lưu Minh đang trò chuyện.","contextZh":"在电影院外面，王一雪和刘明在聊天儿。","label":"8-2 · Chọn phim để xem","lines":[["刘明","今天有不少电影，我们看个电影吧。","Jīntiān yǒu bùshǎo diànyǐng, wǒmen kàn ge diànyǐng ba.","Hôm nay có không ít phim, chúng ta đi xem một bộ phim nhé."],["王一雪","好啊！我们看哪个？","Hǎo a! Wǒmen kàn nǎge?","Hay đấy! Chúng ta xem bộ nào?"],["刘明","我记得你喜欢看爱情片，我们看那个爱情片，怎么样？","Wǒ jìde nǐ xǐhuan kàn àiqíngpiàn, wǒmen kàn nàge àiqíngpiàn, zěnmeyàng?","Tôi nhớ bạn thích xem phim tình cảm, chúng ta xem bộ phim tình cảm kia nhé, thế nào?"],["王一雪","还是看这个吧，我看网上说这个电影比那个爱情片更有意思。","Háishi kàn zhège ba, wǒ kàn wǎngshang shuō zhège diànyǐng bǐ nàge àiqíngpiàn gèng yǒu yìsi.","Hay là xem bộ này đi, tôi đọc trên mạng nói bộ phim này thú vị hơn bộ phim tình cảm kia."],["刘明","好。我去买票。","Hǎo. Wǒ qù mǎi piào.","Được. Tôi đi mua vé."],["王一雪","到网上买吧，网上买比在这里买便宜。","Dào wǎngshang mǎi ba, wǎngshang mǎi bǐ zài zhèlǐ mǎi piányi.","Mua trên mạng đi, mua trên mạng rẻ hơn mua ở đây."]],"sides":{"刘明":"L","王一雪":"R"}},{"context":"Ở nhà hàng, Vương Nhất Tuyết và Lưu Minh đang gọi món.","contextZh":"在饭馆，王一雪和刘明在点菜。","label":"8-3 · Sinh nhật bất ngờ","lines":[["刘明","您好！就要这几个菜吧，谢谢！","Nínhǎo! Jiù yào zhè jǐ ge cài ba, xièxie!","Xin chào! Chúng tôi lấy mấy món này, cảm ơn!"],["王一雪","怎么点这么多菜？","Zěnme diǎn zhème duō cài?","Sao lại gọi nhiều món thế?"],["刘明","你想想，今天是几月几号？","Nǐ xiǎngxiang, jīntiān shì jǐ yuè jǐ hào?","Bạn nghĩ xem, hôm nay là ngày mấy tháng mấy?"],["王一雪","8月27号。啊！我的生日！","Bā yuè èrshíqī hào. À! Wǒ de shēngrì!","Ngày 27 tháng 8. À! Sinh nhật của tôi!"],["刘明","生日快乐！虽然你忘了，但是我记得。看看这是什么？","Shēngrì kuàilè! Suīrán nǐ wàng le, dànshì wǒ jìde. Kànkan zhè shì shénme?","Chúc mừng sinh nhật! Tuy bạn quên mất, nhưng tôi vẫn nhớ. Xem đây là cái gì nào?"],["王一雪","手表！吃饭、看电影、买手表，今天花了不少钱吧？","Shǒubiǎo! Chī fàn, kàn diànyǐng, mǎi shǒubiǎo, jīntiān huā le bùshǎo qián ba?","Đồng hồ! Ăn cơm, xem phim, mua đồng hồ, hôm nay tiêu không ít tiền nhỉ?"],["刘明","虽然花了一些钱，但是我们过了一个快乐的生日。","Suīrán huā le yìxiē qián, dànshì wǒmen guò le yí ge kuàilè de shēngrì.","Tuy tiêu tốn một ít tiền, nhưng chúng tôi đã có một sinh nhật vui vẻ."]],"sides":{"刘明":"L","王一雪":"R"}},{"context":"Tiểu Ngữ đang kể câu chuyện trong ngày của Vương Nhất Tuyết và Lưu Minh.","contextZh":"小语在讲述王一雪和刘明的一天。","label":"8-4 · Tiểu Ngữ kể lại câu chuyện","lines":[["小语","虽然妻子忘了今天是自己的生日，但是丈夫记得。","Suīrán qīzi wàng le jīntiān shì zìjǐ de shēngrì, dànshì zhàngfu jìde.","Tuy người vợ quên mất hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ."],["小语","丈夫请妻子去饭馆吃饭、去电影院看电影，还给妻子买了一块非常漂亮的手表。","Zhàngfu qǐng qīzi qù fànguǎn chī fàn, qù diànyǐngyuàn kàn diànyǐng, hái gěi qīzi mǎi le yí kuài fēicháng piàoliang de shǒubiǎo.","Người chồng mời vợ đi ăn ở nhà hàng, đi xem phim ở rạp chiếu phim, còn mua tặng vợ một chiếc đồng hồ rất đẹp."],["小语","妻子觉得今天很快乐。","Qīzi juéde jīntiān hěn kuàilè.","Người vợ cảm thấy hôm nay rất vui."]],"sides":{"小语":"C"}}],"9":[{"context":"Ở cửa hàng, Vương Nhất Tuyết và Lưu Minh đang xem quần.","contextZh":"在商店，王一雪和刘明在看裤子。","label":"9-1 · Mua quần cho con trai","lines":[["王一雪","儿子的裤子坏了，我们给他买条新的吧。","Érzi de kùzi huài le, wǒmen gěi tā mǎi tiáo xīn de ba.","Quần của con trai bị rách rồi, chúng ta mua cho con một cái mới nhé."],["刘明","好啊。","Hǎo a.","Được đấy."],["王一雪","你看这条黑色的怎么样？","Nǐ kàn zhè tiáo hēisè de zěnmeyàng?","Bạn xem chiếc quần đen này thế nào?"],["刘明","没有你上次买的那条好看。","Méiyǒu nǐ shàngcì mǎi de nà tiáo hǎokàn.","Không đẹp bằng chiếc quần bạn mua lần trước."],["王一雪","旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","Pángbiān nàge nánháir jiù chuān le zhèyàng de kùzi, wǒ juéde hěn hǎokàn a!","Cậu bé bên cạnh đang mặc chiếc quần như thế này, tôi thấy đẹp lắm!"],["刘明","儿子的个子没有他那么高，穿上就不会太好看。","Érzi de gèzi méiyǒu tā nàme gāo, chuānshang jiù bú huì tài hǎokàn.","Con trai tôi không cao bằng cậu ấy, mặc vào sẽ không đẹp lắm."],["王一雪","好吧，我们再去那边看看。","Hǎo ba, wǒmen zài qù nàbiān kànkan.","Được thôi, chúng ta sang chỗ khác xem tiếp."]],"sides":{"刘明":"R","王一雪":"L"}},{"context":"Ở cửa cửa hàng, Vương Nhất Tuyết và Lưu Minh đang đi ra ngoài.","contextZh":"在商店门口，王一雪和刘明往外走。","label":"9-2 · Trà sữa hay cà phê","lines":[["王一雪","门口有家奶茶店。你想喝杯奶茶吗？","Ménkǒu yǒu jiā nǎichádiàn. Nǐ xiǎng hē bēi nǎichá ma?","Ở cửa có một quán trà sữa. Bạn có muốn uống một cốc trà sữa không?"],["刘明","我想喝咖啡，还是去咖啡店吧。","Wǒ xiǎng hē kāfēi, háishi qù kāfēidiàn ba.","Tôi muốn uống cà phê, hay là đến quán cà phê đi."],["王一雪","咖啡店离这儿有点儿远。","Kāfēidiàn lí zhèr yǒudiǎnr yuǎn.","Quán cà phê cách đây hơi xa."],["刘明","没关系，那家店的咖啡很好喝。","Méi guānxi, nà jiā diàn de kāfēi hěn hǎohē.","Không sao, cà phê ở quán đó rất ngon."],["王一雪","那你等一下，我去买杯奶茶。","Nà nǐ děng yíxià, wǒ qù mǎi bēi nǎichá.","Vậy bạn đợi một lát, tôi đi mua một cốc trà sữa."],["刘明","你不想喝咖啡吗？","Nǐ bù xiǎng hē kāfēi ma?","Bạn không muốn uống cà phê à?"],["王一雪","喝了咖啡，晚上就别想睡觉了。","Hē le kāfēi, wǎnshang jiù bié xiǎng shuìjiào le.","Uống cà phê rồi, tối sẽ không ngủ được đâu."]],"sides":{"刘明":"R","王一雪":"L"}},{"context":"Ở cửa quán cà phê, Vương Nhất Tuyết và Lưu Minh đang trò chuyện.","contextZh":"在咖啡店门口，王一雪和刘明在聊天儿。","label":"9-3 · Đi bộ về nhà","lines":[["刘明","我们打车回去吧。","Wǒmen dǎchē huíqù ba.","Chúng ta bắt taxi về nhà đi."],["王一雪","这里离家很近，还是走路吧。","Zhèlǐ lí jiā hěn jìn, háishi zǒulù ba.","Ở đây cách nhà rất gần, hay là đi bộ đi."],["刘明","要走多长时间？","Yào zǒu duō cháng shíjiān?","Đi bộ mất bao lâu?"],["王一雪","走半个多小时就到了。","Zǒu bàn ge duō xiǎoshí jiù dào le.","Đi bộ hơn nửa tiếng là đến."],["刘明","好的。每天上下班都坐车，今天运动运动吧。","Hǎo de. Měitiān shàng xiàbān dōu zuò chē, jīntiān yùndòng yùndòng ba.","Được. Ngày nào đi làm anh cũng ngồi xe, hôm nay vận động một chút đi."]],"sides":{"刘明":"L","王一雪":"R"}},{"context":"Trong phòng, Vương Nhất Tuyết đang viết nhật ký.","contextZh":"在房间，王一雪在写日记。","label":"9-4 · Nhật ký của Vương Nhất Tuyết","lines":[["王一雪","这周刘明休息，我下班后跟他去了一家商店。","Zhè zhōu Liú Míng xiūxi, wǒ xiàbān hòu gēn tā qù le yì jiā shāngdiàn.","Tuần này Lưu Minh được nghỉ, sau khi tan làm tôi cùng anh đi đến một cửa hàng."],["王一雪","商店里边的衣服没有大商场里边的好看。","Shāngdiàn lǐbiān de yīfu méiyǒu dà shāngchǎng lǐbiān de hǎokàn.","Quần áo trong cửa hàng không đẹp bằng quần áo trong trung tâm thương mại lớn."],["王一雪","我们没有买到喜欢的衣服，从商店出来就到咖啡店坐了坐。","Wǒmen méiyǒu mǎidào xǐhuan de yīfu, cóng shāngdiàn chūlái jiù dào kāfēidiàn zuò le zuò.","Chúng tôi không mua được bộ quần áo nào mình thích, ra khỏi cửa hàng liền đến quán cà phê ngồi một lát."],["王一雪","因为想运动运动，所以喝完东西，我们就走回家了。","Yīnwèi xiǎng yùndòng yùndòng, suǒyǐ hēwán dōngxi, wǒmen jiù zǒuhuí jiā le.","Vì muốn vận động nên sau khi uống xong, chúng tôi đi bộ về nhà."]],"sides":{"王一雪":"C"}}],"10":[{"context":"Trong phòng, Lưu Minh đang giúp Lưu Tiểu Minh chuẩn bị đồ dùng.","contextZh":"在房间，刘明在帮刘小明准备东西。","label":"10-1 · Chuẩn bị đồ dùng học tập","lines":[["刘明","小明，你们明天开学，你准备好了吗？","Xiǎomíng, nǐmen míngtiān kāixué, nǐ zhǔnbèi hǎo le ma?","Tiểu Minh, ngày mai các con khai giảng, con đã chuẩn bị xong chưa?"],["刘小明","明天就开学啊？爸爸，我的书包你看见了吗？","Míngtiān jiù kāixué a? Bàba, wǒ de shūbāo nǐ kànjiàn le ma?","Ngày mai đã khai giảng rồi sao? Bố ơi, cặp sách của con bố có nhìn thấy không?"],["刘明","书包在门后面。","Shūbāo zài mén hòumiàn.","Cặp sách ở sau cửa."],["刘小明","书在哪儿呢？笔呢？","Shū zài nǎr ne? Bǐ ne?","Sách ở đâu? Bút đâu?"],["刘明","书在床上，笔在桌子上。","Shū zài chuáng shang, bǐ zài zhuōzi shang.","Sách ở trên giường, bút ở trên bàn."],["刘小明","太好了！现在都准备好了。","Tài hǎo le! Xiànzài dōu zhǔnbèi hǎo le.","Tốt quá! Bây giờ đều đã chuẩn bị xong rồi."],["刘明","这次爸爸帮你，下次你自己准备，好不好？","Zhè cì bàba bāng nǐ, xià cì nǐ zìjǐ zhǔnbèi, hǎo bu hǎo?","Lần này bố giúp con, lần sau con tự chuẩn bị, được không?"],["刘小明","好！","Hǎo!","Được ạ!"]],"sides":{"刘小明":"R","刘明":"L"}},{"context":"Trong phòng, Vương Nhất Tuyết và Lưu Tiểu Tuyết đang nói chuyện học tập.","contextZh":"在房间，王一雪和刘小雪在聊学习。","label":"10-2 · Ôn bài trước kỳ thi","lines":[["王一雪","小雪，你在做什么呢？","Xiǎoxuě, nǐ zài zuò shénme ne?","Tiểu Tuyết, con đang làm gì đấy?"],["刘小雪","明天考试，我在看书呢。","Míngtiān kǎoshì, wǒ zài kàn shū ne.","Ngày mai thi, con đang đọc sách đây."],["王一雪","这些词要好好看看。","Zhèxiē cí yào hǎohǎo kànkan.","Những từ này phải xem lại thật kỹ."],["刘小雪","我看过了，意思也都懂了。","Wǒ kànguo le, yìsi yě dōu dǒng le.","Con đã xem qua rồi, nghĩa cũng hiểu hết."],["王一雪","你的本子呢？本子上做错的题也要看一看。","Nǐ de běnzi ne? Běnzi shang zuòcuò de tí yě yào kàn yí kàn.","Vở của con đâu? Những bài làm sai trong vở cũng phải xem lại."],["刘小雪","妈妈，是您准备考试还是我准备考试？","Māma, shì nín zhǔnbèi kǎoshì háishi wǒ zhǔnbèi kǎoshì?","Mẹ ơi, là mẹ chuẩn bị thi hay là con chuẩn bị thi?"]],"sides":{"刘小雪":"R","王一雪":"L"}},{"context":"Ở phòng khách, Vương Nhất Tuyết và các con đang trò chuyện.","contextZh":"在客厅，王一雪和孩子们在聊天儿。","label":"10-3 · Thi xong về nhà","lines":[["刘小雪","妈妈，我回来了！","Māma, wǒ huílái le!","Mẹ ơi, con về rồi!"],["王一雪","我买了奶茶，就在桌子上，自己去拿吧。","Wǒ mǎi le nǎichá, jiù zài zhuōzi shang, zìjǐ qù ná ba.","Mẹ đã mua trà sữa, để ngay trên bàn, con tự đi lấy đi."],["刘小雪","谢谢妈妈！","Xièxie māma!","Cảm ơn mẹ!"],["王一雪","今天考试考得怎么样？","Jīntiān kǎoshì kǎo de zěnmeyàng?","Hôm nay thi thế nào?"],["刘小雪","我觉得比上次好。","Wǒ juéde bǐ shàngcì hǎo.","Con thấy làm tốt hơn lần trước."],["王一雪","真不错！饭菜快要做好了，你叫弟弟一起去洗手吧。","Zhēn búcuò! Fàncài kuàiyào zuòhǎo le, nǐ jiào dìdi yìqǐ qù xǐshǒu ba.","Giỏi thật! Cơm sắp nấu xong rồi, con gọi em trai cùng đi rửa tay đi."],["刘小明","妈妈，我是第一名，姐姐还没洗完呢。","Māma, wǒ shì dì-yī míng, jiějie hái méi xǐwán ne.","Mẹ ơi, con rửa xong đầu tiên, chị gái còn chưa rửa xong."],["王一雪","你洗得真快啊！","Nǐ xǐ de zhēn kuài a!","Con rửa tay nhanh thật đấy!"]],"sides":{"刘小明":"L","刘小雪":"L","王一雪":"R"}},{"context":"Trong phòng, Lưu Tiểu Tuyết đang viết nhật ký.","contextZh":"在房间，刘小雪在写日记。","label":"10-4 · Nhật ký của Lưu Tiểu Tuyết","lines":[["刘小雪","快要开学了，爸爸帮弟弟准备书包、本子和笔。","Kuàiyào kāixué le, bàba bāng dìdi zhǔnbèi shūbāo, běnzi hé bǐ.","Sắp khai giảng rồi, bố giúp em trai chuẩn bị cặp sách, vở và bút."],["刘小雪","我就要考试了，妈妈让我看书、看做错的题。","Wǒ jiù yào kǎoshì le, māma ràng wǒ kàn shū, kàn zuòcuò de tí.","Tôi sắp thi rồi, mẹ bảo tôi đọc sách và xem lại những bài làm sai."],["刘小雪","我们上学，爸爸、妈妈比我们还忙。","Wǒmen shàngxué, bàba, māma bǐ wǒmen hái máng.","Chúng tôi đi học, bố mẹ còn bận hơn cả chúng tôi."],["刘小雪","我问他们：“是我和弟弟上学还是你们上学？”","Wǒ wèn tāmen: \"Shì wǒ hé dìdi shàngxué háishi nǐmen shàngxué?\"","Tôi hỏi họ: là tôi và em trai đi học hay là bố mẹ đi học?"],["刘小雪","我问完，他们都笑了。","Wǒ wènwán, tāmen dōu xiào le.","Tôi hỏi xong, họ đều cười."]],"sides":{"刘小雪":"C"}}],"11":[{"context":"Trong lớp học, Vương Nhất Phi và Bạch Gia Nguyệt đang trò chuyện.","contextZh":"在教室，王一飞和白家月在聊天儿。","label":"11-1 · Đau đầu ở lớp","lines":[["王一飞","家月，都下课了，你怎么还不回家？","Jiāyuè, dōu xiàkè le, nǐ zěnme hái bù huí jiā?","Gia Nguyệt, đã tan học rồi, sao bạn còn chưa về nhà?"],["白家月","我头疼，不太舒服。","Wǒ tóu téng, bú tài shūfu.","Tôi đau đầu, không được khỏe lắm."],["王一飞","你这几天经常头疼，去医院看看吧。","Nǐ zhè jǐ tiān jīngcháng tóu téng, qù yīyuàn kànkan ba.","Mấy hôm nay bạn thường xuyên đau đầu, đi bệnh viện khám thử xem."],["白家月","我想休息一下，现在不能动，一动就疼。","Wǒ xiǎng xiūxi yíxià, xiànzài bù néng dòng, yí dòng jiù téng.","Tôi muốn nghỉ một lát, bây giờ không cử động được, cứ động là đau."],["王一飞","那你在这儿坐着，我去开车，一会儿送你去医院。","Nà nǐ zài zhèr zuòzhe, wǒ qù kāichē, yíhuìr sòng nǐ qù yīyuàn.","Vậy bạn cứ ngồi ở đây, tôi đi lấy xe, lát nữa đưa bạn đi bệnh viện."],["白家月","谢谢王老师。","Xièxie Wáng lǎoshī.","Cảm ơn cô Vương."]],"sides":{"王一飞":"L","白家月":"R"}},{"context":"Trong xe của Vương Nhất Phi, Vương Nhất Phi và Bạch Gia Nguyệt đang trò chuyện, Lý Văn gọi điện thoại đến.","contextZh":"在王一飞车里，王一飞和白家月在聊天儿，李文打来一个电话。","label":"11-2 · Trên xe đi bệnh viện","lines":[["王一飞","现在路上车多，还下着雪，我开慢一点儿。","Xiànzài lùshang chē duō, hái xiàzhe xuě, wǒ kāi màn yìdiǎnr.","Bây giờ trên đường nhiều xe, lại còn đang có tuyết, tôi lái chậm lại một chút."],["白家月","没问题，现在头没那么疼了。","Méi wèntí, xiànzài tóu méi nàme téng le.","Không sao, bây giờ đầu không đau như thế nữa rồi."],["王一飞","好。李文来电话了，你帮我接一下。","Hǎo. Lǐ Wén lái diànhuà le, nǐ bāng wǒ jiē yíxià.","Được. Lý Văn gọi điện thoại đến, bạn giúp tôi nghe máy nhé."],["白家月","喂，李文，王老师开着车呢，你找她有事吗？","Wèi, Lǐ Wén, Wáng lǎoshī kāizhe chē ne, nǐ zhǎo tā yǒu shì ma?","A lô, Lý Văn, cô Vương đang lái xe, bạn tìm cô có việc gì không?"],["李文","没什么事。今天雪这么大，你们开车去哪儿啊？","Méi shénme shì. Jīntiān xuě zhème dà, nǐmen kāichē qù nǎr a?","Không có việc gì. Hôm nay tuyết lớn thế, các bạn lái xe đi đâu vậy?"],["白家月","去医院，我头有点儿疼。","Qù yīyuàn, wǒ tóu yǒudiǎnr téng.","Đi bệnh viện, tôi hơi đau đầu."],["李文","那我一会儿去看看你。","Nà wǒ yíhuìr qù kànkan nǐ.","Vậy lát nữa tôi đến thăm bạn."]],"sides":{"李文":"L","王一飞":"L","白家月":"R"}},{"context":"Trong phòng, Lý Văn đến thăm Bạch Gia Nguyệt.","contextZh":"在房间，李文来看望白家月。","label":"11-3 · Thăm bệnh ở nhà","lines":[["白家月","李文，快请进！","Lǐ Wén, kuài qǐng jìn!","Lý Văn, mau vào đi!"],["李文","家月，你怎么样了？头还疼吗？","Jiāyuè, nǐ zěnmeyàng le? Tóu hái téng ma?","Gia Nguyệt, bạn thế nào rồi? Đầu còn đau không?"],["白家月","不那么疼了。医生开了一些药，吃完就好多了。","Bú nàme téng le. Yīshēng kāi le yìxiē yào, chīwán jiù hǎoduō le.","Không đau như thế nữa rồi. Bác sĩ kê một ít thuốc, uống xong sẽ đỡ nhiều."],["李文","那就好！","Nà jiù hǎo!","Vậy thì tốt rồi!"],["王一飞","家月，你想不想吃点儿东西？","Jiāyuè, nǐ xiǎng bu xiǎng chī diǎnr dōngxi?","Gia Nguyệt, bạn có muốn ăn chút gì không?"],["李文","吃点儿吧，身体不舒服时更要好好吃饭。","Chī diǎnr ba, shēntǐ bù shūfu shí gèng yào hǎohāo chī fàn.","Ăn chút đi, khi cơ thể không khỏe càng phải ăn uống cho tốt."],["白家月","吃点儿什么呢？","Chī diǎnr shénme ne?","Ăn chút gì đây?"],["王一飞","你最喜欢吃中国菜，我做几个中国菜吧。","Nǐ zuì xǐhuan chī Zhōngguó cài, wǒ zuò jǐ ge Zhōngguó cài ba.","Bạn thích ăn món Trung Quốc nhất, tôi làm vài món Trung Quốc nhé."],["白家月","好的，谢谢王老师。","Hǎo de, xièxie Wáng lǎoshī.","Được ạ, cảm ơn cô Vương."]],"sides":{"李文":"R","王一飞":"L","白家月":"L"}},{"context":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký.","contextZh":"在房间，白家月在写日记。","label":"11-4 · Nhật ký của Gia Nguyệt","lines":[["白家月","我这几天经常头疼，从药店买了点儿药，没去医院。","Wǒ zhè jǐ tiān jīngcháng tóu téng, cóng yàodiàn mǎi le diǎnr yào, méi qù yīyuàn.","Mấy hôm nay tôi thường xuyên đau đầu, mua một ít thuốc ở hiệu thuốc, không đi bệnh viện."],["白家月","今天下课后，王老师看我不舒服，就送我去医院了。","Jīntiān xiàkè hòu, Wáng lǎoshī kàn wǒ bù shūfu, jiù sòng wǒ qù yīyuàn le.","Hôm nay sau khi tan học, cô Vương thấy tôi không khỏe nên đưa tôi đi bệnh viện."],["白家月","从医院回来，李文也来看我了。","Cóng yīyuàn huílái, Lǐ Wén yě lái kàn wǒ le.","Từ bệnh viện về, Lý Văn cũng đến thăm tôi."],["白家月","现在他们都回去了，我也要睡觉了。","Xiànzài tāmen dōu huíqù le, wǒ yě yào shuìjiào le.","Bây giờ họ đều đã về rồi, tôi cũng phải đi ngủ đây."]],"sides":{"白家月":"C"}}],"12":[{"context":"Trong phòng, Vương Nhất Tuyết nhận được điện thoại của Bạch Gia Nguyệt.","contextZh":"在房间，王一雪接到白家月的电话。","label":"12-1 · Gọi điện hỏi thời tiết","lines":[["王一雪","喂，家月，是你啊！有什么事情吗？","Wèi, Jiāyuè, shì nǐ a! Yǒu shénme shìqing ma?","A lô, Gia Nguyệt, là bạn à! Có việc gì không?"],["白家月","没什么事，就想跟您说说话。","Méi shénme shì, jiù xiǎng gēn nín shuōshuo huà.","Không có việc gì, chỉ muốn nói chuyện với cô thôi."],["王一雪","好啊。你今天没课吗？","Hǎo a. Nǐ jīntiān méi kè ma?","Được chứ. Hôm nay bạn không có tiết học à?"],["白家月","下午有课。您那里天气怎么样？","Xiàwǔ yǒu kè. Nín nàlǐ tiānqì zěnmeyàng?","Buổi chiều có tiết. Chỗ cô thời tiết thế nào ạ?"],["王一雪","北京这几天虽然是晴天，但是有点儿冷。","Běijīng zhè jǐ tiān suīrán shì qíng tiān, dànshì yǒudiǎnr lěng.","Mấy hôm nay Bắc Kinh tuy trời nắng nhưng hơi lạnh."],["白家月","我这里比北京冷多了，外边还正下着雪呢！","Wǒ zhèlǐ bǐ Běijīng lěngduō le, wàibian hái zhèng xiàzhe xuě ne!","Chỗ tôi lạnh hơn Bắc Kinh nhiều, bên ngoài vẫn đang có tuyết rơi đấy!"]],"sides":{"王一雪":"L","白家月":"R"}},{"context":"Trong phòng khách, Vương Nhất Tuyết gọi điện thoại cho Vương Nhất Phi.","contextZh":"在客厅，王一雪给王一飞打电话。","label":"12-2 · Dặn dò qua điện thoại","lines":[["王一雪","喂，一飞，听家月说你那边下雪了，下得大不大？","Wèi, Yīfēi, tīng Jiāyuè shuō nǐ nàbian xià xuě le, xià de dà bu dà?","A lô, Nhất Phi, nghe Gia Nguyệt nói chỗ bạn có tuyết, tuyết rơi lớn không?"],["王一飞","今天不大，昨天比今天下得大。","Jīntiān bú dà, zuótiān bǐ jīntiān xià de dà.","Hôm nay không lớn, hôm qua tuyết rơi lớn hơn hôm nay."],["王一雪","天气不好，你去外面的时候多穿点儿衣服。","Tiānqì bù hǎo, nǐ qù wàimian de shíhou duō chuān diǎnr yīfu.","Thời tiết không tốt, khi ra ngoài bạn mặc thêm áo nhé."],["王一飞","这几天我在网上上课，没出去过。","Zhè jǐ tiān wǒ zài wǎngshang shàngkè, méi chūqù guo.","Mấy hôm nay tôi học online, chưa ra ngoài lần nào."],["王一雪","那就好，有事记得给我打电话。","Nà jiù hǎo, yǒu shì jìde gěi wǒ dǎ diànhuà.","Vậy thì tốt, có việc gì nhớ gọi điện cho tôi nhé."],["王一飞","好的。现在不下雪了，我出去买点儿吃的。","Hǎo de. Xiànzài bú xià xuě le, wǒ chūqù mǎi diǎnr chī de.","Được ạ. Bây giờ hết tuyết rồi, tôi ra ngoài mua chút đồ ăn."],["王一雪","一次多买点儿，阴天下雪什么的就少出去吧。","Yí cì duō mǎi diǎnr, yīn tiān xià xuě shénmede jiù shǎo chūqù ba.","Một lần mua nhiều chút, trời âm u hay có tuyết thì ít ra ngoài thôi."]],"sides":{"王一雪":"L","王一飞":"R"}},{"context":"Trong phòng, Lý Văn gọi điện thoại cho Bạch Gia Nguyệt.","contextZh":"在房间，李文给白家月打电话。","label":"12-3 · Rủ nhau đi chạy bộ","lines":[["李文","喂，家月，今天天气不错，我们去跑步吧！","Wèi, Jiāyuè, jīntiān tiānqì búcuò, wǒmen qù pǎobù ba!","A lô, Gia Nguyệt, hôm nay thời tiết đẹp, chúng ta đi chạy bộ nhé!"],["白家月","你跑步跑得比我快，我们能一起跑吗？","Nǐ pǎobù pǎo de bǐ wǒ kuài, wǒmen néng yìqǐ pǎo ma?","Bạn chạy bộ nhanh hơn tôi, chúng ta có thể chạy cùng nhau không?"],["李文","可以的，我慢慢跑，等着你。","Kěyǐ de, wǒ mànmàn pǎo, děngzhe nǐ.","Được mà, tôi chạy chậm thôi, đợi bạn."],["白家月","好吧。你真爱跑步啊！","Hǎo ba. Nǐ zhēn ài pǎobù a!","Được thôi. Bạn thật thích chạy bộ!"],["李文","我从小就经常跟爸爸跑步，跑步能让人快乐！","Wǒ cóngxiǎo jiù jīngcháng gēn bàba pǎobù, pǎobù néng ràng rén kuàilè!","Tôi từ nhỏ đã thường xuyên chạy bộ cùng bố, chạy bộ làm người ta vui vẻ!"],["白家月","好，那我准备一下。","Hǎo, nà wǒ zhǔnbèi yíxià.","Được, vậy tôi chuẩn bị một lát."],["李文","我现在坐地铁去找你，一会儿楼下见。","Wǒ xiànzài zuò dìtiě qù zhǎo nǐ, yíhuìr lóu xià jiàn.","Bây giờ tôi đi tàu điện ngầm đến tìm bạn, lát nữa gặp nhau dưới lầu nhé."]],"sides":{"李文":"L","白家月":"R"}},{"context":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký.","contextZh":"在房间，白家月在写日记。","label":"12-4 · Nhật ký của Gia Nguyệt","lines":[["白家月","前几天天气不好，我没走路，每天坐两站地铁去学校。","Qián jǐ tiān tiānqì bù hǎo, wǒ méi zǒulù, měi tiān zuò liǎng zhàn dìtiě qù xuéxiào.","Mấy hôm trước thời tiết không tốt, tôi không đi bộ, mỗi ngày đi hai trạm tàu điện ngầm đến trường."],["白家月","今天是个大晴天，李文让我跟他去外面跑步。","Jīntiān shì ge dà qíng tiān, Lǐ Wén ràng wǒ gēn tā qù wàimian pǎobù.","Hôm nay là một ngày nắng to, Lý Văn rủ tôi ra ngoài chạy bộ cùng anh ấy."],["白家月","他小时候经常跑步，跑得比我快，但是他会等我。","Tā xiǎoshíhou jīngcháng pǎobù, pǎo de bǐ wǒ kuài, dànshì tā huì děng wǒ.","Hồi nhỏ anh ấy thường xuyên chạy bộ, chạy nhanh hơn tôi, nhưng anh ấy sẽ đợi tôi."],["白家月","跟李文一起跑步，我好高兴啊！","Gēn Lǐ Wén yìqǐ pǎobù, wǒ hǎo gāoxìng a!","Chạy bộ cùng Lý Văn, tôi vui lắm!"]],"sides":{"白家月":"C"}}],"13":[{"context":"Trong lớp học, Bạch Gia Nguyệt và Trần Thiên Trung đang trò chuyện.","contextZh":"在教室，白家月和陈天中在聊天儿。","label":"13-1 · Chuẩn bị quà năm mới","lines":[["白家月","时间过得真快啊！新年就要到了。","Shíjiān guò de zhēn kuài a! Xīnnián jiù yào dào le.","Thời gian trôi nhanh thật! Năm mới sắp đến rồi."],["陈天中","这一年王老师教我们中文，每天工作都很累。","Zhè yì nián Wáng lǎoshī jiāo wǒmen Zhōngwén, měi tiān gōngzuò dōu hěn lèi.","Năm nay cô Vương dạy chúng tôi tiếng Trung, mỗi ngày làm việc đều rất mệt."],["白家月","是啊，她教得很好。因为她，我们都非常爱上中文课。","Shì a, tā jiāo de hěn hǎo. Yīnwèi tā, wǒmen dōu fēicháng ài shàng Zhōngwén kè.","Đúng vậy, cô dạy rất hay. Nhờ có cô, chúng tôi đều rất yêu thích giờ học tiếng Trung."],["陈天中","我们给她准备个新年礼物吧。你觉得送给她什么好呢？","Wǒmen gěi tā zhǔnbèi ge xīnnián lǐwù ba. Nǐ juéde sòng gěi tā shénme hǎo ne?","Chúng ta chuẩn bị cho cô một món quà năm mới nhé. Bạn thấy tặng cô cái gì thì tốt?"],["白家月","王老师喜欢花，就送给她花吧。","Wáng lǎoshī xǐhuan huā, jiù sòng gěi tā huā ba.","Cô Vương thích hoa, tặng hoa cho cô nhé."],["陈天中","那我们去花店看看，现在买花的人多，希望花店还有漂亮的花。","Nà wǒmen qù huādiàn kànkan, xiànzài mǎi huā de rén duō, xīwàng huādiàn hái yǒu piàoliang de huā.","Vậy chúng ta đến tiệm hoa xem thử, bây giờ nhiều người mua hoa, mong là tiệm hoa vẫn còn hoa đẹp."]],"sides":{"白家月":"L","陈天中":"R"}},{"context":"Trong lớp học, Vương Nhất Phi đang dạy học.","contextZh":"在教室，王一飞在上课。","label":"13-2 · Cô giáo chữa chữ sai","lines":[["白家月","王老师，今天的词比昨天多了十个。","Wáng lǎoshī, jīntiān de cí bǐ zuótiān duō le shí ge.","Cô Vương ơi, từ hôm nay nhiều hơn hôm qua mười từ."],["王一飞","是啊！你们都学会了吗？","Shì a! Nǐmen dōu xuéhuì le ma?","Đúng vậy! Các bạn đều học thuộc chưa?"],["安妮","学会了，没有问题。","Xuéhuì le, méiyǒu wèntí.","Học thuộc rồi ạ, không có vấn đề gì."],["王一飞","好。现在我来说，你们在本子上面写。","Hǎo. Xiànzài wǒ lái shuō, nǐmen zài běnzi shàngmian xiě.","Tốt. Bây giờ tôi đọc, các bạn viết lên vở nhé."],["王一飞","同学们，“洗手间”的“间”字写错了，它的里面是“日”，不是“口”。","Tóngxuémen, \"xǐshǒujiān\" de \"jiān\" zì xiěcuò le, tā de lǐmian shì \"rì\", bú shì \"kǒu\".","Các bạn ơi, chữ 间 trong từ nhà vệ sinh viết sai rồi, bên trong của nó là chữ 日, không phải chữ 口."],["白家月","“日”比“口”多一笔，写“口”就是“问题”的“问”了。","\"Rì\" bǐ \"kǒu\" duō yì bǐ, xiě \"kǒu\" jiùshi \"wèntí\" de \"wèn\" le.","Chữ 日 nhiều hơn chữ 口 một nét, viết chữ 口 thì thành chữ 问 trong từ vấn đề rồi."],["王一飞","没错，你说得很对。","Méi cuò, nǐ shuō de hěn duì.","Đúng rồi, bạn nói rất đúng."]],"sides":{"安妮":"L","王一飞":"R","白家月":"L"}},{"context":"Trong lớp học, An Ni và Bạch Gia Nguyệt đang trò chuyện.","contextZh":"在教室，安妮和白家月在聊天儿。","label":"13-3 · Tặng nhau quà năm mới","lines":[["安妮","家月，你觉得这个本子怎么样？","Jiāyuè, nǐ juéde zhège běnzi zěnmeyàng?","Gia Nguyệt, bạn thấy quyển vở này thế nào?"],["白家月","很漂亮，多少钱一个？","Hěn piàoliang, duōshao qián yí ge?","Rất đẹp, bao nhiêu tiền một quyển?"],["安妮","比我们一起买的那个本子贵一点儿。","Bǐ wǒmen yìqǐ mǎi de nà ge běnzi guì yìdiǎnr.","Đắt hơn quyển vở chúng ta cùng mua một chút."],["白家月","这么漂亮的本子，不可能贵一点儿吧？","Zhème piàoliang de běnzi, bù kěnéng guì yìdiǎnr ba?","Quyển vở đẹp thế này, không thể chỉ đắt hơn một chút chứ?"],["安妮","我是上网买的，真没那么贵。我买了两个，送你一个。","Wǒ shì shàngwǎng mǎi de, zhēn méi nàme guì. Wǒ mǎi le liǎng ge, sòng nǐ yí ge.","Tôi mua trên mạng, thật sự không đắt như thế đâu. Tôi mua hai quyển, tặng bạn một quyển."],["白家月","谢谢！那我送给你什么呢？","Xièxie! Nà wǒ sòng gěi nǐ shénme ne?","Cảm ơn! Vậy tôi tặng bạn cái gì đây?"],["安妮","咖啡杯吧，我最喜欢喝咖啡了。","Kāfēibēi ba, wǒ zuì xǐhuan hē kāfēi le.","Cốc cà phê nhé, tôi thích uống cà phê nhất."],["白家月","好，那样我们就都有新年礼物了！","Hǎo, nà yàng wǒmen jiù dōu yǒu xīnnián lǐwù le!","Được, như vậy chúng ta đều có quà năm mới rồi!"]],"sides":{"安妮":"L","白家月":"R"}},{"context":"Trong phòng, Bạch Gia Nguyệt đang viết nhật ký.","contextZh":"在房间，白家月在写日记。","label":"13-4 · Nhật ký của Gia Nguyệt","lines":[["白家月","新年就要到了，安妮送给我一个新本子。","Xīnnián jiù yào dào le, Ānnī sòng gěi wǒ yí ge xīn běnzi.","Năm mới sắp đến rồi, An Ni tặng tôi một quyển vở mới."],["白家月","她告诉我是在网上买的，比我的本子贵一点儿。","Tā gàosu wǒ shì zài wǎngshang mǎi de, bǐ wǒ de běnzi guì yìdiǎnr.","Cô ấy nói với tôi là mua trên mạng, đắt hơn quyển vở của tôi một chút."],["白家月","我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。","Wǒmen bān tóngxué yě sòng le Wáng lǎoshī piàoliang de huā, xīwàng tā gāogāoxìngxìng de guò ge xīnnián.","Các bạn cùng lớp chúng tôi cũng tặng cô Vương hoa đẹp, mong cô vui vẻ đón một năm mới."]],"sides":{"白家月":"C"}}],"14":[{"context":"Trên đường về nhà, Lý Văn và Vương Nhất Phi vừa đi vừa trò chuyện.","contextZh":"在回家路上，李文和王一飞边走边聊。","label":"14-1 · Người lạ dưới lầu","lines":[["李文","王老师，你家楼下站着一个人。","Wáng lǎoshī, nǐ jiā lóu xià zhànzhe yí ge rén.","Cô Vương ơi, dưới lầu nhà cô có một người đang đứng."],["王一飞","我家楼下？我看看。","Wǒ jiā lóu xià? Wǒ kànkan.","Dưới lầu nhà tôi à? Để tôi xem."],["李文","那个人穿着黑色的裤子，手里还拿着一个黑色的包。","Nà ge rén chuānzhe hēisè de kùzi, shǒulǐ hái názhe yí ge hēisè de bāo.","Người đó mặc quần màu đen, trên tay còn cầm một cái túi màu đen."],["王一飞","我看见那个人了，他是我男朋友。","Wǒ kànjiàn nà ge rén le, tā shì wǒ nánpéngyou.","Tôi nhìn thấy người đó rồi, anh ấy là bạn trai tôi."],["李文","那我们快过去吧。","Nà wǒmen kuài guòqù ba.","Vậy chúng ta mau qua đó đi."]],"sides":{"李文":"L","王一飞":"R"}},{"context":"Dưới lầu, Vương Nhất Phi gặp Dương Đồng Lạc.","contextZh":"在楼下，王一飞见到杨同乐。","label":"14-2 · Gặp bạn trai dưới lầu","lines":[["王一飞","同乐，真是你啊！上次打电话，你说有时间过来看我，没想到这么快就来了！","Tónglè, zhēn shì nǐ a! Shàng cì dǎ diànhuà, nǐ shuō yǒu shíjiān guòlái kàn wǒ, méi xiǎngdào zhème kuài jiù lái le!","Đồng Lạc, đúng là bạn thật! Lần trước gọi điện, bạn nói có thời gian sẽ qua thăm tôi, không ngờ đến nhanh thế!"],["杨同乐","就要过年了，你一个人在这儿多没意思啊，所以我就早早过来了。","Jiù yào guònián le, nǐ yí ge rén zài zhèr duō méi yìsi a, suǒyǐ wǒ jiù zǎozǎo guòlái le.","Sắp đến Tết rồi, bạn một mình ở đây chán biết bao, nên tôi đến sớm."],["王一飞","你能来，我太高兴了！","Nǐ néng lái, wǒ tài gāoxìng le!","Bạn đến được, tôi vui quá!"],["杨同乐","一飞，你旁边这位是？","Yīfēi, nǐ pángbiān zhè wèi shì?","Nhất Phi, người bên cạnh bạn đây là ai?"],["王一飞","同乐，这是李文，他在我们学校学医。李文，这是我男朋友杨同乐。","Tónglè, zhè shì Lǐ Wén, tā zài wǒmen xuéxiào xué yī. Lǐ Wén, zhè shì wǒ nánpéngyou Yáng Tónglè.","Đồng Lạc, đây là Lý Văn, anh ấy học y ở trường chúng tôi. Lý Văn, đây là bạn trai tôi, Dương Đồng Lạc."],["杨同乐","李文，很高兴认识你！","Lǐ Wén, hěn gāoxìng rènshi nǐ!","Lý Văn, rất vui được gặp bạn!"],["李文","认识你我也很高兴！我家就在前面那个楼，有时间来玩。","Rènshi nǐ wǒ yě hěn gāoxìng! Wǒ jiā jiù zài qiánmian nà ge lóu, yǒu shíjiān lái wán.","Được gặp bạn tôi cũng rất vui! Nhà tôi ở ngay tòa nhà phía trước kia, có thời gian thì qua chơi."]],"sides":{"李文":"L","杨同乐":"R","王一飞":"L"}},{"context":"Ở nhà Vương Nhất Phi, Vương Nhất Phi và Dương Đồng Lạc trò chuyện trong phòng khách.","contextZh":"在王一飞家里，王一飞和杨同乐在客厅聊天儿。","label":"14-3 · Trò chuyện ở nhà Nhất Phi","lines":[["杨同乐","一飞，你住的房子真不错，很大，离学校也不远。","Yīfēi, nǐ zhù de fángzi zhēn búcuò, hěn dà, lí xuéxiào yě bù yuǎn.","Nhất Phi, căn nhà bạn ở thật tốt, rất to, lại không xa trường."],["王一飞","是啊！我楼下还住着一家中国人，他们人很好。","Shì a! Wǒ lóu xià hái zhùzhe yì jiā Zhōngguó rén, tāmen rén hěn hǎo.","Đúng vậy! Dưới lầu nhà tôi còn có một gia đình người Trung Quốc ở, họ rất tốt."],["杨同乐","这样你有事情就可以找他们帮忙。","Zhèyàng nǐ yǒu shìqing jiù kěyǐ zhǎo tāmen bāngmáng.","Như vậy có việc gì bạn có thể nhờ họ giúp."],["王一飞","对，我也帮他们家的小孩儿学中文。","Duì, wǒ yě bāng tāmen jiā de xiǎoháir xué Zhōngwén.","Đúng, tôi cũng giúp đứa trẻ nhà họ học tiếng Trung."],["杨同乐","我记得你跟我说过，是个女孩儿，学得也很好。","Wǒ jìde nǐ gēn wǒ shuō guo, shì ge nǚháir, xué de yě hěn hǎo.","Tôi nhớ bạn từng nói với tôi, đó là một bé gái, học cũng rất tốt."],["王一飞","没错，她经常跑上来找我玩。","Méi cuò, tā jīngcháng pǎo shànglái zhǎo wǒ wán.","Đúng rồi, em ấy thường xuyên chạy lên tìm tôi chơi."],["杨同乐","你问问他们什么时候有时间，我请他们吃个饭。","Nǐ wènwen tāmen shénme shíhou yǒu shíjiān, wǒ qǐng tāmen chī ge fàn.","Bạn hỏi họ khi nào rảnh, tôi mời họ ăn một bữa cơm."]],"sides":{"杨同乐":"L","王一飞":"R"}},{"context":"Trong phòng, Vương Nhất Phi đang viết nhật ký.","contextZh":"在房间，王一飞在写日记。","label":"14-4 · Nhật ký của Nhất Phi","lines":[["王一飞","我男朋友姓杨，叫杨同乐。","Wǒ nánpéngyou xìng Yáng, jiào Yáng Tónglè.","Bạn trai tôi họ Dương, tên là Dương Đồng Lạc."],["王一飞","他高个子、大眼睛，唱歌唱得很好，跳舞跳得也不错。","Tā gāo gèzi, dà yǎnjing, chànggē chàng de hěn hǎo, tiàowǔ tiào de yě búcuò.","Anh ấy cao, mắt to, hát rất hay, nhảy múa cũng không tệ."],["王一飞","他和我姐姐一起工作，是姐姐介绍我们认识的。","Tā hé wǒ jiějie yìqǐ gōngzuò, shì jiějie jièshào wǒmen rènshi de.","Anh ấy làm việc cùng chị gái tôi, chính chị gái đã giới thiệu chúng tôi quen nhau."],["王一飞","他告诉我，从见到我的第一天开始，他就喜欢上我了。","Tā gàosu wǒ, cóng jiàndào wǒ de dì-yī tiān kāishǐ, tā jiù xǐhuan shàng wǒ le.","Anh ấy nói với tôi, từ ngày đầu tiên gặp tôi, anh ấy đã thích tôi rồi."]],"sides":{"王一飞":"C"}}],"15":[{"context":"Trong lớp học, các bạn học sinh đang thi.","contextZh":"在教室，同学们在考试。","label":"15-1 · Sau giờ thi","lines":[["王一飞","考试就要开始了，请大家写上姓名，写好后就可以做题了。","Kǎoshì jiù yào kāishǐ le, qǐng dàjiā xiě shang xìngmíng, xiěhǎo hòu jiù kěyǐ zuò tí le.","Kỳ thi sắp bắt đầu, mời mọi người viết họ tên lên, viết xong là có thể làm bài."],["白家月","老师，我做完了。","Lǎoshī, wǒ zuòwán le.","Cô ơi, em làm xong rồi."],["陈天中","老师，我也做完了。","Lǎoshī, wǒ yě zuòwán le.","Cô ơi, em cũng làm xong rồi."],["王一飞","……对了，你们考完试想做什么？","...Duìle, nǐmen kǎowán shì xiǎng zuò shénme?","À đúng rồi, thi xong các bạn muốn làm gì?"],["白家月","我很想去中国，虽然去过一次，但是很想再去一次。","Wǒ hěn xiǎng qù Zhōngguó, suīrán qù guo yí cì, dànshì hěn xiǎng zài qù yí cì.","Em rất muốn đến Trung Quốc, tuy đã đến một lần rồi nhưng rất muốn đến thêm một lần nữa."],["王一飞","不错，到中国后你就可以经常说中文了。","Búcuò, dào Zhōngguó hòu nǐ jiù kěyǐ jīngcháng shuō Zhōngwén le.","Tốt đấy, đến Trung Quốc rồi bạn có thể thường xuyên nói tiếng Trung."]],"sides":{"王一飞":"L","白家月":"R","陈天中":"L"}},{"context":"Trong quán cà phê, Lý Văn và Bạch Gia Nguyệt đang trò chuyện.","contextZh":"在咖啡店，李文和白家月在聊天儿。","label":"15-2 · Kế hoạch đi Bắc Kinh","lines":[["白家月","考完试了，我现在可以出国旅游了。","Kǎowán shì le, wǒ xiànzài kěyǐ chūguó lǚyóu le.","Thi xong rồi, bây giờ tôi có thể ra nước ngoài du lịch."],["李文","你要去哪儿？","Nǐ yào qù nǎr?","Bạn định đi đâu?"],["白家月","我要再去一次北京。","Wǒ yào zài qù yí cì Běijīng.","Tôi muốn đến Bắc Kinh thêm một lần nữa."],["李文","为什么还去北京？","Wèi shénme hái qù Běijīng?","Sao còn đến Bắc Kinh nữa?"],["白家月","因为我想再吃一次烤鸭，再喝一次奶茶，再去北京大学看一次电影……","Yīnwèi wǒ xiǎng zài chī yí cì kǎoyā, zài hē yí cì nǎichá, zài qù Běijīng Dàxué kàn yí cì diànyǐng...","Vì tôi muốn ăn vịt quay thêm một lần nữa, uống trà sữa thêm một lần nữa, đến Đại học Bắc Kinh xem phim thêm một lần nữa..."],["李文","你想做的事情很多啊！","Nǐ xiǎng zuò de shìqing hěn duō a!","Những việc bạn muốn làm nhiều thật!"],["白家月","是啊，你看，我还在网上买好颐和园的门票了呢。","Shì a, nǐ kàn, wǒ hái zài wǎngshang mǎihǎo Yíhé Yuán de ménpiào le ne.","Đúng vậy, bạn xem, tôi còn mua sẵn vé vào Di Hòa Viên trên mạng rồi."],["李文","我的高中同学就在颐和园上班，可以让他给你好好介绍介绍。","Wǒ de gāozhōng tóngxué jiù zài Yíhé Yuán shàngbān, kěyǐ ràng tā gěi nǐ hǎohāo jièshào jièshào.","Bạn học cấp ba của tôi làm việc ở Di Hòa Viên, có thể nhờ anh ấy giới thiệu kỹ cho bạn."],["白家月","太好了！出门旅游，多个朋友多条路。","Tài hǎo le! Chūmén lǚyóu, duō ge péngyou duō tiáo lù.","Tuyệt quá! Đi du lịch, càng nhiều bạn càng nhiều đường."]],"sides":{"李文":"R","白家月":"L"}},{"context":"Trong quán cà phê, Lý Văn và Bạch Gia Nguyệt đang trò chuyện.","contextZh":"在咖啡店，李文和白家月在聊天儿。","label":"15-3 · Nhớ lại lần về nước trước","lines":[["白家月","李文，你有一年没回国了吧？","Lǐ Wén, nǐ yǒu yì nián méi huí guó le ba?","Lý Văn, bạn đã một năm không về nước rồi phải không?"],["李文","不到一年。我六月的时候回去了一次。","Bú dào yì nián. Wǒ Liùyuè de shíhou huíqù le yí cì.","Chưa đến một năm. Tháng sáu tôi về một lần rồi."],["白家月","我怎么忘了？还是我送你去的机场呢。","Wǒ zěnme wàng le? Hái shì wǒ sòng nǐ qù de jīchǎng ne.","Sao tôi lại quên nhỉ? Vẫn là tôi đưa bạn ra sân bay mà."],["李文","是啊。","Shì a.","Đúng vậy."],["白家月","我记得你那次的机票很便宜。","Wǒ jìde nǐ nà cì de jīpiào hěn piányi.","Tôi nhớ vé máy bay lần đó của bạn rất rẻ."],["李文","没错，可能因为那个时候去北京的人不多吧。","Méi cuò, kěnéng yīnwèi nà ge shíhou qù Běijīng de rén bù duō ba.","Đúng vậy, có lẽ vì lúc đó không nhiều người đến Bắc Kinh."],["白家月","这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。","Zhè cì de jīpiào suīrán yǒudiǎnr guì, dàn xiǎngdào jiù yào fēi Běijīng le, wǒ hái shì hěn gāoxìng de.","Vé máy bay lần này tuy hơi đắt, nhưng nghĩ đến việc sắp bay đến Bắc Kinh, tôi vẫn rất vui."]],"sides":{"李文":"R","白家月":"L"}},{"context":"Trong phòng, Lý Văn đang viết nhật ký.","contextZh":"在房间，李文在写日记。","label":"15-4 · Nhật ký của Lý Văn","lines":[["李文","我六月的时候回过一次北京，现在有半年多没回去了，我有点儿想家。","Wǒ Liùyuè de shíhou huíguo yí cì Běijīng, xiànzài yǒu bàn nián duō méi huíqù le, wǒ yǒudiǎnr xiǎng jiā.","Tháng sáu tôi đã về Bắc Kinh một lần, bây giờ đã hơn nửa năm không về, tôi hơi nhớ nhà."],["李文","就要过年了，我要回家过年。","Jiù yào guònián le, wǒ yào huí jiā guònián.","Sắp đến Tết rồi, tôi muốn về nhà đón Tết."],["李文","家月这次也要去北京，我们都是星期五的飞机。","Jiāyuè zhè cì yě yào qù Běijīng, wǒmen dōu shì Xīngqīwǔ de fēijī.","Lần này Gia Nguyệt cũng đến Bắc Kinh, chúng tôi đều bay chuyến thứ sáu."],["李文","家月说我们好像小鸟，一起飞到北京，再一起飞回这里。","Jiāyuè shuō wǒmen hǎoxiàng xiǎoniǎo, yìqǐ fēi dào Běijīng, zài yìqǐ fēi huí zhèlǐ.","Gia Nguyệt nói chúng tôi giống như những chú chim nhỏ, cùng bay đến Bắc Kinh, rồi cùng bay về đây."]],"sides":{"李文":"C"}}]};
window.dictations = window.dictations2 = {"1":[["请问，您是王一飞老师的姐姐吗？","Xin hỏi, cô có phải là chị gái của thầy Vương Nhất Phi không ạ?","请问 · 姐姐 · 老师"],["你们就是她的学生吧？","Các bạn chính là học sinh của cô ấy phải không?","就是 · 学生 · 吧"],["一飞给我打电话了，让我来接你们。","Nhất Phi đã gọi điện cho tôi, nhờ tôi đến đón các bạn.","打电话 · 让 · 接"],["你们是第一次来北京吗？","Đây có phải là lần đầu tiên các bạn đến Bắc Kinh không?","第一次 · 北京"],["我们都是第一次来。","Chúng tôi đều là lần đầu tiên đến.","都是 · 第一次"],["你们是来学中文的吗？","Các bạn đến để học tiếng Trung phải không?","学中文 · 是……的"],["不是，我们是来旅游的。","Không phải, chúng tôi đến để du lịch.","不是 · 旅游"],["我这几天都不忙，你们有事就找我。","Mấy ngày này tôi đều không bận, các bạn có việc gì cứ tìm tôi.","这几天 · 不忙 · 有事"],["喂，家月，你明天有时间吗？","A lô, Gia Nguyệt, ngày mai bạn có thời gian không?","明天 · 时间"],["我想请你帮个忙。","Tôi muốn nhờ bạn giúp một việc.","请 · 帮忙"],["不好意思，我已经到北京了。","Xin lỗi, tôi đã đến Bắc Kinh rồi.","不好意思 · 已经"],["你是什么时候到的？","Bạn đến lúc nào vậy?","什么时候 · 到"],["我是今天早上到的。","Tôi đến sáng nay.","今天早上 · 是……的"],["你有事可以叫李文帮忙，他还在学校呢。","Bạn có việc gì có thể nhờ Lý Văn giúp, cậu ấy vẫn còn ở trường.","叫 · 帮忙 · 学校"],["好的，那我给他打个电话。","Được, vậy thì tôi gọi điện cho cậu ấy.","那 · 打电话"],["我们已经到北京了，是您姐姐来接的我们。","Chúng em đã đến Bắc Kinh rồi, chính chị gái của thầy đã đến đón chúng em.","已经 · 姐姐 · 接"],["她请我们吃了北京烤鸭。","Chị ấy mời chúng em ăn vịt quay Bắc Kinh.","请 · 北京烤鸭"],["她还给我们介绍了很多东西。","Chị ấy còn giới thiệu cho chúng em rất nhiều thứ.","介绍 · 东西"],["我们的中文不太好，有时不太懂她的意思。","Tiếng Trung của chúng em không tốt lắm, đôi khi không hiểu rõ ý của chị ấy.","中文 · 有时 · 意思"],["王老师让我们说中文。","Thầy Vương bảo chúng tôi nói tiếng Trung.","让 · 说中文"]],"2":[["请问，这儿有到北京大学的公交车吗？","Xin hỏi, ở đây có xe buýt đi Đại học Bắc Kinh không ạ?","公交车 · 北京大学"],["有，但车站有点儿远。","Có, nhưng trạm xe hơi xa.","但 · 车站 · 远"],["这儿好打车吗？","Ở đây có dễ đón taxi không?","好 · 打车"],["我们还是打车去吧。","Chúng ta vẫn nên đi taxi thì hơn.","还是 · 打车"],["学校里人真多啊！","Trong trường đông người thật đấy!","人 · 多 · 啊"],["北京大学有四万多名学生呢！","Đại học Bắc Kinh có hơn bốn vạn sinh viên đấy!","四万多 · 学生"],["你是怎么知道的？","Bạn biết bằng cách nào vậy?","怎么 · 知道"],["是网上说的。","Là trên mạng nói vậy.","网上 · 说"],["北京大学有三千多名外国学生。","Đại học Bắc Kinh có hơn ba nghìn sinh viên nước ngoài.","三千多 · 外国学生"],["我也想来这儿学习。","Tôi cũng muốn đến đây học.","也 · 学习"],["那边就有一间教室，我们去看一下吧。","Bên kia có một phòng học, chúng ta qua xem một chút nhé.","一间 · 教室"],["学校里有家电影院！","Trong trường có một rạp chiếu phim!","电影院"],["电影院还不小。","Rạp chiếu phim còn không nhỏ đâu.","电影院 · 不小"],["他们卖的电影票也很便宜。","Vé xem phim họ bán cũng rất rẻ.","电影票 · 便宜"],["有的还不到二十块钱。","Có vé còn chưa đến hai mươi đồng.","不到 · 二十块钱"],["那你想不想去看个电影？","Vậy bạn có muốn đi xem một bộ phim không?","想不想 · 电影"],["还是别看电影了，北京大学就很好看！","Vẫn là đừng xem phim nữa, Đại học Bắc Kinh đã rất đẹp rồi!","还是 · 别 · 好看"],["北京大学很大，有四万多名学生。","Đại học Bắc Kinh rất lớn, có hơn bốn vạn sinh viên.","很大 · 四万多"],["学校很漂亮，里边还有家电影院。","Trường rất đẹp, bên trong còn có một rạp chiếu phim.","漂亮 · 电影院"],["我们有时间还想再过来看个电影。","Khi có thời gian chúng tôi còn muốn quay lại xem một bộ phim.","有时间 · 过来 · 电影"]],"3":[["今天回来这么晚啊！","Hôm nay về muộn thế!","回来 · 这么晚"],["工作太多了，下班的时候没做完。","Việc nhiều quá, lúc tan làm vẫn chưa làm xong.","工作 · 做完"],["菜都做好了，过来吃饭吧。","Cơm đã nấu xong hết rồi, qua đây ăn cơm đi.","做好 · 过来"],["我想休息一下，喝杯水。","Tôi muốn nghỉ một lát, uống cốc nước.","休息一下 · 喝水"],["我们找个时间去旅游，怎么样？","Chúng ta tìm thời gian đi du lịch nhé, thế nào?","找个时间 · 旅游"],["我也很想一起出去玩。","Tôi cũng rất muốn cùng đi chơi.","一起 · 出去玩"],["你想去哪儿？","Bạn muốn đi đâu?","想去 · 哪儿"],["我还没想好呢。","Tôi vẫn chưa nghĩ ra.","没想好"],["那你再想一想，你想好了，我来买票。","Vậy bạn nghĩ thêm đi, bạn nghĩ xong rồi thì tôi đi mua vé.","再想一想 · 想好 · 买票"],["吃个苹果吧，我都洗好了。","Ăn quả táo đi, tôi đã rửa sạch hết rồi.","苹果 · 洗好"],["就在桌子上，你自己拿。","Ngay trên bàn đấy, bạn tự lấy đi.","桌子 · 自己 · 拿"],["我去洗洗手。","Tôi đi rửa tay một cái.","洗洗手"],["对了，我们去西安旅游，怎么样？","À này, chúng ta đi Tây An du lịch nhé, thế nào?","对了 · 西安 · 旅游"],["为什么想去西安？","Tại sao muốn đi Tây An?","为什么 · 西安"],["我看了看网上的介绍，这个时候去西安很不错！","Tôi đã xem qua giới thiệu trên mạng, đi Tây An vào lúc này rất tuyệt!","看了看 · 网上 · 不错"],["早上，刘明开车送孩子去学校。","Buổi sáng, Lưu Minh lái xe đưa con đi học.","早上 · 开车 · 送孩子"],["送完孩子回家后，医院就来电话了。","Đưa con xong về đến nhà thì bệnh viện gọi điện đến.","送完 · 医院 · 电话"],["医院让他回去上班。","Bệnh viện bảo anh ấy quay lại đi làm.","回去 · 上班"],["我觉得他这个月每天都很累。","Tôi thấy tháng này ngày nào anh ấy cũng rất mệt.","这个月 · 每天 · 累"],["真想让他休息休息。","Thật muốn để anh ấy nghỉ ngơi một chút.","休息休息"]],"4":[["妈妈，我们来过这家商场吗？","Mẹ ơi, chúng ta đã từng đến trung tâm thương mại này chưa?","来过 · 商场"],["没来过，这是新开的。","Chưa từng đến, đây là chỗ mới mở.","没来过 · 新开的"],["我们进去看看吧。","Chúng ta vào trong xem thử đi.","进去 · 看看"],["你想买点儿什么？","Con muốn mua chút gì?","买点儿 · 什么"],["我想买条裤子。","Tôi muốn mua một chiếc quần.","买 · 条 · 裤子"],["妈妈，我想买这条白色的裤子。","Mẹ ơi, con muốn mua chiếc quần màu trắng này.","白色 · 裤子"],["你有很多白色的衣服，为什么还买白色的？","Con đã có rất nhiều quần áo màu trắng, tại sao còn mua màu trắng nữa?","白色 · 为什么"],["因为我喜欢白色啊！","Vì tôi thích màu trắng mà!","因为 · 喜欢 · 白色"],["我觉得这条白色的不太好看，你试试那条红色的吧。","Tôi thấy chiếc quần màu trắng này không đẹp lắm, bạn thử chiếc màu đỏ kia đi.","觉得 · 不太好看 · 试试 · 红色"],["我没穿过红色的，红色的好看吗？","Tôi chưa từng mặc màu đỏ, màu đỏ có đẹp không?","没穿过 · 红色 · 好看"],["就是因为没穿过，所以要试试啊！","Chính vì chưa từng mặc nên mới phải thử chứ!","因为 · 所以 · 试试"],["妈妈，我想买个新书包。","Mẹ ơi, tôi muốn mua một chiếc cặp sách mới.","新 · 书包"],["那边卖书包，我们过去看看吧。","Bên kia bán cặp sách, chúng ta qua đó xem thử đi.","卖 · 过去 · 看看"],["这么多漂亮的书包！","Nhiều cặp sách đẹp thế!","这么多 · 漂亮 · 书包"],["红色的、绿色的、黑色的，你想买哪个？","Màu đỏ, màu xanh lá, màu đen, bạn muốn mua cái nào?","红色 · 绿色 · 黑色"],["不错，我也觉得绿色的更好看。","Không tệ, tôi cũng thấy màu xanh lá đẹp hơn.","不错 · 绿色 · 更好看"],["我和妈妈去了一家商场。","Tôi và mẹ đã đi một trung tâm thương mại.","和 · 商场"],["因为是新开的，所以这几天东西很便宜。","Vì là chỗ mới mở nên mấy ngày này đồ đạc rất rẻ.","因为 · 所以 · 便宜"],["商场里的衣服颜色很多。","Quần áo trong trung tâm thương mại có rất nhiều màu sắc.","衣服 · 颜色 · 很多"],["我觉得我穿红色的也很好看。","Tôi thấy mình mặc màu đỏ cũng rất đẹp.","穿 · 红色 · 好看"]],"5":[["家月，快下来吧，第一次去中国朋友家，别晚了。","Gia Nguyệt, mau xuống đi, lần đầu đến nhà bạn người Trung Quốc, đừng muộn nhé.","快下来 · 第一次 · 中国朋友家"],["还有时间，你上来吧。","Vẫn còn thời gian, bạn lên đây đi.","还有时间 · 上来"],["我不上去了，就在下面等你。","Tôi không lên nữa, cứ đợi bạn ở dưới này.","不上去 · 下面 · 等"],["那我一会儿就下去。","Vậy tôi sẽ xuống ngay trong một lát.","一会儿 · 下去"],["你快点儿吧。","Bạn nhanh lên nhé.","快点儿"],["一雪姐说11点前到就可以。","Chị Nhất Tuyết nói đến trước 11 giờ là được.","11点前 · 到"],["家月、安妮，快进来！","Gia Nguyệt, Annie, mau vào đây!","快 · 进来"],["我给你们介绍一下，这是孩子们的爷爷、奶奶。","Tôi giới thiệu với các bạn một chút, đây là ông và bà của các cháu.","介绍 · 爷爷 · 奶奶"],["爸，妈，这是白家月，这是安妮。","Bố, mẹ, đây là Bạch Gia Nguyệt, đây là Annie.","爸 · 妈 · 白家月"],["她们都是一飞的学生。","Hai bạn đều là học sinh của Nhất Phi.","都是 · 学生"],["这是送你们的礼物。","Đây là quà tặng ông bà.","送 · 礼物"],["你们太客气了，还拿这么多礼物来！","Các cháu khách sáo quá, còn mang nhiều quà đến thế!","太客气 · 礼物"],["这是给孩子们准备的礼物。","Đây là quà đã chuẩn bị cho các cháu.","准备 · 礼物"],["谢谢！你们别客气，快坐吧！","Cảm ơn! Các bạn đừng khách sáo, mau ngồi đi!","别客气 · 快坐"],["都12点了，我们吃饭吧。","Đã 12 giờ rồi, chúng ta ăn cơm đi.","都12点 · 吃饭"],["都是我自己做的，你们多吃点儿。","Đều là tự tay tôi nấu, các bạn ăn nhiều một chút nhé.","自己 · 多吃点儿"],["奶茶也很好喝，是您自己做的吗？","Trà sữa cũng rất ngon, có phải tự tay cô làm không?","奶茶 · 好喝 · 自己"],["不是，奶茶是爷爷买的。","Không phải, trà sữa là ông mua đấy.","奶茶 · 爷爷 · 买"],["回国前一天，我们去一雪姐家了。","Một ngày trước khi về nước, chúng tôi đã đến nhà chị Nhất Tuyết.","回国 · 一雪姐"],["因为吃了太多东西，我们吃完饭是走回酒店的。","Vì ăn quá nhiều nên ăn cơm xong chúng tôi đi bộ về khách sạn.","吃太多 · 走回 · 酒店"]],"6":[["明天就是女儿的生日了。","Ngày mai là sinh nhật của con gái rồi.","明天 · 女儿 · 生日"],["你不说，我还真忘了。","Bạn không nói thì tôi thật sự đã quên mất rồi.","不说 · 真 · 忘"],["我们给她准备个什么礼物呢？","Chúng ta chuẩn bị cho con bé món quà gì đây?","准备 · 什么 · 礼物"],["她喜欢画画，你觉得画笔怎么样？","Con bé thích vẽ tranh, bạn thấy bút vẽ thế nào?","喜欢 · 画画 · 画笔"],["我再给她买个大大的生日蛋糕。","Tôi sẽ mua thêm cho con bé một cái bánh sinh nhật thật to.","再 · 大大 · 生日蛋糕"],["小雪，生日快乐！","Tiểu Tuyết, chúc mừng sinh nhật!","小雪 · 生日 · 快乐"],["这是爸爸、妈妈送你的礼物。","Đây là quà bố mẹ tặng con.","爸爸 · 妈妈 · 礼物"],["你打开看看喜欢不喜欢。","Con mở ra xem có thích không.","打开 · 看看 · 喜欢"],["画笔！我很喜欢！","Bút vẽ! Con rất thích!","画笔 · 很 · 喜欢"],["那你想画点儿什么？","Vậy con muốn vẽ gì nào?","想 · 画 · 什么"],["画我们的家！有爸爸、妈妈、弟弟，还有黑色的狗、白色的猫什么的。","Vẽ nhà của chúng ta! Có bố, mẹ, em trai, còn có con chó đen, con mèo trắng các thứ nữa.","家 · 爸爸 · 什么的"],["那我要画一个穿白色衣服的姐姐。","Vậy em sẽ vẽ một chị gái mặc quần áo trắng.","画 · 白色 · 衣服"],["小雪，看看今天有什么好吃的。","Tiểu Tuyết, con xem hôm nay có món gì ngon nào.","看看 · 今天 · 好吃"],["长长的面条儿，大大的蛋糕。","Mì sợi dài dài, bánh kem to to.","长长 · 面条儿 · 大大"],["还有鱼啊肉啊什么的，都是你喜欢吃的。","Còn có cá, thịt các thứ nữa, đều là món con thích ăn.","鱼 · 肉 · 什么的"],["快去叫弟弟过来吃饭吧，吃完饭我们还要出去玩呢。","Mau đi gọi em trai lại ăn cơm đi, ăn xong chúng ta còn phải ra ngoài chơi nữa.","叫 · 弟弟 · 出去玩"],["过生日真好啊！","Được mừng sinh nhật thật là thích!","过生日 · 真 · 好"],["过生日就要吃好吃的，还要高高兴兴地玩。","Mừng sinh nhật thì phải ăn ngon, còn phải chơi thật vui vẻ.","过生日 · 吃 · 高高兴兴地"],["我们买了蛋糕，做了面条儿，还做了鱼啊肉啊什么的。","Chúng tôi mua bánh kem, làm mì sợi, còn làm cả cá, thịt các thứ nữa.","蛋糕 · 面条儿 · 什么的"],["这是很忙、很累，但很快乐的一天。","Đây là một ngày rất bận rộn, rất mệt, nhưng cũng rất vui.","忙 · 累 · 快乐"]],"7":[["安妮，你是什么时候从北京回来的？","An Ni, bạn trở về từ Bắc Kinh lúc nào?","安妮 · 什么时候 · 从"],["昨天下午。","Chiều hôm qua.","昨天 · 下午"],["你怎么一下课就往外跑？","Sao bạn vừa tan học đã chạy ra ngoài?","一下课 · 就 · 往外跑"],["我跟同学说好了，一起去打篮球。","Tôi đã hẹn với bạn học, cùng nhau đi chơi bóng rổ.","同学 · 说好 · 打篮球"],["我也想跟你们一起玩。","Tôi cũng muốn đi chơi cùng các bạn.","也 · 跟 · 一起玩"],["没问题，走吧。","Không vấn đề gì, đi thôi.","没问题 · 走"],["天中，你是不是很喜欢打篮球？","Thiên Trung, bạn có rất thích chơi bóng rổ không?","是不是 · 很 · 打篮球"],["你还喜欢什么运动？","Bạn còn thích môn thể thao nào nữa?","还 · 什么 · 运动"],["我还喜欢踢足球，一到星期天就跟朋友们去踢球。","Tôi còn thích đá bóng, cứ đến Chủ nhật là cùng các bạn đi đá bóng.","踢足球 · 一到 · 就"],["你踢得怎么样？","Bạn đá thế nào?","踢得 · 怎么样"],["我踢得还可以。","Tôi đá cũng tạm được.","踢得 · 还可以"],["你篮球打得怎么样？","Bạn chơi bóng rổ thế nào?","篮球 · 打得 · 怎么样"],["打得还可以。","Chơi cũng tạm được.","打得 · 还可以"],["跑步呢？你跑得快不快？","Còn chạy bộ thì sao? Bạn chạy có nhanh không?","跑步 · 跑得 · 快不快"],["我跑得不快，也不太喜欢跑步。","Tôi chạy không nhanh, cũng không thích chạy bộ lắm.","跑得 · 不快 · 跑步"],["那你喜欢游泳吗？","Vậy bạn có thích bơi không?","喜欢 · 游泳"],["喜欢，但我游泳游得不快。","Thích, nhưng tôi bơi không nhanh.","游泳 · 游得 · 不快"],["我的爱好是运动。","Sở thích của tôi là thể thao.","爱好 · 运动"],["现在我篮球打得很好，足球踢得不错，游泳游得也很快。","Bây giờ tôi chơi bóng rổ rất giỏi, đá bóng cũng khá tốt, bơi cũng rất nhanh.","篮球 · 足球 · 游泳"],["我一有时间就去运动。","Cứ có thời gian rảnh là tôi lại đi tập thể thao.","一有时间 · 就 · 运动"]],"8":[["你看，这两块手表怎么样？","Bạn xem, hai cái đồng hồ này thế nào?","手表 · 两块 · 怎么样"],["我也觉得左边的比右边的好看。","Tôi cũng thấy cái bên trái đẹp hơn cái bên phải.","左边 · 比 · 右边"],["真不便宜！八千八！","Thật không rẻ chút nào! Tám nghìn tám trăm tệ!","不便宜 · 八千八"],["今天有不少电影，我们看个电影吧。","Hôm nay có không ít phim, chúng ta đi xem một bộ phim nhé.","不少 · 电影 · 看"],["我记得你喜欢看爱情片。","Tôi nhớ bạn thích xem phim tình cảm.","记得 · 喜欢 · 爱情片"],["我们看那个爱情片，怎么样？","Chúng ta xem bộ phim tình cảm kia nhé, thế nào?","爱情片 · 怎么样"],["还是看这个吧，我看网上说这个电影比那个爱情片更有意思。","Hay là xem bộ này đi, tôi đọc trên mạng nói bộ phim này thú vị hơn bộ phim tình cảm kia.","网上 · 比 · 更有意思"],["到网上买吧，网上买比在这里买便宜。","Mua trên mạng đi, mua trên mạng rẻ hơn mua ở đây.","网上 · 比 · 便宜"],["怎么点这么多菜？","Sao lại gọi nhiều món thế?","点 · 这么多 · 菜"],["你想想，今天是几月几号？","Bạn nghĩ xem, hôm nay là ngày mấy tháng mấy?","想想 · 几月 · 几号"],["8月27号。啊！我的生日！","Ngày 27 tháng 8. À! Sinh nhật của tôi!","8月27号 · 生日"],["生日快乐！虽然你忘了，但是我记得。","Chúc mừng sinh nhật! Tuy bạn quên mất, nhưng tôi vẫn nhớ.","生日快乐 · 虽然 · 但是"],["吃饭、看电影、买手表，今天花了不少钱吧？","Ăn cơm, xem phim, mua đồng hồ, hôm nay tiêu không ít tiền nhỉ?","吃饭 · 看电影 · 花"],["虽然花了一些钱，但是我们过了一个快乐的生日。","Tuy tiêu tốn một ít tiền, nhưng chúng tôi đã có một sinh nhật vui vẻ.","虽然 · 花 · 快乐"],["今天比昨天冷。","Hôm nay lạnh hơn hôm qua.","今天 · 比 · 昨天"],["他觉得踢足球比打篮球有意思。","Anh ấy thấy đá bóng thú vị hơn chơi bóng rổ.","踢足球 · 比 · 打篮球"],["今天比昨天更热。","Hôm nay nóng hơn hôm qua.","今天 · 比 · 更热"],["虽然妻子忘了今天是自己的生日，但是丈夫记得。","Tuy người vợ quên mất hôm nay là sinh nhật của mình, nhưng người chồng vẫn nhớ.","虽然 · 妻子 · 丈夫"],["丈夫请妻子去饭馆吃饭、去电影院看电影。","Người chồng mời vợ đi ăn ở nhà hàng, đi xem phim ở rạp chiếu phim.","丈夫 · 饭馆 · 电影院"],["妻子觉得今天很快乐。","Người vợ cảm thấy hôm nay rất vui.","妻子 · 今天 · 快乐"]],"9":[["儿子的裤子坏了，我们给他买条新的吧。","Quần của con trai bị rách rồi, chúng ta mua cho con một cái mới nhé.","儿子 · 裤子 · 坏"],["你看这条黑色的怎么样？","Bạn xem chiếc quần đen này thế nào?","黑色 · 怎么样"],["没有你上次买的那条好看。","Không đẹp bằng chiếc quần bạn mua lần trước.","没有 · 上次 · 好看"],["旁边那个男孩儿就穿了这样的裤子，我觉得很好看啊！","Cậu bé bên cạnh đang mặc chiếc quần như thế này, tôi thấy đẹp lắm!","旁边 · 男孩儿 · 这样"],["儿子的个子没有他那么高，穿上就不会太好看。","Con trai tôi không cao bằng cậu ấy, mặc vào sẽ không đẹp lắm.","个子 · 没有 · 那么高"],["好吧，我们再去那边看看。","Được thôi, chúng ta sang chỗ khác xem tiếp.","再去 · 那边 · 看看"],["门口有家奶茶店。你想喝杯奶茶吗？","Ở cửa có một quán trà sữa. Bạn có muốn uống một cốc trà sữa không?","门口 · 奶茶店 · 奶茶"],["我想喝咖啡，还是去咖啡店吧。","Tôi muốn uống cà phê, hay là đến quán cà phê đi.","咖啡 · 咖啡店"],["咖啡店离这儿有点儿远。","Quán cà phê cách đây hơi xa.","咖啡店 · 离 · 远"],["没关系，那家店的咖啡很好喝。","Không sao, cà phê ở quán đó rất ngon.","没关系 · 咖啡 · 好喝"],["那你等一下，我去买杯奶茶。","Vậy bạn đợi một lát, tôi đi mua một cốc trà sữa.","等一下 · 买 · 奶茶"],["喝了咖啡，晚上就别想睡觉了。","Uống cà phê rồi, tối sẽ không ngủ được đâu.","喝了 · 晚上 · 睡觉"],["我们打车回去吧。","Chúng ta bắt taxi về nhà đi.","打车 · 回去"],["这里离家很近，还是走路吧。","Ở đây cách nhà rất gần, hay là đi bộ đi.","离家 · 很近 · 走路"],["要走多长时间？","Đi bộ mất bao lâu?","走 · 多长时间"],["走半个多小时就到了。","Đi bộ hơn nửa tiếng là đến.","半个多小时 · 到了"],["每天上下班都坐车，今天运动运动吧。","Ngày nào đi làm cũng ngồi xe, hôm nay vận động một chút đi.","上下班 · 坐车 · 运动"],["这周刘明休息，我下班后跟他去了一家商店。","Tuần này Lưu Minh được nghỉ, sau khi tan làm tôi cùng anh đi đến một cửa hàng.","这周 · 休息 · 商店"],["商店里边的衣服没有大商场里边的好看。","Quần áo trong cửa hàng không đẹp bằng quần áo trong trung tâm thương mại lớn.","商店 · 没有 · 好看"],["因为想运动运动，所以喝完东西，我们就走回家了。","Vì muốn vận động nên sau khi uống xong, chúng tôi đi bộ về nhà.","因为 · 运动 · 走回家"]],"10":[["小明，你们明天开学，你准备好了吗？","Tiểu Minh, ngày mai các con khai giảng, con đã chuẩn bị xong chưa?","明天 · 开学 · 准备"],["明天就开学啊？爸爸，我的书包你看见了吗？","Ngày mai đã khai giảng rồi sao? Bố ơi, cặp sách của con bố có nhìn thấy không?","就开学 · 书包 · 看见"],["书包在门后面。","Cặp sách ở sau cửa.","书包 · 门 · 后面"],["书在哪儿呢？笔呢？","Sách ở đâu? Bút đâu?","书 · 笔 · 呢"],["书在床上，笔在桌子上。","Sách ở trên giường, bút ở trên bàn.","床上 · 笔 · 桌子上"],["太好了！现在都准备好了。","Tốt quá! Bây giờ đều đã chuẩn bị xong rồi.","太好 · 现在 · 准备好"],["这次爸爸帮你，下次你自己准备，好不好？","Lần này bố giúp con, lần sau con tự chuẩn bị, được không?","帮 · 下次 · 自己"],["小雪，你在做什么呢？","Tiểu Tuyết, con đang làm gì đấy?","在做 · 什么 · 呢"],["明天考试，我在看书呢。","Ngày mai thi, con đang đọc sách đây.","明天 · 考试 · 看书"],["这些词要好好看看。","Những từ này phải xem lại thật kỹ.","词 · 好好 · 看看"],["我看过了，意思也都懂了。","Con đã xem qua rồi, nghĩa cũng hiểu hết.","看过 · 意思 · 懂"],["你的本子呢？本子上做错的题也要看一看。","Vở của con đâu? Những bài làm sai trong vở cũng phải xem lại.","本子 · 做错 · 题"],["妈妈，是您准备考试还是我准备考试？","Mẹ ơi, là mẹ chuẩn bị thi hay là con chuẩn bị thi?","还是 · 准备 · 考试"],["妈妈，我回来了！","Mẹ ơi, con về rồi!","妈妈 · 回来"],["我买了奶茶，就在桌子上，自己去拿吧。","Mẹ đã mua trà sữa, để ngay trên bàn, con tự đi lấy đi.","奶茶 · 桌子 · 自己"],["今天考试考得怎么样？","Hôm nay thi thế nào?","考试 · 考得 · 怎么样"],["我觉得比上次好。","Con thấy làm tốt hơn lần trước.","觉得 · 比 · 上次"],["饭菜快要做好了，你叫弟弟一起去洗手吧。","Cơm sắp nấu xong rồi, con gọi em trai cùng đi rửa tay đi.","快要 · 做好 · 洗手"],["妈妈，我是第一名，姐姐还没洗完呢。","Mẹ ơi, con rửa xong đầu tiên, chị gái còn chưa rửa xong.","第一名 · 还没 · 洗完"],["你洗得真快啊！","Con rửa tay nhanh thật đấy!","洗得 · 真 · 快"]],"11":[["我头疼，不太舒服。","Tôi đau đầu, không được khỏe lắm.","头疼 · 不舒服"],["你这几天经常头疼，去医院看看吧。","Mấy hôm nay bạn thường xuyên đau đầu, đi bệnh viện khám thử xem.","经常 · 头疼 · 医院"],["现在不能动，一动就疼。","Bây giờ không cử động được, cứ động là đau.","动 · 疼"],["那你在这儿坐着，我去开车。","Vậy bạn cứ ngồi ở đây, tôi đi lấy xe.","坐着 · 开车"],["现在路上车多，还下着雪。","Bây giờ trên đường nhiều xe, lại còn đang có tuyết.","路上 · 下着雪"],["我开慢一点儿。","Tôi lái chậm lại một chút.","慢 · 一点儿"],["王老师开着车呢，你找她有事吗？","Cô Vương đang lái xe, bạn tìm cô có việc gì không?","开着车 · 有事"],["今天雪这么大，你们开车去哪儿啊？","Hôm nay tuyết lớn thế, các bạn lái xe đi đâu vậy?","雪 · 开车 · 哪儿"],["去医院，我头有点儿疼。","Đi bệnh viện, tôi hơi đau đầu.","医院 · 头疼"],["李文，快请进！","Lý Văn, mau vào đi!","请进"],["家月，你怎么样了？头还疼吗？","Gia Nguyệt, bạn thế nào rồi? Đầu còn đau không?","怎么样 · 头疼"],["医生开了一些药，吃完就好多了。","Bác sĩ kê một ít thuốc, uống xong sẽ đỡ nhiều.","医生 · 药 · 好多了"],["身体不舒服时更要好好吃饭。","Khi cơ thể không khỏe càng phải ăn uống cho tốt.","身体 · 不舒服 · 好好吃饭"],["你最喜欢吃中国菜，我做几个中国菜吧。","Bạn thích ăn món Trung Quốc nhất, tôi làm vài món Trung Quốc nhé.","最喜欢 · 中国菜"],["我从药店买了点儿药，没去医院。","Tôi mua một ít thuốc ở hiệu thuốc, không đi bệnh viện.","药店 · 药 · 医院"],["王老师看我不舒服，就送我去医院了。","Cô Vương thấy tôi không khỏe nên đưa tôi đi bệnh viện.","不舒服 · 送 · 医院"],["从医院回来，李文也来看我了。","Từ bệnh viện về, Lý Văn cũng đến thăm tôi.","医院 · 回来 · 看"],["现在他们都回去了，我也要睡觉了。","Bây giờ họ đều đã về rồi, tôi cũng phải đi ngủ đây.","回去 · 睡觉"],["谢谢王老师。","Cảm ơn cô Vương.","谢谢 · 王老师"],["那我一会儿去看看你。","Vậy lát nữa tôi đến thăm bạn.","一会儿 · 看看"]],"12":[["我这里比北京冷多了，外边还正下着雪呢！","Chỗ tôi lạnh hơn Bắc Kinh nhiều, bên ngoài vẫn đang có tuyết rơi đấy!","比 · 冷多了 · 下着雪"],["北京这几天虽然是晴天，但是有点儿冷。","Mấy hôm nay Bắc Kinh tuy trời nắng nhưng hơi lạnh.","晴天 · 有点儿冷"],["没什么事，就想跟您说说话。","Không có việc gì, chỉ muốn nói chuyện với cô thôi.","没什么事 · 说说话"],["下午有课。您那里天气怎么样？","Buổi chiều có tiết. Chỗ cô thời tiết thế nào ạ?","下午 · 天气 · 怎么样"],["昨天比今天下得大。","Hôm qua tuyết rơi lớn hơn hôm nay.","昨天 · 比 · 下得大"],["天气不好，你去外面的时候多穿点儿衣服。","Thời tiết không tốt, khi ra ngoài bạn mặc thêm áo nhé.","外面 · 多穿 · 衣服"],["这几天我在网上上课，没出去过。","Mấy hôm nay tôi học online, chưa ra ngoài lần nào.","网上 · 上课 · 出去"],["有事记得给我打电话。","Có việc gì nhớ gọi điện cho tôi nhé.","有事 · 记得 · 打电话"],["现在不下雪了，我出去买点儿吃的。","Bây giờ hết tuyết rồi, tôi ra ngoài mua chút đồ ăn.","不下雪 · 出去 · 买"],["一次多买点儿，阴天下雪什么的就少出去吧。","Một lần mua nhiều chút, trời âm u hay có tuyết thì ít ra ngoài thôi.","阴天 · 下雪 · 少出去"],["今天天气不错，我们去跑步吧！","Hôm nay thời tiết đẹp, chúng ta đi chạy bộ nhé!","天气不错 · 跑步"],["你跑步跑得比我快，我们能一起跑吗？","Bạn chạy bộ nhanh hơn tôi, chúng ta có thể chạy cùng nhau không?","跑步 · 比我快 · 一起跑"],["我从小就经常跟爸爸跑步，跑步能让人快乐！","Tôi từ nhỏ đã thường xuyên chạy bộ cùng bố, chạy bộ làm người ta vui vẻ!","从小 · 经常 · 跑步"],["我现在坐地铁去找你，一会儿楼下见。","Bây giờ tôi đi tàu điện ngầm đến tìm bạn, lát nữa gặp nhau dưới lầu nhé.","地铁 · 楼下见"],["前几天天气不好，我没走路，每天坐两站地铁去学校。","Mấy hôm trước thời tiết không tốt, tôi không đi bộ, mỗi ngày đi hai trạm tàu điện ngầm đến trường.","天气不好 · 两站 · 地铁"],["今天是个大晴天，李文让我跟他去外面跑步。","Hôm nay là một ngày nắng to, Lý Văn rủ tôi ra ngoài chạy bộ cùng anh ấy.","大晴天 · 外面 · 跑步"],["他小时候经常跑步，跑得比我快，但是他会等我。","Hồi nhỏ anh ấy thường xuyên chạy bộ, chạy nhanh hơn tôi, nhưng anh ấy sẽ đợi tôi.","小时候 · 跑得比我快 · 等我"],["跟李文一起跑步，我好高兴啊！","Chạy bộ cùng Lý Văn, tôi vui lắm!","一起跑步 · 好高兴"],["喂，家月，是你啊！有什么事情吗？","A lô, Gia Nguyệt, là bạn à! Có việc gì không?","事情"],["你真爱跑步啊！","Bạn thật thích chạy bộ!","真爱 · 跑步"]],"13":[["时间过得真快啊！新年就要到了。","Thời gian trôi nhanh thật! Năm mới sắp đến rồi.","时间 · 新年"],["这一年王老师教我们中文，每天工作都很累。","Năm nay cô Vương dạy chúng tôi tiếng Trung, mỗi ngày làm việc đều rất mệt.","教 · 中文 · 累"],["她教得很好。因为她，我们都非常爱上中文课。","Cô dạy rất hay. Nhờ có cô, chúng tôi đều rất yêu thích giờ học tiếng Trung.","教得很好 · 爱上 · 中文课"],["我们给她准备个新年礼物吧。","Chúng ta chuẩn bị cho cô một món quà năm mới nhé.","准备 · 新年礼物"],["王老师喜欢花，就送给她花吧。","Cô Vương thích hoa, tặng hoa cho cô nhé.","喜欢 · 花 · 送给"],["那我们去花店看看，希望花店还有漂亮的花。","Vậy chúng ta đến tiệm hoa xem thử, mong là tiệm hoa vẫn còn hoa đẹp.","花店 · 希望 · 漂亮的花"],["王老师，今天的词比昨天多了十个。","Cô Vương ơi, từ hôm nay nhiều hơn hôm qua mười từ.","词 · 比 · 多了十个"],["现在我来说，你们在本子上面写。","Bây giờ tôi đọc, các bạn viết lên vở nhé.","本子 · 上面 · 写"],["“洗手间”的“间”字写错了，它的里面是“日”，不是“口”。","Chữ 间 trong từ nhà vệ sinh viết sai rồi, bên trong của nó là chữ 日, không phải chữ 口.","洗手间 · 里面 · 日"],["“日”比“口”多一笔，写“口”就是“问题”的“问”了。","Chữ 日 nhiều hơn chữ 口 một nét, viết chữ 口 thì thành chữ 问 trong từ vấn đề rồi.","多一笔 · 问题 · 问"],["家月，你觉得这个本子怎么样？","Gia Nguyệt, bạn thấy quyển vở này thế nào?","觉得 · 本子 · 怎么样"],["比我们一起买的那个本子贵一点儿。","Đắt hơn quyển vở chúng ta cùng mua một chút.","比 · 贵一点儿"],["这么漂亮的本子，不可能贵一点儿吧？","Quyển vở đẹp thế này, không thể chỉ đắt hơn một chút chứ?","漂亮 · 不可能 · 贵一点儿"],["我是上网买的，真没那么贵。","Tôi mua trên mạng, thật sự không đắt như thế đâu.","上网 · 没那么贵"],["我买了两个，送你一个。","Tôi mua hai quyển, tặng bạn một quyển.","买 · 送"],["咖啡杯吧，我最喜欢喝咖啡了。","Cốc cà phê nhé, tôi thích uống cà phê nhất.","咖啡杯 · 最喜欢 · 咖啡"],["好，那样我们就都有新年礼物了！","Được, như vậy chúng ta đều có quà năm mới rồi!","那样 · 新年礼物"],["新年就要到了，安妮送给我一个新本子。","Năm mới sắp đến rồi, An Ni tặng tôi một quyển vở mới.","新年 · 送给 · 新本子"],["她告诉我是在网上买的，比我的本子贵一点儿。","Cô ấy nói với tôi là mua trên mạng, đắt hơn quyển vở của tôi một chút.","告诉 · 上网 · 贵一点儿"],["我们班同学也送了王老师漂亮的花，希望她高高兴兴地过个新年。","Các bạn cùng lớp chúng tôi cũng tặng cô Vương hoa đẹp, mong cô vui vẻ đón một năm mới.","班 · 送 · 漂亮的花 · 新年"]],"14":[["王老师，你家楼下站着一个人。","Cô Vương ơi, dưới lầu nhà cô có một người đang đứng.","楼下 · 站着 · 一个人"],["那个人穿着黑色的裤子，手里还拿着一个黑色的包。","Người đó mặc quần màu đen, trên tay còn cầm một cái túi màu đen.","穿着 · 黑色 · 包"],["我看见那个人了，他是我男朋友。","Tôi nhìn thấy người đó rồi, anh ấy là bạn trai tôi.","看见 · 男朋友"],["那我们快过去吧。","Vậy chúng ta mau qua đó đi.","快 · 过去"],["同乐，真是你啊！","Đồng Lạc, đúng là bạn thật!","真是 · 你"],["上次打电话，你说有时间过来看我，没想到这么快就来了！","Lần trước gọi điện, bạn nói có thời gian sẽ qua thăm tôi, không ngờ đến nhanh thế!","打电话 · 有时间 · 过来"],["就要过年了，你一个人在这儿多没意思啊。","Sắp đến Tết rồi, bạn một mình ở đây chán biết bao.","过年 · 一个人 · 多没意思"],["你能来，我太高兴了！","Bạn đến được, tôi vui quá!","能来 · 太高兴"],["一飞，你旁边这位是？","Nhất Phi, người bên cạnh bạn đây là ai?","旁边 · 这位"],["这是李文，他在我们学校学医。","Đây là Lý Văn, anh ấy học y ở trường chúng tôi.","学校 · 学医"],["这是我男朋友杨同乐。","Đây là bạn trai tôi, Dương Đồng Lạc.","男朋友 · 杨同乐"],["李文，很高兴认识你！","Lý Văn, rất vui được gặp bạn!","高兴 · 认识"],["我家就在前面那个楼，有时间来玩。","Nhà tôi ở ngay tòa nhà phía trước kia, có thời gian thì qua chơi.","前面 · 楼 · 有时间"],["一飞，你住的房子真不错，很大，离学校也不远。","Nhất Phi, căn nhà bạn ở thật tốt, rất to, lại không xa trường.","房子 · 不错 · 离学校"],["我楼下还住着一家中国人，他们人很好。","Dưới lầu nhà tôi còn có một gia đình người Trung Quốc ở, họ rất tốt.","楼下 · 住着 · 中国人"],["这样你有事情就可以找他们帮忙。","Như vậy có việc gì bạn có thể nhờ họ giúp.","有事情 · 帮忙"],["我也帮他们家的小孩儿学中文。","Tôi cũng giúp đứa trẻ nhà họ học tiếng Trung.","帮 · 小孩儿 · 中文"],["我记得你跟我说过，是个女孩儿，学得也很好。","Tôi nhớ bạn từng nói với tôi, đó là một bé gái, học cũng rất tốt.","记得 · 女孩儿 · 学得很好"],["她经常跑上来找我玩。","Em ấy thường xuyên chạy lên tìm tôi chơi.","经常 · 跑上来 · 找我玩"],["你问问他们什么时候有时间，我请他们吃个饭。","Bạn hỏi họ khi nào rảnh, tôi mời họ ăn một bữa cơm.","什么时候 · 有时间 · 请吃饭"]],"15":[["考试就要开始了，请大家写上姓名，写好后就可以做题了。","Kỳ thi sắp bắt đầu, mời mọi người viết họ tên lên, viết xong là có thể làm bài.","考试 · 姓名 · 做题"],["老师，我做完了。","Cô ơi, em làm xong rồi.","做完"],["对了，你们考完试想做什么？","À đúng rồi, thi xong các bạn muốn làm gì?","考完试 · 想做"],["我很想去中国，虽然去过一次，但是很想再去一次。","Tôi rất muốn đến Trung Quốc, tuy đã đến một lần rồi nhưng rất muốn đến thêm một lần nữa.","去过一次 · 再去一次"],["不错，到中国后你就可以经常说中文了。","Tốt đấy, đến Trung Quốc rồi bạn có thể thường xuyên nói tiếng Trung.","到中国 · 经常 · 说中文"],["考完试了，我现在可以出国旅游了。","Thi xong rồi, bây giờ tôi có thể ra nước ngoài du lịch.","考完试 · 出国 · 旅游"],["我要再去一次北京。","Tôi muốn đến Bắc Kinh thêm một lần nữa.","再去一次 · 北京"],["因为我想再吃一次烤鸭，再喝一次奶茶。","Vì tôi muốn ăn vịt quay thêm một lần nữa, uống trà sữa thêm một lần nữa.","再吃一次 · 再喝一次"],["我还在网上买好颐和园的门票了呢。","Tôi còn mua sẵn vé vào Di Hòa Viên trên mạng rồi.","网上 · 颐和园 · 门票"],["我的高中同学就在颐和园上班。","Bạn học cấp ba của tôi làm việc ở Di Hòa Viên.","高中同学 · 颐和园 · 上班"],["太好了！出门旅游，多个朋友多条路。","Tuyệt quá! Đi du lịch, càng nhiều bạn càng nhiều đường.","出门旅游 · 朋友 · 路"],["李文，你有一年没回国了吧？","Lý Văn, bạn đã một năm không về nước rồi phải không?","一年 · 没回国"],["不到一年。我六月的时候回去了一次。","Chưa đến một năm. Tháng sáu tôi về một lần rồi.","不到一年 · 六月 · 回去一次"],["还是我送你去的机场呢。","Vẫn là tôi đưa bạn ra sân bay mà.","送 · 机场"],["我记得你那次的机票很便宜。","Tôi nhớ vé máy bay lần đó của bạn rất rẻ.","记得 · 机票 · 便宜"],["没错，可能因为那个时候去北京的人不多吧。","Đúng vậy, có lẽ vì lúc đó không nhiều người đến Bắc Kinh.","可能 · 那个时候 · 北京"],["这次的机票虽然有点儿贵，但想到就要飞北京了，我还是很高兴的。","Vé máy bay lần này tuy hơi đắt, nhưng nghĩ đến việc sắp bay đến Bắc Kinh, tôi vẫn rất vui.","机票 · 有点儿贵 · 飞北京"],["现在有半年多没回去了，我有点儿想家。","Bây giờ đã hơn nửa năm không về, tôi hơi nhớ nhà.","半年多 · 没回去 · 想家"],["就要过年了，我要回家过年。","Sắp đến Tết rồi, tôi muốn về nhà đón Tết.","过年 · 回家"],["家月说我们好像小鸟，一起飞到北京，再一起飞回这里。","Gia Nguyệt nói chúng tôi giống như những chú chim nhỏ, cùng bay đến Bắc Kinh, rồi cùng bay về đây.","好像 · 小鸟 · 飞"]]};
